// =====================================================================
// W34 d1：到期中心的本质 —— 不是「轮询各面私有库」，而是各面来登记。
//
// 今天要把两种做法的差别跑出来：
//   做法 A（错的直觉）：calendar 每 10 分钟去 finance / homeos 的表里
//                        轮询「有没有新的 due_at」，谁快到期就建提醒。
//   做法 B（PRD 16.4）  ：各业务面在自己写事务内「来登记」，
//                        calendar 只读自己 calendar_* 三张表。
//
// 本机没有 Postgres，所以用内存 slice 模拟三张表。
// 关键不是「模拟得像」，而是把两种做法在「依赖数 / 查询次数 /
// 新增一个业务面要改几处 / 越权面」四个维度上的差别打印出来。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func sub(s string) {
	fmt.Printf("\n── %s\n", s)
}

// ---- 三张表：业务面私有表 + 到期中心自有表 ----

type Bill struct {
	ID      string
	Family  string
	Title   string
	DueAt   string // 固定字符串，避免 time 输出不确定
	Status  string // unpaid / paid
	Deleted bool
}

type Member struct {
	ID     string
	Family string
	Name   string
}

type CalReminder struct {
	ID       string
	FromFace string // 来源面：finance / homeos
	Title    string
	DueAt    string
	Active   bool
}

type DB struct {
	bills     []Bill
	members   []Member
	reminders []CalReminder
}

func newDB() *DB {
	return &DB{
		bills: []Bill{
			{ID: "bill-001", Family: "fam-001", Title: "房贷 3 月期", DueAt: "2026-03-05", Status: "unpaid"},
			{ID: "bill-002", Family: "fam-001", Title: "物业费 Q1", DueAt: "2026-03-20", Status: "unpaid"},
			{ID: "bill-003", Family: "fam-002", Title: "房租", DueAt: "2026-03-02", Status: "unpaid"},
			{ID: "bill-004", Family: "fam-002", Title: "保险费", DueAt: "2026-06-18", Status: "unpaid"},
		},
		members: []Member{
			{ID: "mem-001", Family: "fam-001", Name: "爸爸"},
			{ID: "mem-002", Family: "fam-001", Name: "妈妈"},
			{ID: "mem-003", Family: "fam-002", Name: "爷爷"},
		},
	}
}

// =====================================================================
// 做法 A：轮询。calendar 主动去读别人的私有表。
// =====================================================================

// pollCycle 模拟「一轮轮询」。返回本轮读到的行数与违规的跨 schema 访问数。
func pollCycle(db *DB) (found, violations int) {
	// ① 跨 schema SELECT finance.finance_bill —— 违反铁律：模块间禁直查表
	violations++
	for _, b := range db.bills {
		if b.Deleted {
			continue
		}
		if b.DueAt <= "2026-03-10" { // 「还有 7 天内到期」的轮询条件
			found++
		}
	}
	// ② 想给「谁」发提醒，还得查 homeos.household_member —— 又一次跨 schema
	violations++
	for range db.members {
	}
	// ③ 重复出现的来源对象要靠「我见过哪些 id」去重，而这个「见过」的表放哪儿？
	//    放 calendar 自己的表 = 又一份影子数据；放 finance = 轮询方根本无权写。
	violations++
	return found, violations
}

// =====================================================================
// 做法 B：登记。各面在写事务内调 platform 接口登记。
// =====================================================================

type Registry struct{ db *DB }

// Register 模拟 svc-calendar 收到一条 due.registered 意图。
// 只写 db.reminders（自己那张表），一行都不碰 finance / homeos。
func (r *Registry) Register(from, sourceID, title, dueAt string) {
	r.db.reminders = append(r.db.reminders, CalReminder{
		ID:       "rem-" + sourceID,
		FromFace: from,
		Title:    title,
		DueAt:    dueAt,
		Active:   true,
	})
}

func main() {
	db := newDB()
	reg := &Registry{db: db}

	hdr("背景：三张表分属三个服务，谁都碰不到谁的表")

	sub("tech-plan §1.1 的硬边界")
	fmt.Println("  schema finance   账号 finance_app    ← svc-finance")
	fmt.Println("  schema calendar  账号 calendar_app   ← svc-calendar")
	fmt.Println("  schema homeos    账号 homeos_app     ← svc-homeos")
	fmt.Println("  红线：禁止跨 schema SQL、只读视图、共用账号（tech-plan §10.3 第 1 条）")
	fmt.Println("  也就是说 svc-calendar 用自己的连接凭证，**物理上** SELECT 不了 finance.finance_bill。")

	// ---- 跑做法 A ----
	hdr("做法 A（错的直觉）：calendar 每 10 分钟轮询各面私有表")

	const rounds = 6 // 模拟 1 小时的轮询（每 10 分钟一轮）
	totalFound, totalViolations := 0, 0
	for i := 1; i <= rounds; i++ {
		f, v := pollCycle(db)
		totalFound += f
		totalViolations += v
		fmt.Printf("  第 %d 轮（t=%02dmin）：查到 %d 条将到期，跨 schema 违规访问 %d 次\n",
			i, i*10, f, v)
	}
	sub("一轮下来的数字")
	fmt.Printf("  轮询 %d 轮，每轮跨 schema 违规 %d 次 → 合计 %d 次\n",
		rounds, totalViolations/rounds, totalViolations)
	fmt.Printf("  查到「将到期」%d 次，但 calendar 里真正需要的提醒：%d 条（重复 %d 次）\n",
		totalFound, 2, totalFound-2)
	fmt.Println("  问题 1：换个账号就能 SELECT，等于把红线从「架构约定」降级成「口头承诺」")
	fmt.Println("  问题 2：10 分钟一轮意味着到期当天最多晚 10 分钟才知道")
	fmt.Println("  问题 3：poller 必须在 calendar 里硬编码「finance.finance_bill.due_at 这个字段叫什么」")
	fmt.Println("          —— 加第二个业务面就要改 calendar 代码，calendar 变成知道所有业务细节的 god service")

	// ---- 跑做法 B ----
	hdr("做法 B（PRD 16.4）：各面来登记，calendar 只读自己的表")

	fmt.Println("  用户在 finance 建账单，finance 在**自己**的写事务里调 platform 接口：")
	for _, b := range db.bills {
		reg.Register("finance", b.ID, b.Title, b.DueAt)
		fmt.Printf("    finance 登记  %-9s %-10s due_at=%s\n", b.ID, b.Title, b.DueAt)
	}
	fmt.Println("  用户邀请成员，homeos 在**自己**的写事务里调同一个接口：")
	for _, m := range db.members {
		reg.Register("homeos", m.ID, "成员入职欢迎："+m.Name, "2026-03-01")
		fmt.Printf("    homeos  登记  %-9s %s\n", m.ID, m.Name)
	}

	sub("calendar 到期中心现在只需要问自己一张表")
	fmt.Println("  SELECT * FROM calendar.calendar_reminder WHERE active ORDER BY due_at;")
	for _, r := range db.reminders {
		fmt.Printf("    %-9s <- %-8s %-18s due_at=%s\n", r.ID, r.FromFace, r.Title, r.DueAt)
	}
	fmt.Printf("  一共 %d 条，跨 schema 访问 0 次。\n", len(db.reminders))

	hdr("逐项对比（这是今天真正要带走的东西）")

	type row struct {
		dim      string
		poll     string
		register string
	}
	rows := []row{
		{"calendar 需要连几个库", "finance + homeos（违规）", "只要 calendar 自己（1 个）"},
		{"一轮的跨 schema 访问", "3 次 × 轮询轮数", "0 次"},
		{"到期识别延迟", "最多一个轮询周期", "提交那一刻就登记（最终一致）"},
		{"加一个新业务面", "改 calendar 代码 + 加一次跨 schema SELECT", "新面自己调 platform 接口，calendar 零改动"},
		{"业务面被删/改期时", "poller 察觉不到，旧提醒留在到期中心变成幽灵", "业务面发 due.revoked 撤销（d8 讲）"},
		{"越权面", "共用账号 / 只读视图 / DBLink，红线直接破", "结构上不可能发生"},
	}
	fmt.Printf("  %-22s %-34s %s\n", "维度", "做法 A 轮询", "做法 B 登记")
	fmt.Println("  " + strings.Repeat("-", 96))
	for _, r := range rows {
		fmt.Printf("  %-22s %-34s %s\n", r.dim, r.poll, r.register)
	}

	hdr("一句话结论")
	fmt.Println("  「到期中心聚合各面数据」这句话，容易被读成 calendar 去读各面的表。")
	fmt.Println("  PRD 16.4 的原意是反过来的：**各面把自己带时间语义的对象送进来登记**。")
	fmt.Println("  前一种读法要破坏 schema 边界，后一种读法让边界成为天然保护。")
	fmt.Println()
	fmt.Println("  第二个区别同样重要：登记是「推」，触发归 calendar 一个地方。")
	fmt.Println("  如果是轮询，谁来「到点提醒」就成了问题 —— 每个业务面都得自己起定时器，")
	fmt.Println("  多套定时器 = 多套真相 + 重复通知（d13 会真跑出重复通知）。")

	fmt.Println("\n=== W34 d1 到此结束 ===")
	fmt.Println("明天逐个拆注册契约的 10 个字段：每一个都在解决一个具体的「不做会怎样」。")
}

// =====================================================================
// W34 d2：注册契约的字段映射 —— 每一个字段防住一个具体的「不做会怎样」。
//
// PRD 16.4 的注册字段映射（统一格式）：
//   { source_system, source_id, source_family_id, title,
//     due_at|start_at|end_at, participants[], repeat, priority,
//     done_returns_to, visibility }
//
// 今天不背字段名。今天做的是：对每一个字段，先造一个「把它置空/置错」的
// 反例，然后真跑一遍 calendar 收到这条注册之后会发生什么，看它错在哪。
// 字段存在不是因为「PRD 写了」，是因为缺了它会产生一种具体的错误。
//
// 本机没有 Postgres，用内存结构模拟 calendar_reminder 的约束。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// Registration 就是一个业务面发给 calendar 的注册意图。
// Go 的 struct 与 TS 的 interface 的最大差别：struct 是**值语义**，
// 赋值即复制 —— 传进函数之后函数里改它，外面看不到。
// TS 的对象是引用语义，函数里改属性外面看得见。
type Registration struct {
	SourceSystem   string   // 来源面 code：finance / homeos
	SourceID       string   // 来源对象 id
	SourceFamilyID string   // 来源对象所属家庭
	Title          string   // 到期中心里显示的标题
	DueAt          string   // 到期时刻（Reminder/CalendarEvent 有；Todo 可空）
	Participants   []string // 参与人（成员 id）
	Repeat         string   // none / daily / weekly / monthly
	Priority       string   // low / normal / high
	DoneReturnsTo  string   // ★ 完成回写的目标：{source_system}:{source_id}:{action}
	Visibility     string   // family / private
	Kind           string   // reminder / event / todo（注册类型）
}

func (r Registration) validate() []string {
	var errs []string
	if r.SourceSystem == "" {
		errs = append(errs, "source_system 为空 → 撤销时不知道找谁，回写也无处可去")
	}
	if r.SourceID == "" {
		errs = append(errs, "source_id 为空 → 幂等键失去一半，重复注册挡不住")
	}
	if r.SourceFamilyID == "" {
		errs = append(errs, "source_family_id 为空 → 提醒会挂到错误的家庭下，多租户立刻泄露")
	}
	if r.Title == "" {
		errs = append(errs, "title 为空 → 用户在到期中心看到一行空白，不知道该做什么")
	}
	if r.DueAt == "" && r.Kind != "todo" {
		errs = append(errs, "due_at 为空 → 定时器无从排期，这条提醒永远不触发")
	}
	if len(r.Participants) == 0 {
		errs = append(errs, "participants 为空 → 到点了不知道推给谁，通知链路断在第一跳")
	}
	switch r.Repeat {
	case "none", "daily", "weekly", "monthly":
	default:
		errs = append(errs, fmt.Sprintf("repeat=%q 不在枚举内 → 周期规则解析器返回零值，这条提醒静默失效", r.Repeat))
	}
	switch r.Priority {
	case "low", "normal", "high":
	default:
		errs = append(errs, fmt.Sprintf("priority=%q 不在枚举内 → 排序退化成零值，紧急的账单和不急的混在一起", r.Priority))
	}
	if r.DoneReturnsTo == "" {
		errs = append(errs, "★ done_returns_to 为空 → 用户点完成之后业务面永远不知道，回写丢失（PRD：视为缺陷）")
	}
	switch r.Visibility {
	case "family", "private":
	default:
		errs = append(errs, fmt.Sprintf("visibility=%q 不在枚举内 → 到期中心是家庭共享的，泄露面最大的一块", r.Visibility))
	}
	return errs
}

// ---- calendar 侧的校验结果 ----

func acceptOrReject(r Registration) (string, string) {
	if errs := r.validate(); len(errs) > 0 {
		return "REJECT", strings.Join(errs, "\n            ")
	}
	return "ACCEPT", ""
}

// =====================================================================
// 十个字段逐个「拿走它」
// =====================================================================

type fieldCase struct {
	name   string
	breaks string
	mutate func(*Registration)
	// 为什么它必须存在（一句话）
	reason string
}

func main() {
	// 一条完整正确的注册
	good := Registration{
		SourceSystem:   "finance",
		SourceID:       "bill-001",
		SourceFamilyID: "fam-001",
		Title:          "房贷 3 月期",
		DueAt:          "2026-03-05T09:00:00+08:00",
		Participants:   []string{"mem-001", "mem-002"},
		Repeat:         "monthly",
		Priority:       "high",
		DoneReturnsTo:  "finance:bill-001:mark_paid",
		Visibility:     "family",
		Kind:           "reminder",
	}

	hdr("基准：一条完整的注册意图（finance 的 Bill.due_at）")
	fmt.Printf("  %-20s %s\n", "source_system", good.SourceSystem)
	fmt.Printf("  %-20s %s\n", "source_id", good.SourceID)
	fmt.Printf("  %-20s %s\n", "source_family_id", good.SourceFamilyID)
	fmt.Printf("  %-20s %s\n", "title", good.Title)
	fmt.Printf("  %-20s %s\n", "due_at", good.DueAt)
	fmt.Printf("  %-20s %v\n", "participants[]", good.Participants)
	fmt.Printf("  %-20s %s\n", "repeat", good.Repeat)
	fmt.Printf("  %-20s %s\n", "priority", good.Priority)
	fmt.Printf("  %-20s %s   ← ★\n", "done_returns_to", good.DoneReturnsTo)
	fmt.Printf("  %-20s %s\n", "visibility", good.Visibility)
	fmt.Printf("  %-20s %s\n", "kind", good.Kind)
	st, _ := acceptOrReject(good)
	fmt.Printf("\n  calendar 侧判定：%s\n", st)

	// ---- 逐个拿走 ----
	hdr("逐个拿走一个字段，看 calendar 侧会发生什么")

	cases := []fieldCase{
		{"source_system", "撤销事件发不出去；完成回写不知道回哪个面；幂等键少一维",
			func(r *Registration) { r.SourceSystem = "" },
			"注销「这条注册是谁登记的」这一事实。没有它，去重、回写、撤销三件事全部失去主语。"},
		{"source_id", "同一张账单被登记两次会落两条提醒；回写找不到对象",
			func(r *Registration) { r.SourceID = "" },
			"来源对象的身份。它是「跨面引用」用的 —— 只存 id 不存副本（tech-plan §7.1 方式③）。"},
		{"source_family_id", "提醒挂到错误的家庭下；孩子打开 App 看到父母的账单",
			func(r *Registration) { r.SourceFamilyID = "" },
			"多租户的唯一凭据。S5 讲过：表带 family_id ≠ 查询带 family_id。跨面登记时这一列是唯一带过来的隔离信息。"},
		{"title", "到期中心出现一行空白",
			func(r *Registration) { r.Title = "" },
			"到期中心是给别人看的界面。它不能显示 finance 的对象名，必须是一句人能读的话。"},
		{"due_at", "定时器无从排期，这条提醒永远不触发",
			func(r *Registration) { r.DueAt = "" },
			"「到期」这个词的全部含义。带上时区，因为注册方和 calendar 不在同一台机器（d5 会真跑出时区事故）。"},
		{"participants[]", "到点了不知道推给谁",
			func(r *Registration) { r.Participants = nil },
			"通知链路的收件人。homeos 消费 reminder.fired 后靠它落 Notification（分型 reminder）。"},
		{"repeat", "周期规则解析器返回零值，提醒静默失效",
			func(r *Registration) { r.Repeat = "每月" },
			"周期归属到期中心。这里只放**枚举**，不放 iCalendar RRULE 字符串 —— 那是 calendar 内部的表示，不该泄漏到契约上。"},
		{"priority", "紧急的账单和不急的混在一条列表里",
			func(r *Registration) { r.Priority = "very-high" },
			"排序。写枚举而不是整数，因为整数会漂移（有人写 10 有人写 100），枚举在 Go 里就是 string，非法值当场拒绝。"},
		{"done_returns_to", "★ 用户点完成之后业务面永远不知道，回写丢失",
			func(r *Registration) { r.DoneReturnsTo = "" },
			"这条单独拎出来讲。完成回写是「calendar 点一下 → finance 的 Bill.status 变 paid」的**方向声明**。没有它，calendar 无从知道要把结果送到哪（d4 整天讲这个）。"},
		{"visibility", "到期中心是家庭共享的，这是泄露面最大的一块",
			func(r *Registration) { r.Visibility = "public" },
			"到期中心是聚合视图，默认家庭可见；private 用于个人事项（如某人的体检）。它只影响读，不影响触发。"},
	}

	for i, c := range cases {
		r := good // Go struct 赋值是**复制**，所以改 r 不会污染 good
		c.mutate(&r)
		st, msg := acceptOrReject(r)
		fmt.Printf("\n  [%d/%d] 拿走 %s\n", i+1, len(cases), c.name)
		fmt.Printf("        为什么它存在：%s\n", c.reason)
		fmt.Printf("        不做的后果：%s\n", c.breaks)
		fmt.Printf("        calendar 判定：%s\n", st)
		if msg != "" {
			fmt.Printf("        原因        ：%s\n", msg)
		}
	}

	// ---- 枚举字段为什么用 string 而不是 int ----
	hdr("枚举字段为什么是 string 而不是整数")
	fmt.Println("  TS 里的直觉：priority 用 enum 或 0/1/2 数字。")
	fmt.Println("  Go 里的选择：契约字段用 string 常量，因为 ——")
	fmt.Println("    ① 跨进程传的就是字节，数字的含义会漂移（有人写 10 有人写 100，跨服务没有类型检查）")
	fmt.Println("    ② 契约变更可见：多一个 \"urgent\" 会立刻被上面的 validate 挡下来，而不是静默落到 default 分支")
	fmt.Println("    ③ 可读：落到事件信封的 JSON 里，\"priority\":\"high\" 比 \"priority\":2 更能定位问题")
	fmt.Println("  Go 里对应的强类型写法（推荐，但本项目为了契约可读性用字符串常量 + 校验）：")
	type Priority int
	const (
		PrioLow Priority = iota
		PrioNormal
		PrioHigh
	)
	fmt.Printf("    iota 版：low=%d normal=%d high=%d（注意 iota 从 0 开始，0 是零值=low，忘赋值就是 low）\n",
		PrioLow, PrioNormal, PrioHigh)
	fmt.Println("    ⚠ 这是 iota 的经典坑：如果你给 PrioNormal 显式赋值 5，后面的 PrioHigh 才是 6，")
	fmt.Println("      而如果漏了赋值，零值恰好等于第一个常量 —— 一个没设的字段悄悄变成 low，永远查不出来。")

	// ---- 必填 vs 可空 ----
	hdr("哪些字段必填、哪些可空")
	type req struct {
		field string
		must  string
		zero  string
	}
	reqs := []req{
		{"source_system", "必填", "空串就找不到主语"},
		{"source_id", "必填", "幂等键失效"},
		{"source_family_id", "必填", "多租户立刻泄露"},
		{"title", "必填", "界面出现空白行"},
		{"due_at", "Todo 类型可空", "待办本来就没有到期时刻"},
		{"participants[]", "必填（可空数组但不许为 nil）", "收件人缺失"},
		{"repeat", "必填（none 表示不重复）", "必须显式声明，不能靠「空=不重复」"},
		{"priority", "必填（normal 是默认值但要显式传）", "不传就用 default，正常"},
		{"done_returns_to", "必填", "★ 回写丢失，PRD 明确视为缺陷"},
		{"visibility", "必填", "家庭共享的视图"},
	}
	fmt.Printf("  %-20s %-36s %s\n", "字段", "约束", "违规后果")
	fmt.Println("  " + strings.Repeat("-", 88))
	for _, r := range reqs {
		fmt.Printf("  %-20s %-36s %s\n", r.field, r.must, r.zero)
	}
	fmt.Println()
	fmt.Println("  ⚠ Go 的坑：空数组 []string{} 与 nil slice 在上面都判 len()==0，")
	fmt.Println("    但 JSON 序列化时 nil 变成 null、[]string{} 变成 []。")
	fmt.Println("    对 TS 来说是同一个值（JSON.parse 后都是 Array），对 Go 来说是两个。")

	hdr("一句话总结")
	fmt.Println("  这十个字段不是「信息齐全」，是「十个独立的失败模式各有各的字段挡着」。")
	fmt.Println("  少一个字段 = 少一种失败模式的可见性 = 那个错误会跑到更远的地方才炸。")
	fmt.Println("  done_returns_to 是唯一一个「缺了不会立刻报错」的字段 —— 它要等到用户点完成那天才暴露。")

	fmt.Println("\n=== W34 d2 到此结束 ===")
	fmt.Println("明天拆幂等键：为什么恰好是 (source_system, source_id, kind) 这三个，换一个会怎样。")
}

// =====================================================================
// W34 d3：幂等键三元组 (source_system, source_id, kind)。
//
// 判据第 1 条：「重复注册同一对象 → 只有一条注册项」。
//
// 今天要把这句话真跑出来，并且回答「为什么恰好是这三个字段」。
// 方法：先写出正确的键，再逐个换成别的候选键，看它拦不住哪一种重复。
//
// 背景：at-least-once 投递（tech-plan §7.5）意味着**同一条注册意图
// 至少会被消费一次，可能被消费三次**。消费方必须自己去重。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// ---- calendar_reminder 的内存模拟，带唯一索引 ----

type Row struct {
	SourceSystem string
	SourceID     string
	Kind         string
	Title        string
	DueAt        string
	Priority     string
	FamilyID     string
}

type Store struct {
	rows  []Row
	dedup int // 被幂等键挡下的次数
}

func key3(s, id, kind string) string { return s + "|" + id + "|" + kind }

func (st *Store) Insert(r Row, keyFn func(Row) string) bool {
	k := keyFn(r)
	for _, x := range st.rows {
		if keyFn(x) == k {
			st.dedup++
			return false // 已存在，丢弃
		}
	}
	st.rows = append(st.rows, r)
	return true
}

// ---- 需要被挡住的三种「合法重复」和一种「合法并存」----

type delivery struct {
	why    string
	row    Row
	repeat bool // 这条是不是「第一次」的那条
}

// 三种重复各自对应的真实来源：
//  1. 网络重投：投递器 ack 丢了，消息重发
//  2. 消费端崩溃：处理完了但 ack 没写，重启后重投
//  3. 业务方自己重试：用户网络卡了点了两次「保存」，写了两条 due.registered
//
// 而 kind 不同的情况不是重复：Bill.due_at 在 PRD 16.4 里同时注册
// Reminder + CalendarEvent 两种类型 —— 同一个 source_id，两条注册项，**都必须存在**。
func main() {
	good := Row{"finance", "bill-001", "reminder", "房贷 3 月期", "2026-03-05T09:00:00+08:00", "high", "fam-001"}
	goodEvent := Row{"finance", "bill-001", "event", "房贷 3 月期（占位日程）", "2026-03-05T00:00:00+08:00", "high", "fam-001"}

	deliveries := []delivery{
		{"① 业务方首次登记（正常路径）", good, false},
		{"② 网络重投：投递器 ack 丢了", good, true},
		{"③ 消费端崩溃后重投：处理过了但没 ack", good, true},
		{"④ 业务方重试：用户点了两次「保存」", good, true},
		{"⑤ 同一次注册的不同 kind（PRD 16.4：Reminder + CalendarEvent）", goodEvent, false},
		{"⑥ 再重投一次那条 event", goodEvent, true},
	}

	hdr("① 正确的键：key3 = (source_system, source_id, kind)")
	st := &Store{}
	k3 := func(r Row) string { return key3(r.SourceSystem, r.SourceID, r.Kind) }
	for _, d := range deliveries {
		ok := st.Insert(d.row, k3)
		fmt.Printf("  %-56s 键=%-28s %s\n", d.why, k3(d.row),
			map[bool]string{true: "插入 ✅", false: "去重丢弃 ♻️"}[ok])
	}
	sort.Slice(st.rows, func(i, j int) bool {
		if st.rows[i].SourceID != st.rows[j].SourceID {
			return st.rows[i].SourceID < st.rows[j].SourceID
		}
		return st.rows[i].Kind < st.rows[j].Kind
	})
	fmt.Printf("\n  最终落库 %d 条（正确 = 2 条：一条 reminder 一条 event），被幂等键挡下 %d 次\n",
		len(st.rows), st.dedup)
	for _, r := range st.rows {
		fmt.Printf("    %-8s %-9s %-10s %s\n", r.SourceSystem, r.SourceID, r.Kind, r.DueAt)
	}

	// ---- 换键实验 ----
	hdr("② 换别的键会怎样：四个候选键，各自拦不住哪一种重复")

	type candidate struct {
		name string
		fn   func(Row) string
		// want = 这批投递跑完**应该**有几条
		want int
		note string
	}
	cands := []candidate{
		{"key1 = source_id", func(r Row) string { return r.SourceID }, 2,
			"不同面同 id 撞车：homeos 的注册被误判成重复丢弃（③ 真跑）"},
		{"key2 = (source_system, source_id)", func(r Row) string { return r.SourceSystem + "|" + r.SourceID }, 2,
			"挡不住 kind 不同的并存 → 那条 CalendarEvent 被吞掉，到期中心少一条日程占位"},
		{"key3 = (source_system, source_id, kind) ★", k3, 2,
			"三种重复全挡住、两种 kind 都并存。它是唯一同时满足这两个条件的组合"},
		{"key4 = (source_system, source_id, kind, due_at)", func(r Row) string {
			return key3(r.SourceSystem, r.SourceID, r.Kind) + "|" + r.DueAt
		}, 2,
			"行数对但语义错：改期后旧行留在库里变成幽灵（④ 真跑），且撤销+重注册会被去重掉"},
		{"key5 = (source_system, source_id, kind, family_id)", func(r Row) string {
			return key3(r.SourceSystem, r.SourceID, r.Kind) + "|" + r.FamilyID
		}, 2,
			"与 key3 逐条等价（family_id 恒由 source_system+source_id 决定）—— 冗余维度，不是更安全"},
	}

	for _, c := range cands {
		s := &Store{}
		for _, d := range deliveries {
			s.Insert(d.row, c.fn)
		}
		verdict := "✅ 行数对"
		if len(s.rows) != c.want {
			verdict = "❌ 行数错"
		}
		fmt.Printf("\n  %-52s 落库 %d 条（应为 %d）%s\n", c.name, len(s.rows), c.want, verdict)
		fmt.Printf("    问题：%s\n", c.note)
	}
	fmt.Println()
	fmt.Println("  注意 key4/key5：行数与 key3 一样是 2，但那只是**这批投递**看起来对。")
	fmt.Println("  换一批投递（改期、跨面）它们就露馅了 —— 这就是为什么不能只看单次输出。")

	// ---- 真跑出 key1 的撞车 ----
	hdr("③ key1 的真实事故：两个面各自造的 id 空间是独立的")

	otherFace := Row{"homeos", "bill-001", "reminder", "入职周年提醒", "2026-03-05T09:00:00+08:00", "normal", "fam-003"}
	fmt.Println("  finance 也有一个 id = bill-001（它的 Bill 表主键）")
	fmt.Println("  homeos  也有一个 id = bill-001（它的 homeos_rule 表主键）")
	fmt.Println("  两个 id 在各自 schema 里都是合法的 UUID 主键 —— UUID 全局唯一是**概率**上的，")
	fmt.Println("  而真实项目里更常见的是自增 id 或业务 id（bill-001 / 2026-03 房贷），空间必然重叠。")

	s1 := &Store{}
	kk := func(r Row) string { return r.SourceID } // key1
	s1.Insert(good, kk)
	ok := s1.Insert(otherFace, kk)
	fmt.Printf("\n  用 key1：homeos 的注册被 %s\n", map[bool]string{true: "插入成功", false: "**误判为重复而丢弃** ❌"}[ok])
	fmt.Println("  后果：homeos 的入职周年提醒永远不会出现在到期中心，而且**没有任何报错**")
	fmt.Println("        —— 因为去重逻辑「正常工作」了，它只是去错了对象。")

	s3 := &Store{}
	s3.Insert(good, k3)
	ok3 := s3.Insert(otherFace, k3)
	fmt.Printf("\n  用 key3：homeos 的注册 %s\n", map[bool]string{true: "插入成功 ✅", false: "被丢弃"}[ok3])

	// ---- 为什么 key3 里没有 due_at ----
	hdr("④ 为什么键里不能有 due_at：改期场景真跑")

	type billVersion struct {
		id    string
		dueAt string
		note  string
	}
	v1 := billVersion{"bill-001", "2026-03-05", "第一次登记"}
	v2 := billVersion{"bill-001", "2026-03-12", "用户改期到 3 月 12 日后重新登记"}

	for _, withDue := range []bool{true, false} {
		s := &Store{}
		var fn func(Row) string
		if withDue {
			fn = cands[3].fn
		} else {
			fn = k3
		}
		name := "key4（含 due_at）"
		if !withDue {
			name = "key3（不含 due_at）★"
		}
		s.Insert(Row{"finance", v1.id, "reminder", "房贷 3 月期", v1.dueAt, "high", "fam-001"}, fn)
		s.Insert(Row{"finance", v2.id, "reminder", "房贷 3 月期", v2.dueAt, "high", "fam-001"}, fn)
		fmt.Printf("\n  %s：改期后共落库 %d 条\n", name, len(s.rows))
		for _, r := range s.rows {
			mark := "  ← 幽灵：业务面已经没有 3 月 5 日这回事了"
			if r.DueAt == v2.dueAt {
				mark = "  ← 正确"
			}
			fmt.Printf("    due_at=%s%s\n", r.DueAt, mark)
		}
		if !withDue {
			fmt.Println("  key3 的语义：改期是**同一个对象的状态变化**，不是新对象。")
			fmt.Println("  所以它必须先撤销旧的（due.revoked，d8 讲）、再注册新的，两者共用同一个幂等键。")
			fmt.Println("  如果把 due_at 放进键里，撤销后重新注册就会因为旧行还在而被去重掉 ——")
			fmt.Println("  结果是新日期的提醒根本不存在。")
		}
	}

	// ---- Go 的坑 ----
	hdr("⑤ 这个键在 Go 里怎么落库")
	fmt.Println("  三种写法，只有第一种是对的：")
	fmt.Println()
	fmt.Println("  ❌ 写法一：存三个列，靠应用层查重")
	fmt.Println("     SELECT ... WHERE source_system=? AND source_id=? AND kind=?")
	fmt.Println("     然后 if len(rows)==0 { INSERT }")
	fmt.Println("     两个并发请求同时查到 0 行 → 都插入 → 去重失效（check-then-act 竞态）")
	fmt.Println()
	fmt.Println("  ✅ 写法二：唯一索引 + INSERT ... ON CONFLICT DO NOTHING")
	fmt.Println(`     CREATE UNIQUE INDEX uq_cal_rem_idem
	         ON calendar.calendar_reminder(source_system, source_id, kind);`)
	fmt.Println(`     INSERT INTO calendar.calendar_reminder (...) VALUES (...)
	         ON CONFLICT (source_system, source_id, kind) DO NOTHING;`)
	fmt.Println("     并发安全由数据库保证：第二个请求撞唯一索引，DO NOTHING 让它变成 0 行受影响")
	fmt.Println()
	fmt.Println("  ❌ 写法三：应用层 map 去重")
	fmt.Println("     这个在单进程内有效，但 svc-calendar 重启后 map 就空了；")
	fmt.Println("     而且多实例部署时每个实例一份 map，压根不共享。")

	// 真跑一下「并发 check-then-act」的失效
	fmt.Println()
	fmt.Println("  真跑一下写法一的竞态（两个 goroutine 同时注册同一张账单）：")
	store := &Store{}
	store.Insert(good, k3) // 已经有一行
	// 模拟两个 goroutine 都先查、各自看到「没有」再插
	a, b := store.rows, store.rows
	_ = a
	_ = b
	store.rows = append(store.rows, good) // 竞态结果：重复行
	fmt.Printf("    竞态发生后的行数：%d（应为 1，实际 2 → 去重失效 ❌）\n", len(store.rows))
	store2 := &Store{}
	store2.Insert(good, k3)
	store2.Insert(good, k3) // 唯一索引会挡住第二次
	fmt.Printf("    唯一索引方案的行数：%d（✓）\n", len(store2.rows))

	// ---- Go vs TS ----
	hdr("⑥ Go 与 TS 的差别：struct 是值语义")
	fmt.Println("  TS：const a = {n:1}; const b = a; b.n = 2; → a.n 也变成 2（引用）")
	fmt.Println("  Go：a := S{N:1}; b := a; b.N = 2;       → a.N 还是 1（复制）")
	fmt.Println("  这在今天有实际后果：构造幂等键时如果写成")
	fmt.Println("     func keyOf(r *Row) string { ... }  并在内部改 r")
	fmt.Println("  传值版本不会被外部看见，传指针版本会。构造「键」的函数应该是纯函数。")
	fmt.Println()
	fmt.Println("  ⚠ 另一个 Go 坑：map 的零值可用但并发写会 panic（concurrent map writes）。")
	fmt.Println("    上面的 Store 用 slice + 线性扫描，看起来慢但天然并发安全（只读）。")
	fmt.Println("    真上生产是唯一索引，不要用 map 在应用层兜。")

	fmt.Println("\n=== W34 d3 到此结束 ===")
	fmt.Println("明天讲 done_returns_to —— 十个字段里唯一一个「缺了不会立刻报错」的。")
}

// =====================================================================
// W34 d4：done_returns_to 为什么最重要。
//
// 十个注册字段里，只有它「缺了不会立刻报错」。
// 其他字段缺了，calendar 侧当场 REJECT（d2 跑过）；
// 它缺了，注册成功、提醒照常触发、通知照常下发 ——
// 直到有一天用户在到期中心点了「完成」，业务面那边毫无反应。
//
// PRD 16.4 原文：
//   「注册项被用户在到期中心完成 → 回写业务面对象状态
//     （done_returns_to 指定的回调），不回写视为缺陷。」
//
// 今天把这个「视为缺陷」真跑出来：
//   ① 有 done_returns_to  → 回写成功，Bill.status = paid
//   ② 没有 done_returns_to → 回写丢失，且系统自认为一切正常
//   ③ 回写失败的兜底链（d16 会展开）
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 业务面 finance 的内存状态
// =====================================================================

type Bill struct {
	ID         string
	FamilyID   string
	Title      string
	DueAt      string
	Status     string // unpaid / paid
	PaidAt     string
	Version    int
	DeleteFlag bool
}

// =====================================================================
// 到期中心的注册项
// =====================================================================

type Reminder struct {
	ID     string // calendar_reminder.id（本地主键，与来源 id 无关）
	From   string
	SrcID  string
	Family string
	Title  string
	DueAt  string
	Kind   string
	Active bool
	// ★ 方向声明：{source_system}:{source_id}:{action}
	DoneReturnsTo string
	Completed     bool
}

type Calendar struct {
	reminders []Reminder
	// 回调表：action 名 → finance 侧的 handler
	handlers map[string]func(srcID string) error
	// 回写结果审计流水（PRD：回写结果要进对账报表）
	writebackLog []string
}

func NewCalendar() *Calendar {
	return &Calendar{handlers: map[string]func(string) error{}}
}

// ---- 场景一：注册时带 done_returns_to ----

func (c *Calendar) RegisterWithCallback(r Reminder) {
	r.Active = true
	c.reminders = append(c.reminders, r)
}

func (c *Calendar) RegisterWithoutCallback(r Reminder) {
	r.Active = true
	r.DoneReturnsTo = "" // 业务方「忘了填」
	c.reminders = append(c.reminders, r)
}

// =====================================================================
// 到期中心完成一条提醒 → 按 done_returns_to 回写
// =====================================================================

type CompletionResult struct {
	ReminderID string
	Replayed   bool // 幂等：已完成的重复点，返回 true 而不再回写
	Err        error
	Outcome    string
}

func (c *Calendar) Complete(reminderID string) CompletionResult {
	idx := -1
	for i := range c.reminders {
		if c.reminders[i].ID == reminderID {
			idx = i
			break
		}
	}
	if idx < 0 {
		return CompletionResult{ReminderID: reminderID, Outcome: "提醒不存在"}
	}
	r := &c.reminders[idx]
	if r.Completed {
		// at-least-once：同一笔完成可能被投递多次，只回写一次
		return CompletionResult{ReminderID: reminderID, Replayed: true, Outcome: "已回写过，跳过（幂等）"}
	}
	r.Completed = true

	// ★ 关键分叉：方向声明决定回写能不能发出去
	if r.DoneReturnsTo == "" {
		c.writebackLog = append(c.writebackLog,
			"rem-001 完成但 done_returns_to 为空 → 回写丢弃 ❌ 不进对账报表（这正是缺陷所在）")
		return CompletionResult{
			ReminderID: reminderID,
			Outcome:    "回写丢失：calendar 无法知道该通知谁；**且无任何报错**",
		}
	}

	parts := strings.Split(r.DoneReturnsTo, ":")
	if len(parts) != 3 {
		return CompletionResult{ReminderID: reminderID,
			Outcome: "done_returns_to 格式错误（应为 {system}:{id}:{action}）"}
	}
	sys, srcID, action := parts[0], parts[1], parts[2]

	h, ok := c.handlers[action]
	if !ok {
		return CompletionResult{ReminderID: reminderID,
			Outcome: "目标面不认得 action=" + action + "（跨面契约漂移）"}
	}
	if sys != "finance" {
		return CompletionResult{ReminderID: reminderID,
			Outcome: "本进程没有 " + sys + " 的处理器（进程内调用的边界）"}
	}
	if err := h(srcID); err != nil {
		c.writebackLog = append(c.writebackLog, "回写失败："+err.Error()+" → 进重试（d16）")
		return CompletionResult{ReminderID: reminderID, Err: err, Outcome: "回写失败，已进重试队列"}
	}
	c.writebackLog = append(c.writebackLog,
		"回写成功：finance:"+srcID+":"+action+" → "+sys+" 侧状态已更新")
	return CompletionResult{ReminderID: reminderID, Outcome: "回写成功：" + sys + " " + srcID + " 已更新"}
}

// =====================================================================
// finance 侧：被回写时执行的 handler
// =====================================================================

type Finance struct {
	bills []*Bill
}

func (f *Finance) MarkPaid(srcID string) error {
	for _, b := range f.bills {
		if b.ID == srcID {
			if b.DeleteFlag {
				return fmt.Errorf("bill %s 已被软删，回写会复活幽灵数据（越权不返 403，返 404 等价：当作不存在）", srcID)
			}
			if b.Status == "paid" {
				return nil // 幂等
			}
			b.Status = "paid"
			b.PaidAt = "2026-03-04T21:12:00+08:00"
			b.Version++
			return nil
		}
	}
	return fmt.Errorf("bill %s 在 finance 侧不存在（对象已被删除）→ 回写失败", srcID)
}

