// =====================================================================
// W34 d5：注册的实现 —— 写事务内登记意图，调用点收在 platform 接口后面。
//
// 本项目的技术前提：**砍掉了 NATS JetStream**，跨面联动改成进程内直接调用。
// 但两件事不变：
//   ① 语义上仍然按事件契约设计（字段、幂等键、回写方向都不变）
//   ② 调用点必须收在 platform 的接口后面（铁律第 9 条）
//
// 今天要真跑出来的东西：
//   A. 为什么「在业务写事务内同步调 calendar」会出事（回滚了但注册已生效）
//   B. 为什么「先提交再调」也有问题（提交成功但注册丢了）
//   C. outbox + 进程内投递器：两个问题一起解决
//   D. platform 接口的价值：调用点只有一处，换实现只改 wiring
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// platform 层：唯一允许出现「另一个面」的地方（铁律第 9 条）
// =====================================================================

// DueRegistration 就是 {code}.due.registered 的 payload。
// 注意：这个 struct 不含 transport 字段（不写 delivery:"stream"）——
// 因为进程内调用不经过消息通道。以后换回 NATS，delivery 由 envelope 层填。
type DueRegistration struct {
	SourceSystem   string
	SourceID       string
	SourceFamilyID string
	Title          string
	DueAt          string
	Participants   []string
	Repeat         string
	Priority       string
	DoneReturnsTo  string
	Visibility     string
	Kind           string
}

// platform.DueRegistrar 是**唯一**允许被业务代码依赖的跨面接口。
// Go 的 interface 是隐式实现的：只要方法签名对上就算，不用 implements。
// TS 里必须写 `implements DueRegistrar`，而这里一个不 implements 的类型
// 只要方法齐了就能传进来 —— 这是 Go 少一层样板代码的代价。
type DueRegistrar interface {
	RegisterDue(ctx string, reg DueRegistration) error
	RevokeDue(ctx string, sourceSystem, sourceID, kind string) error
}

// =====================================================================
// 两种实现：进程内直调 / 事件总线。本项目现在用第一种。
// =====================================================================

// InProcessRegistrar —— 直接调用 calendar 的 handler
type InProcessRegistrar struct {
	target *CalendarHandler // 同进程里的另一个模块
	// outbox：登记「本事务里有哪些注册意图待投递」
	outbox []Envelope
}

func (r *InProcessRegistrar) RegisterDue(ctx string, reg DueRegistration) error {
	// ★ 关键：这一步只写 outbox，**不**调用 target。
	// 在真实的事件版里，这一步是往 outbox 表 INSERT 一行，提交后由投递器发出去。
	r.outbox = append(r.outbox, Envelope{
		Type:   reg.SourceSystem + ".due.registered",
		BusID:  "finance:bill-001",
		Idem:   "finance.due.registered:bill-001",
		Reg:    reg,
		Status: "pending",
	})
	return nil
}

func (r *InProcessRegistrar) RevokeDue(ctx string, sys, id, kind string) error {
	r.outbox = append(r.outbox, Envelope{
		Type:   sys + ".due.revoked",
		BusID:  id,
		Idem:   sys + ".due.revoked:" + id,
		Reg:    DueRegistration{SourceSystem: sys, SourceID: id, Kind: kind},
		Status: "pending",
	})
	return nil
}

// Dispatch 是投递器：把 outbox 里的意图送给 target。
// 真实实现里这一步是「提交事务之后，起一个 goroutine 扫 outbox 表」。
func (r *InProcessRegistrar) Dispatch() (ok, fail int) {
	for i := range r.outbox {
		if r.outbox[i].Status != "pending" {
			continue
		}
		if err := r.target.Consume(r.outbox[i]); err != nil {
			r.outbox[i].Status = "failed"
			r.outbox[i].LastErr = err.Error()
			fail++
			continue
		}
		r.outbox[i].Status = "delivered"
		ok++
	}
	return ok, fail
}

type Envelope struct {
	Type    string // {code}.due.registered / {code}.due.revoked
	BusID   string // business_id（不是对象 id，是信封字段）
	Idem    string // idempotency_key = event_type + business_id
	Reg     DueRegistration
	Status  string
	LastErr string
}

// CalendarHandler 是 calendar 侧真正干活的模块。
type CalendarHandler struct {
	rows     []Reminder
	Consumed []string // 收到的意图类型，用来打印
}

func (c *CalendarHandler) Consume(e Envelope) error {
	// 幂等键去重（d3 的三元组）
	k := e.Reg.SourceSystem + "|" + e.Reg.SourceID + "|" + e.Reg.Kind
	if e.Type == "finance.due.revoked" || e.Type == "homeos.due.revoked" {
		for i := range c.rows {
			cur := c.rows[i].From + "|" + c.rows[i].SrcID + "|" + c.rows[i].Kind
			if cur == k {
				c.rows[i].Active = false
				c.Consumed = append(c.Consumed, e.Type+" → 撤销 "+e.Reg.SourceID)
				return nil
			}
		}
		return fmt.Errorf("撤销失败：%s 在 calendar 侧不存在", e.Reg.SourceID)
	}
	for _, r := range c.rows {
		if r.From+"|"+r.SrcID+"|"+r.Kind == k {
			c.Consumed = append(c.Consumed, e.Type+" → 幂等命中，丢弃 "+e.Reg.SourceID)
			return nil
		}
	}
	c.rows = append(c.rows, Reminder{
		From: e.Reg.SourceSystem, SrcID: e.Reg.SourceID, Family: e.Reg.SourceFamilyID,
		Title: e.Reg.Title, DueAt: e.Reg.DueAt, Kind: e.Reg.Kind, Active: true,
	})
	c.Consumed = append(c.Consumed, e.Type+" → 落 "+e.Reg.SourceID)
	return nil
}

type Reminder struct {
	From, SrcID, Family, Title, DueAt, Kind string
	Active                                  bool
}

// FakeReg 是测试替身：满足 platform.DueRegistrar，但什么都不做。
// 因为 Go 的 interface 是隐式实现的，这里根本不用写 implements ——
// 只要方法签名对上，Finance 就愿意接受它。
type FakeReg struct{ got []DueRegistration }

func (f *FakeReg) RegisterDue(ctx string, reg DueRegistration) error {
	f.got = append(f.got, reg)
	return nil
}
func (f *FakeReg) RevokeDue(ctx string, sys, id, kind string) error { return nil }

// =====================================================================
// 业务侧：finance 写一张账单
// =====================================================================

type Bill struct {
	ID         string
	FamilyID   string
	Title      string
	DueAt      string
	Status     string
	DeleteFlag bool
}

type Finance struct {
	// 已提交的行
	committed []*Bill
	// 事务中未提交的改动
	staged []*Bill
	reg    DueRegistrar // ← 依赖的是接口，不是具体实现
}

func (f *Finance) CreateBill(id, fam, title, dueAt string, failCommit bool) error {
	b := &Bill{ID: id, FamilyID: fam, Title: title, DueAt: dueAt, Status: "unpaid"}
	f.staged = append(f.staged, b)

	// ★ 同一个事务里登记注册意图 —— 注意调的是 platform 接口
	err := f.reg.RegisterDue("tx", DueRegistration{
		SourceSystem:   "finance",
		SourceID:       id,
		SourceFamilyID: fam,
		Title:          title,
		DueAt:          dueAt,
		Participants:   []string{"mem-001"},
		Repeat:         "none",
		Priority:       "high",
		DoneReturnsTo:  "finance:" + id + ":mark_paid",
		Visibility:     "family",
		Kind:           "reminder",
	})
	if err != nil {
		return err // 注册意图登记失败 → 整个事务失败
	}
	if failCommit {
		f.staged = nil // 回滚
		return fmt.Errorf("commit 失败：数据库连接中断")
	}
	f.committed = append(f.committed, f.staged...)
	f.staged = nil
	return nil
}

// =====================================================================
// 对照组：没有 outbox 的两种错误做法
// =====================================================================

type SyncInTxRegistrar struct { // 做法 A：事务内**直接调**
	cal    *CalendarHandler
	called int
}

func (s *SyncInTxRegistrar) RegisterDue(ctx string, reg DueRegistration) error {
	s.called++
	return s.cal.Consume(Envelope{Type: reg.SourceSystem + ".due.registered", Reg: reg})
}
func (s *SyncInTxRegistrar) RevokeDue(ctx string, sys, id, kind string) error { return nil }

type AfterCommitRegistrar struct { // 做法 B：提交之后才调
	cal *CalendarHandler
	// 模拟「提交成功之后、调用之前」进程立刻崩溃
	crashBeforeCall bool
	pending         []DueRegistration // 写事务里只记下来，等 commit 之后再打
}

func (a *AfterCommitRegistrar) RegisterDue(ctx string, reg DueRegistration) error {
	a.pending = append(a.pending, reg)
	return nil // 写事务内当然成功 —— 它其实什么都没做
}
func (a *AfterCommitRegistrar) RevokeDue(ctx string, sys, id, kind string) error { return nil }

// AfterCommit 是「提交之后」的那一步
func (a *AfterCommitRegistrar) AfterCommit() error {
	if a.crashBeforeCall {
		return fmt.Errorf("调用前进程已崩溃")
	}
	for _, reg := range a.pending {
		if err := a.cal.Consume(Envelope{
			Type: reg.SourceSystem + ".due.registered", BusID: reg.SourceID, Reg: reg,
		}); err != nil {
			return err
		}
	}
	a.pending = nil
	return nil
}

func main() {
	hdr("技术前提：本项目砍掉了 NATS JetStream，改用进程内直接调用")

	fmt.Println("  tech-plan §7.2 原本写的是：写自己的表 → 同事务写 outbox → 提交 → 投递器 → NATS")
	fmt.Println("  现在：写自己的表 → 同事务登记注册意图 → 提交 → 进程内投递器 → 直接调 calendar")
	fmt.Println("  变的只有最后一跳的 transport。语义（字段、幂等键、顺序、回写方向）一个字没动。")
	fmt.Println()
	fmt.Println("  ★ 这正是「按事件契约设计、按进程内实现」的价值：")
	fmt.Println("    今天换实现不用改契约；将来拆服务只要把 InProcessRegistrar 换成 BusRegistrar，")
	fmt.Println("    业务代码一行不动 —— 因为它依赖的是 platform.DueRegistrar 接口（铁律第 9 条）。")

	// ---- 做法 A ----
	hdr("错误做法 A：事务内直接调 calendar（不写 outbox）")

	calA := &CalendarHandler{}
	sync := &SyncInTxRegistrar{cal: calA}
	finA := &Finance{reg: sync}
	err := finA.CreateBill("bill-001", "fam-001", "房贷 3 月期", "2026-03-05T09:00:00+08:00", true)
	fmt.Printf("  业务写：CreateBill 失败（%v）\n", err)
	fmt.Printf("  业务表已提交行数：%d\n", len(finA.committed))
	fmt.Printf("  calendar 收到条数：%d ← ❌ 幽灵注册项\n", len(calA.rows))
	fmt.Println("  后果：账单没建出来，到期中心却有一条「房贷 3 月期」提醒。")
	fmt.Println("  用户点完成 → 回写 finance:bill-001 → 业务对象不存在 → 回写失败进对账告警。")
	fmt.Println("  这个不一致**永远存在**，没有任何机制会自愈。")

	// ---- 做法 B ----
	hdr("错误做法 B：先提交业务，再调 calendar（无 outbox）")

	calB := &CalendarHandler{}
	after := &AfterCommitRegistrar{cal: calB, crashBeforeCall: true}
	finB := &Finance{reg: after}
	_ = finB.CreateBill("bill-001", "fam-001", "房贷 3 月期", "2026-03-05T09:00:00+08:00", false)
	fmt.Printf("  写事务：成功提交，业务表已提交行数：%d（账单建出来了 ✅）\n", len(finB.committed))
	fmt.Printf("  提交之后调 calendar：%v\n", after.AfterCommit())
	fmt.Printf("  calendar 收到条数：%d ← ❌ 提醒缺失\n", len(calB.rows))
	fmt.Println("  后果：用户建了账单，到期中心里什么都没有，不会提醒。")
	fmt.Println("  这个方向**有可能自愈**（对账任务 d10 能发现）但默认不会。")
	fmt.Println("  真实系统里这个窗口不止是崩溃：还包括「calendar 慢」「GC 停顿」「网络抖动」。")

	// ---- 正确做法 ----
	hdr("正确做法：同事务登记意图，提交后由进程内投递器送达")

	cal := &CalendarHandler{}
	inproc := &InProcessRegistrar{target: cal}
	fin := &Finance{reg: inproc}

	fmt.Println("  第 1 步：正常注册")
	_ = fin.CreateBill("bill-001", "fam-001", "房贷 3 月期", "2026-03-05T09:00:00+08:00", false)
	fmt.Printf("    提交后 outbox：%d 条 pending，业务表 %d 行 —— 注意此时 calendar 还是 %d 条\n",
		len(inproc.outbox), len(fin.committed), len(cal.rows))
	ok, fail := inproc.Dispatch()
	fmt.Printf("  第 2 步：投递器跑一轮 → 成功 %d 失败 %d，calendar 现在 %d 条\n", ok, fail, len(cal.rows))
	for _, c := range cal.Consumed {
		fmt.Printf("    %s\n", c)
	}

	fmt.Println("\n  第 3 步：回滚场景 —— 注册意图跟着回滚，不产生幽灵")
	before := len(cal.rows)
	_ = fin.CreateBill("bill-002", "fam-001", "物业费 Q1", "2026-03-20T09:00:00+08:00", true)
	fmt.Printf("    业务回滚，outbox 里 bill-002 那条被标记为 discarded\n")
	// 回滚的实现：事务失败时把本次事务写入的 outbox 行一起作废
	for i := range inproc.outbox {
		if inproc.outbox[i].Reg.SourceID == "bill-002" && inproc.outbox[i].Status == "pending" {
			inproc.outbox[i].Status = "discarded"
		}
	}
	inproc.Dispatch()
	fmt.Printf("    calendar 条数 %d → %d ✅ 与业务表一致\n", before, len(cal.rows))

	fmt.Println("\n  第 4 步：投递失败进重试，不丢")
	cal.rows = nil
	cal.Consumed = nil
	inproc.outbox = nil
	_ = fin.CreateBill("bill-003", "fam-001", "保险费", "2026-06-18T09:00:00+08:00", false)
	// 制造一次失败：往 calendar 里塞一条注定找不到的撤销
	inproc.outbox = append(inproc.outbox, Envelope{
		Type: "finance.due.revoked", BusID: "nope",
		Reg:    DueRegistration{SourceSystem: "finance", SourceID: "nope", Kind: "reminder"},
		Status: "pending",
	})
	ok, fail = inproc.Dispatch()
	fmt.Printf("    投递：成功 %d 失败 %d\n", ok, fail)
	for _, e := range inproc.outbox {
		if e.Status == "failed" {
			fmt.Printf("    failed：%s business_id=%s err=%s\n", e.Type, e.BusID, e.LastErr)
		}
	}
	fmt.Println("    → 失败条目留在 outbox 里等重试，不会丢（指数退避最多 3 次，d16）")

	// ---- platform 接口的价值 ----
	hdr("platform 接口挡住了什么：调用点只有一处")

	fmt.Println("  业务代码里出现 DueRegistrar 的地方：")
	fmt.Println("    lab/s9/d05/main.go  →  type Finance struct { reg DueRegistrar }")
