	}
	for _, s := range swaps {
		fmt.Printf("    %-30s → %s\n", s.from, s.to)
	}
	fmt.Println("    业务 service 代码：**零改动**")
	fmt.Println()
	fmt.Println("  为什么这件事在今天值钱：S9 是第一次真的跨面。d1 说过「加第二个业务面就要改 calendar」——")
	fmt.Println("  那种耦合是改不掉的。而调用点收在接口后面，耦合就降到了 wiring 文件里那几行。")

	// ---- 对照：如果不收在接口后面 ----
	hdr("对照：不收在接口后面的写法")

	fmt.Println("  ❌ 写法：业务代码直接依赖 calendar 的具体类型")
	fmt.Println("     type Finance struct { cal *calendar.Handler }   // 依赖具体实现")
	fmt.Println("     后果：① finance 的测试必须真的起一个 calendar")
	fmt.Println("           ② 想在测试里替换成 mock 只能靠改字段名或加接口（此时才加，来不及了）")
	fmt.Println("           ③ calendar.Handler 一改方法签名，finance 全仓库编译不过")
	fmt.Println()
	fmt.Println("  ✅ 写法：依赖接口")
	fmt.Println("     type Finance struct { reg platform.DueRegistrar }")
	fmt.Println("     后果：① 测试传一个 fake 就行（下面真跑）")
	fmt.Println("           ② calendar 换实现，finance 不动")
	fmt.Println("           ③ 接口签名是**契约**，改动会被所有实现方看见")

	// 真跑一个 fake
	fmt.Println()
	fmt.Println("  真跑：同一个 Finance，换一个 fake 实现，行为完全不同但业务代码不变")
	fake := &FakeReg{}
	finFake := &Finance{reg: fake}
	_ = finFake.CreateBill("bill-999", "fam-001", "测试账单", "2026-07-01T09:00:00+08:00", false)
	fmt.Printf("    fake 收到的注册：%d 条，其中 done_returns_to=%q\n", len(fake.got), fake.got[0].DoneReturnsTo)
	fmt.Printf("    真实 calendar 收到：%d 条（业务代码没改一行）\n", len(cal.rows))

	// ---- Go vs TS ----
	hdr("Go 与 TS 的差别")
	fmt.Println("  ① interface 隐式实现")
	fmt.Println("     TS：  interface DueRegistrar { registerDue(r: DueRegistration): Promise<void> }")
	fmt.Println("           class InProcessRegistrar implements DueRegistrar { ... }   ← 必须写")
	fmt.Println("     Go：  type DueRegistrar interface { RegisterDue(ctx string, reg DueRegistration) error }")
	fmt.Println("           type InProcessRegistrar struct { ... }   ← 不用写 anything")
	fmt.Println("     差别：Go 里「实现」是**编译期事实**，不是声明。所以换实现不需要改原文件。")
	fmt.Println()
	fmt.Println("  ② 错误返回 vs throw")
	fmt.Println("     TS：  throw new Error('commit 失败')  → 调用方 try/catch")
	fmt.Println("     Go：  return err                        → 调用方 if err != nil")
	fmt.Println("     ⚠ Go 的一条纪律：**永远先判 err**。忘了判 err 就继续用那个值，")
	fmt.Println("       编译器不报错、运行也不报错，只是数据是垃圾。这是 Go 新手最常见的漏洞来源。")
	fmt.Println()
	fmt.Println("  ③ 没有 panic 作为控制流")
	fmt.Println("     Go 里 recover 只在 defer 里用来兜底崩溃，不能当 try/catch 用。")
	fmt.Println("     业务错误一律 return error。")

	fmt.Println("\n=== W34 d5 到此结束 ===")
	fmt.Println("明天收口 W34：把注册链路端到端跑一遍，并逐条对判据。")
