package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 全链路：业务对象 → 注册意图 → outbox → 进程内投递 → calendar 三对象
// =====================================================================

type Reg struct {
	SourceSystem, SourceID, SourceFamilyID, Title, DueAt string
	Repeat, Priority, DoneReturnsTo, Visibility, Kind    string
	Participants                                         []string
}

type Envelope struct {
	Type, BusID, Idem string
	Reg               Reg
	Status            string
	Err               string
}

type Platform interface {
	RegisterDue(ctx string, r Reg) error
	RevokeDue(ctx string, sys, id, kind string) error
}

// ---- business 面 ----

type SourceObj struct {
	ID, Kind, Title, DueAt, Family, Face string
	Active                               bool
}

type Business struct {
	objs []*SourceObj
	reg  Platform
	// 定时器：每个业务面如果自建定时器会挂在这里
	timers map[string][]string
}

func (b *Business) EnsureTimer(face, objID, dueAt string) {
	b.timers[face] = append(b.timers[face], objID+":"+dueAt)
}

func (b *Business) Create(o *SourceObj) error {
	for _, x := range b.objs {
		if x.ID == o.ID && x.Face == o.Face {
			return nil // 已存在（用户点了两次保存）
		}
	}
	b.objs = append(b.objs, o)
	return b.reg.RegisterDue("tx", Reg{
		SourceSystem:   o.Face,
		SourceID:       o.ID,
		SourceFamilyID: o.Family,
		Title:          o.Title,
		DueAt:          o.DueAt,
		Participants:   []string{"mem-001"},
		Repeat:         "none",
		Priority:       "high",
		DoneReturnsTo:  o.Face + ":" + o.ID + ":mark_" + o.Kind,
		Visibility:     "family",
		Kind:           "reminder",
	})
}

// ---- platform：InProcess 实现 ----

type InProcess struct {
	cal    *Calendar
	outbox []Envelope
}

func (p *InProcess) RegisterDue(ctx string, r Reg) error {
	p.outbox = append(p.outbox, Envelope{
		Type:  r.SourceSystem + ".due.registered",
		BusID: r.SourceID + ":" + r.DueAt, // tech-plan §7.5：business_id = {source_id}:{due_at}
		Idem:  r.SourceSystem + ".due.registered:" + r.SourceID,
		Reg:   r, Status: "pending",
	})
	return nil
}

func (p *InProcess) RevokeDue(ctx string, sys, id, kind string) error {
	p.outbox = append(p.outbox, Envelope{
		Type: sys + ".due.revoked", BusID: id,
		Idem: sys + ".due.revoked:" + id,
		Reg:  Reg{SourceSystem: sys, SourceID: id, Kind: kind}, Status: "pending",
	})
	return nil
}

func (p *InProcess) Dispatch() (ok, fail int) {
	for i := range p.outbox {
		if p.outbox[i].Status != "pending" {
			continue
		}
		if err := p.cal.Consume(p.outbox[i]); err != nil {
			p.outbox[i].Status, p.outbox[i].Err = "failed", err.Error()
			fail++
			continue
		}
		p.outbox[i].Status = "delivered"
		ok++
	}
	return
}

// ---- calendar 到期中心 ----

type CalRow struct {
	From, SrcID, Kind, Family, Title, DueAt string
	Active                                  bool
}

type Calendar struct {
	rows      []CalRow
	delivered []string
}

func (c *Calendar) Consume(e Envelope) error {
	k := e.Reg.SourceSystem + "|" + e.Reg.SourceID + "|" + e.Reg.Kind
	for i := range c.rows {
		if c.rows[i].From+"|"+c.rows[i].SrcID+"|"+c.rows[i].Kind == k {
			c.delivered = append(c.delivered, "幂等命中 → 丢弃 "+e.BusID)
			return nil
		}
	}
	c.rows = append(c.rows, CalRow{
		From: e.Reg.SourceSystem, SrcID: e.Reg.SourceID, Kind: e.Reg.Kind,
		Family: e.Reg.SourceFamilyID, Title: e.Reg.Title, DueAt: e.Reg.DueAt, Active: true,
	})
	c.delivered = append(c.delivered, e.Type+" → 落 "+e.Reg.SourceID)
	return nil
}

func (c *Calendar) Active() int {
	n := 0
	for _, r := range c.rows {
		if r.Active {
			n++
		}
	}
	return n
}

// ---- homeos 通知下发 ----

type Notification struct {
	Type    string // reminder
	Title   string
	Members []string
}

type HomeOS struct{ notifs []Notification }

func (h *HomeOS) OnReminderFired(r CalRow) {
	h.notifs = append(h.notifs, Notification{Type: "reminder", Title: r.Title, Members: []string{"mem-001"}})
}

func main() {
	cal := &Calendar{}
	inproc := &InProcess{cal: cal}
	fin := &Business{reg: inproc, timers: map[string][]string{}}
	home := &Business{reg: inproc, timers: map[string][]string{}}
	hos := &HomeOS{}

	hdr("① 四类业务对象（PRD 16.4 当前面目录内的三行真来源 + 一行边界说明）")
	seeds := []*SourceObj{
