		{ID: "rp-014", Kind: "repaid", Face: "finance", Family: "fam-001", Title: "公积金还款 第 4 期", DueAt: "2026-03-12T09:00:00+08:00", Active: true},
		{ID: "goal-007", Kind: "reached", Face: "finance", Family: "fam-001", Title: "存款目标 5 万 截止", DueAt: "2026-09-30T09:00:00+08:00", Active: true},
		{ID: "bgt-2026-03", Kind: "exceeded", Face: "finance", Family: "fam-001", Title: "3 月预算超支", DueAt: "", Active: true},
