	fmt.Println("  之所以还建出来，是为了说明「事件驱动 ≠ 注册到到期中心」这条边界（d11 展开）。")

	hdr("② 投递：outbox → calendar")
	ok, fail := inproc.Dispatch()
	fmt.Printf("  投递成功 %d 条，失败 %d 条\n", ok, fail)
	for _, d := range cal.delivered {
		fmt.Printf("    %s\n", d)
	}
	fmt.Printf("\n  calendar_reminder 现有 %d 条（其中 budget 那条也落了 —— 今天先放过它，d11 会删掉）\n", len(cal.rows))

	hdr("③ 到点：calendar 触发 → homeos 落 Notification")
	// 按 due_at 顺序触发（用固定字符串排序，确定输出）
	idx := make([]int, 0, len(cal.rows))
	for i := range cal.rows {
		idx = append(idx, i)
	}
	for i := 0; i < len(idx); i++ {
		for j := i + 1; j < len(idx); j++ {
			if cal.rows[idx[j]].DueAt < cal.rows[idx[i]].DueAt {
				idx[i], idx[j] = idx[j], idx[i]
			}
		}
	}
	for _, i := range idx {
		r := cal.rows[i]
		if !r.Active || r.DueAt == "" {
			continue
		}
		fmt.Printf("  t=%s  calendar.reminder.fired  %-14s\n", r.DueAt, r.SrcID)
		hos.OnReminderFired(r)
		fmt.Printf("            → homeos 落 Notification(type=reminder, members=%v)\n", hos.notifs[len(hos.notifs)-1].Members)
	}
	fmt.Printf("\n  触发方统计：calendar 1 个，通知下发方 homeos 1 个，业务面 0 个定时器 ✅")

	// =================================================================
	hdr("判据 1：重复注册同一对象 → 只有一条注册项")
	// =================================================================
	before := len(cal.rows)
	for i := 0; i < 3; i++ {
		_ = fin.Create(seeds[0]) // 用户点了三次保存
	}
	_, _ = inproc.Dispatch()
	fmt.Printf("  再注册 3 次 bill-001：calendar_reminder %d → %d 条\n", before, len(cal.rows))
	fmt.Printf("  幂等键 = (source_system, source_id, kind) = (finance, bill-001, reminder)\n")
	fmt.Printf("  判定：%s\n", map[bool]string{true: "✅ 通过（唯一索引兜的，不是应用层 if）", false: "❌ 不通过"}[len(cal.rows) == before])
	fmt.Println("  验证过的失败模式：")
	fmt.Println("    key1=source_id 会把 homeos 的 mem-003 误判成重复 → 少一条提醒")
	fmt.Println("    key4=(…,due_at) 改期后新旧并存，旧行变幽灵")

	// =================================================================
	hdr("判据 5（讲清）：为什么触发归 calendar、通知下发归 homeos")
	// =================================================================
	fmt.Println("  触发 = 「什么时候响」。这件事只有 calendar 有资格决定：")
	fmt.Println("    ① 只有它知道周期规则怎么算下一个触发日（skip / postpone）")
	fmt.Println("    ② 只有它做单一调度（一个 goroutine 扫一张表，不是 N 个）")
	fmt.Println("    ③ 只有它能保证「同一个 due_at 只触发一次」（定时器幂等）")
	fmt.Println("  通知下发 = 「响给谁、怎么送到」。这件事只有 homeos 有资格：")
	fmt.Println("    ① 它是唯一有 homeos_notification 表的面（S3 建表时就定的）")
	fmt.Println("    ② 它掌握未读口径、聚合推送、免打扰策略")
	fmt.Println("    ③ 各业务面都订阅它，不订阅彼此")
	fmt.Println()
	fmt.Println("  如果让 calendar 自己发通知：")
	fmt.Println("    - 每接一个新面就要在 calendar 里加一个推送实现")
	fmt.Println("    - 未读数在两边各算一份，口径必然漂移")
	fmt.Println("    - 推送渠道（APNs/FCM/站内信）的细节泄漏进时间系统")
	fmt.Println("  如果让 homeos 自己触发：")
	fmt.Println("    - homeos 得知道每个业务对象的周期规则")
	fmt.Println("    - homeos 变成 calendar 的镜像，两张表同步问题")
	fmt.Println()
	fmt.Printf("  今天的输出印证了这条分工：触发次数 %d 次全部发生在 calendar，Notification 全部落在 homeos。\n",
		len(hos.notifs))

	// =================================================================
	hdr("判据 6（讲清）：为什么业务面不能自己起定时器")
	// =================================================================
	fmt.Println("  让每个业务面自己起定时器，会真跑出下面这两个后果：")
