	}
	fmt.Println("  → 「今天有哪些到期」这个问题现在有 3 个答案来源：calendar_reminder、")
	fmt.Println("    finance.timers、homeos.timers。改期时三者不同步 = 幽灵 + 漏报。")

	// 后果二：重复通知
	fmt.Println()
	fmt.Println("  重复通知（真实事故）：同一张账单被 finance 定时器和 calendar 各发一次")
	hos.OnReminderFired(CalRow{From: "finance", SrcID: "bill-001", Title: "房贷 3 月期（finance 自己发的）"})
	hos.OnReminderFired(CalRow{From: "finance", SrcID: "bill-001", Title: "房贷 3 月期（calendar 发的）"})
