	fmt.Println("  除非你把「下次触发时间」持久化 —— 那你就是在重新实现 calendar。")
	fmt.Println("  「多套定时器 = 多套真相 + 重复通知 + 一套残缺的重启恢复」。")

	hdr("W34 四天回顾：每个字段/机制解决的具体问题")

	type row struct{ what, why, where string }
	rows := []row{
