// =====================================================================
// W35 d7：撤销语义 —— 业务对象的三种变化，注册项各自怎么跟着变。
//
// PRD 16.4 只写了一句话：
//   「业务对象被删除 → 注册项级联失效」
// 但「业务对象变了」其实是四种，不同的处理方式完全不同：
//
//   A 删除（软删 deleted_at）      → 撤销
//   B 改期（due_at 变了）        → 同键覆盖注册（**不撤销**，见今天的顺序陷阱）
//   C 状态变了（账单已缴清）      → 撤销（提前完成）
//   D 只是改了标题/优先级        → 更新，不撤销（active 保持，字段覆盖）
//
// 今天把四种真跑一遍，并打印「为什么 B 不能只做注册不做撤销」。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// ---- calendar 侧的注册项 ----

type CalRow struct {
	From, SrcID, Kind, Family, Title, DueAt, Priority string
	Active                                            bool
	RevokedAt, RevokeReason                           string
}

type Calendar struct{ rows []CalRow }

// Upsert 模拟「唯一索引 + ON CONFLICT DO UPDATE」
func (c *Calendar) Upsert(from, srcID, kind, title, dueAt, priority string) string {
	k := from + "|" + srcID + "|" + kind
	for i := range c.rows {
		if c.rows[i].From+"|"+c.rows[i].SrcID+"|"+c.rows[i].Kind == k {
			c.rows[i].Title = title
			c.rows[i].DueAt = dueAt
			c.rows[i].Priority = priority
			c.rows[i].Active = true // 重新激活
			return "UPDATED(同键覆盖)"
		}
	}
	c.rows = append(c.rows, CalRow{
		From: from, SrcID: srcID, Kind: kind, Title: title,
		DueAt: dueAt, Priority: priority, Active: true,
	})
	return "INSERTED"
}

func (c *Calendar) Revoke(from, srcID, kind, reason string) string {
	k := from + "|" + srcID + "|" + kind
	for i := range c.rows {
		if c.rows[i].From+"|"+c.rows[i].SrcID+"|"+c.rows[i].Kind == k {
			if !c.rows[i].Active {
				return "已失效（幂等：重复撤销不再改）"
			}
			c.rows[i].Active = false
			c.rows[i].RevokedAt = "2026-03-02T10:00:00+08:00"
			c.rows[i].RevokeReason = reason
			return "REVOKED"
		}
	}
	return "NOT_FOUND（撤销了一个不存在的注册项 → 进对账报表）"
}

func (c *Calendar) Count() int {
	n := 0
	for _, r := range c.rows {
		if r.Active {
			n++
		}
	}
	return n
}

func (c *Calendar) Dump(title string) {
	fmt.Printf("  %s（生效 %d 条 / 总 %d 条）\n", title, c.Count(), len(c.rows))
	for _, r := range c.rows {
		st := "生效"
		note := ""
		if !r.Active {
			st = "失效"
			note = "  reason=" + r.RevokeReason
		}
		fmt.Printf("    [%s] %-9s %-9s %-8s due_at=%-26s %s%s\n",
			st, r.SrcID, r.Kind, r.Priority, r.DueAt, r.Title, note)
	}
}

// =====================================================================

func main() {
	cal := &Calendar{}

	hdr("A 删除场景：业务对象被软删 → 撤销")
	fmt.Println("  铁律第 2 条：业务表软删 deleted_at + deleted_by —— 对象还在，只是不该被看见。")
	fmt.Println("  注册项跟着「失效」（active=false），**不是物理删除** —— 因为对账要查它。")
	_ = cal.Upsert("finance", "bill-001", "reminder", "房贷 3 月期", "2026-03-05T09:00:00+08:00", "high")
	_ = cal.Upsert("finance", "rp-014", "reminder", "公积金还款 第 4 期", "2026-03-12T09:00:00+08:00", "normal")
	cal.Dump("① 删除前")
	fmt.Printf("  用户删除 bill-001（finance 侧 deleted_at=2026-03-02T10:00:00+08:00）\n")
	fmt.Printf("  发 finance.due.revoked → %s\n", cal.Revoke("finance", "bill-001", "reminder", "source_deleted"))
	cal.Dump("② 删除后")
	fmt.Println("  注意保留了什么：SrcID / DueAt / RevokedAt / RevokeReason 都还在。")
	fmt.Println("  对账任务靠这四列回答「这条提醒为什么消失了」，删干净就永远查不到了。")

	// 重跑一遍
	fmt.Println()
	fmt.Println("  重发一次撤销（用户手滑点了两次删除）：")
	fmt.Printf("    → %s（幂等：不报错，但也不重复改）\n", cal.Revoke("finance", "bill-001", "reminder", "source_deleted"))

	hdr("B 改期场景：due_at 变了 → 同键覆盖注册，**不撤销**")
	fmt.Println("  这是今天最容易做错的一个场景。先看做错的版本：")
	cal2 := &Calendar{}
	_ = cal2.Upsert("finance", "bill-002", "reminder", "物业费 Q1", "2026-03-20T09:00:00+08:00", "normal")
	cal2.Dump("① 改期前")
	fmt.Println("  用户把 due_at 从 3-20 改到 3-25，finance 只发了 due.registered（没发 revoked）：")
	fmt.Printf("    → %s（同键覆盖，due_at 被改了，看起来是对的）\n",
		cal2.Upsert("finance", "bill-002", "reminder", "物业费 Q1", "2026-03-25T09:00:00+08:00", "normal"))
	cal2.Dump("② 只重新注册")
	fmt.Println("  为什么这看起来能过？因为幂等键里没有 due_at（d3 的结论），Upsert 是覆盖。")
	fmt.Println("  但它有一个真实的事故：**投递顺序**。")
	fmt.Println()
	fmt.Println("  场景：注册和撤销是两条独立意图，投递器可能先送 revoked、后送 registered，")
	fmt.Println("  也可能先送 registered、后送 revoked。两种顺序给出不同结果：")
	// 顺序 A
	a := &Calendar{}
	_ = a.Upsert("finance", "bill-003", "reminder", "车险", "2026-03-28T09:00:00+08:00", "normal")
	a.Revoke("finance", "bill-003", "reminder", "rescheduled")
	a.Upsert("finance", "bill-003", "reminder", "车险", "2026-04-10T09:00:00+08:00", "normal")
	fmt.Printf("    顺序 A（revoked 先到）：生效 %d 条，due_at=%s ✅ 正确\n",
		a.Count(), a.rows[0].DueAt)
	// 顺序 B：新注册先到，旧撤销后到
	b := &Calendar{}
	_ = b.Upsert("finance", "bill-003", "reminder", "车险", "2026-04-10T09:00:00+08:00", "normal")
	rev := b.Revoke("finance", "bill-003", "reminder", "rescheduled")
	fmt.Printf("    顺序 B（registered 先到、旧 revoked 后到）：生效 %d 条 due_at=%s → %s\n",
		b.Count(), b.rows[0].DueAt, rev)
	fmt.Println("      **撤销意图里没有 due_at，calendar 无法分辨「我要撤的是 3-28 那条」**")
	fmt.Println("      结果：用户把车险改到 4-10，新提醒刚建好就被旧撤销打掉了 ❌")
	fmt.Println()
	fmt.Println("  两道防线：")
	fmt.Println("    防线 1（事件治理，tech-plan §7.5）：「不承诺全局有序，只承诺同一")
	fmt.Println("      (source_system, source_id) 分区内有序」。同一次改期产生的两条意图")
	fmt.Println("      business_id 都是 bill-003 → 落在同一分区 → 顺序有保证。")
	fmt.Println("      ⚠ 但注意：分区有序**只在同一业务对象的多条意图之间**成立。")
	fmt.Println("      如果你给 revoked 换一个 business_id（比如 bill-003:revoke），")
	fmt.Println("      它就跑到另一个分区，防线 1 立刻失效。")
	fmt.Println()
	fmt.Println("    防线 2（更稳，改期根本不拆两条）：")
	fmt.Println()
	c3 := &Calendar{}
	_ = c3.Upsert("finance", "bill-004", "reminder", "车险", "2026-03-28T09:00:00+08:00", "normal")
	fmt.Printf("    改期：Upsert 同键覆盖 → %s，生效 %d 条 ✅\n",
		c3.Upsert("finance", "bill-004", "reminder", "车险", "2026-04-10T09:00:00+08:00", "normal"), c3.Count())
	fmt.Println("    没有 revoked 参与，顺序问题从根上消失。")
	fmt.Println("    这就是幂等键不含 due_at 的第二个好处（d3 只讲了第一个：不做幽灵）。")

	hdr("C 提前完成：状态变了 → 撤销")
	cal4 := &Calendar{}
	_ = cal4.Upsert("finance", "goal-007", "reminder", "存款目标 5 万 截止", "2026-09-30T09:00:00+08:00", "normal")
	_ = cal4.Upsert("finance", "bill-005", "reminder", "信用卡还款", "2026-03-08T09:00:00+08:00", "high")
	cal4.Dump("① 用户提前完成之前")
	fmt.Println("  用户在 finance 里点「这笔已经还了」（不是到期中心点的）：")
	_ = cal4.Revoke("finance", "goal-007", "reminder", "completed_early")
	_ = cal4.Revoke("finance", "bill-005", "reminder", "completed_early")
	cal4.Dump("② 撤销之后")
	fmt.Println("  revoke_reason=completed_early 与 source_deleted 是两回事：")
	fmt.Println("    source_deleted   → 对象没了，提醒不该存在")
	fmt.Println("    completed_early  → 对象还在且已完成，提醒不该再响")
	fmt.Println("  统计口径不同（「多少提醒被删」vs「多少事情提前办完了」），所以必须分开记。")

	hdr("D 只改字段：标题/优先级变了 → 更新，不撤销")
	cal5 := &Calendar{}
	_ = cal5.Upsert("finance", "bill-006", "reminder", "物业费", "2026-03-20T09:00:00+08:00", "low")
	fmt.Println("  用户把标题从「物业费」改成「物业费 + 车位费」，优先级 low → high")
	fmt.Printf("    → %s\n", cal5.Upsert("finance", "bill-006", "reminder", "物业费 + 车位费", "2026-03-20T09:00:00+08:00", "high"))
	cal5.Dump("  结果")
	fmt.Println("  判据很简单：due_at 变了吗？没变 → 更新。变了 → 也是更新（见 B）。")
	fmt.Println("  **撤销只用于「这个提醒不该再存在了」**，不是「数据变了」。")
	fmt.Println("  每次改个标题就发一条 revoked，是把撤销当成刷新用，会把撤销日志冲爆。")

	hdr("四种变化的处理方式对照表")

	type row struct {
		change     string
		action     string
		reason     string
		badIfWrong string
	}
	rows := []row{
		{"删除（软删）", "revoked", "source_deleted", "用户删了账单，到期中心还在催缴"},
		{"due_at 变更", "registered（同键覆盖）", "—（不撤销）", "若拆成 revoked+registered，顺序反了会把新日期的提醒撤销掉"},
		{"状态变更（已缴清/已达成）", "revoked", "completed_early", "提前办完的事还会反复提醒"},
		{"标题/优先级变更", "registered（同键覆盖）", "—（不撤销）", "撤销当刷新用 → 撤销日志冲爆、真正的撤销被淹没"},
		{"对象整体重建（新 id）", "registered + 旧对象 revoked", "source_deleted", "重复提醒（当成两个对象了）"},
	}
	fmt.Printf("  %-26s %-26s %-22s %s\n", "业务侧发生什么", "发出的意图", "revoke_reason", "处理错了的后果")
	fmt.Println("  " + strings.Repeat("-", 108))
	for _, r := range rows {
		fmt.Printf("  %-26s %-26s %-22s %s\n", r.change, r.action, r.reason, r.badIfWrong)
	}

	hdr("撤销 vs 删除：为什么注册项不物理删除")

	type cmp struct{ dim, revokeActive, hardDelete string }
	cmps := []cmp{
		{"对账", "能回答「这条提醒为什么消失」", "无从查证，账单和提醒的差异永远查不出来"},
		{"幂等", "重复撤销是 no-op（幂等）", "重复撤销会 NOT_FOUND，误报一堆告警"},
		{"改期", "撤销 + 同键重注册能复活同一行", "重注册会产生新行，id 变化，引用全断"},
		{"审计", "能看到「谁在什么时候撤销的」", "PRD 16.4 的「不回写视为缺陷」需要证据，这条就是证据"},
		{"代价", "表会越来越大", "需要定期归档 + 归档脚本也是一处复杂度"},
	}
	fmt.Printf("  %-10s %-42s %s\n", "维度", "active=false（撤销）", "DELETE 物理删除")
	fmt.Println("  " + strings.Repeat("-", 100))
	for _, c := range cmps {
		fmt.Printf("  %-10s %-42s %s\n", c.dim, c.revokeActive, c.hardDelete)
	}
	fmt.Println()
	fmt.Println("  实践做法：撤销是 active=false（+ revoked_at + revoke_reason），")
	fmt.Println("  物理删除交给归档任务，条件是 revoked_at < now() - 90 天。")
	fmt.Println("  这样「不注册清单 / 孤儿清理」这类日对账有 90 天的窗口可以回溯。")

	hdr("Go 的实现要点：Update 与 Upsert 的差别")

	fmt.Println("  用 GORM 时，两个方法长得像但语义完全不同：")
	fmt.Println()
	fmt.Println("    db.Save(&row)                    ← Update：不存在就 Insert，存在就全字段覆盖")
	fmt.Println("    db.Clauses(clause.OnConflict{...}).Create(&row)  ← Upsert：显式指定冲突键与动作")
	fmt.Println()
	fmt.Println("  ⚠ 坑一：Save 会把没填的字段写成零值。")
	fmt.Println("     如果 DueAt 用 gorm.Model 的零时间（0001-01-01 00:00:00）存进去，")
	fmt.Println("     提醒会在公元前 1 年就该触发，然后被调度器当成过期项扫掉。")
	fmt.Println("     所以可空时间字段要用 *time.Time，nil 表示「没有」。")
	fmt.Println()
	fmt.Println("  ⚠ 坑二：RowsAffected 不可信的场景。")
	fmt.Println("     ON CONFLICT DO NOTHING 在冲突时返回 0 —— 这是好事，能判「这条是重复投递」。")
	fmt.Println("     但如果你写成 DO UPDATE 且新值与旧值相同，Postgres 也返回 0，")
	fmt.Println("     此时 0 到底意味着「重复」还是「无变化」分不出来。")
	fmt.Println("     判据要定死：要么用 DO NOTHING（0 = 重复），要么先 SELECT 再决定，别混。")
	fmt.Println()
	fmt.Println("  ⚠ 坑三：struct 是值语义，改了副本不会生效。")
	fmt.Println("     Go: for _, r := range rows { r.Active = false }   // 什么都不会发生")
	fmt.Println("     Go: for i := range rows { rows[i].Active = false }  // ✓")
	fmt.Println("     TS: rows.forEach(r => r.active = false)            // 生效（对象是引用）")
	fmt.Println("     这是从 JS 过来最容易中招的一处，编译器不会提醒你。")

	fmt.Println("\n=== W35 d7 到此结束 ===")
	fmt.Println("明天讲 due.revoked 的三种场景在事件层怎么表达，以及 payload 里该带什么。")
}

// =====================================================================
// W35 d8：due.revoked 的三种场景 —— 在事件层怎么表达，payload 带什么。
//
// tech-plan §7.5 事件目录：
//   {code}.due.revoked  发布方 finance  消费方 calendar  business_id {source_id}
//
// 注意：目录里 **没有** 「时间变更」这一条单独的撤销事件。
// 所以今天要回答的问题是：三种场景是不是共用同一个事件？
// 如果共用，payload 里必须多带什么才能让 calendar 判得清？
// =====================================================================

package main

import (
	"encoding/json"
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 事件信封：tech-plan §7.4 的 13 字段。进程内调用时不走通道，
// 但字段一个不少 —— 因为以后换回总线，这些字段已经在库里了。
// =====================================================================

type Envelope struct {
	EventID        string         `json:"event_id"`
	Type           string         `json:"type"`
	Source         string         `json:"source"`
	BusinessID     string         `json:"business_id"`
	FamilyID       string         `json:"family_id"`
	MemberID       string         `json:"member_id"`
	Payload        map[string]any `json:"payload"`
	Version        string         `json:"version"`
	CreatedAt      string         `json:"created_at"`
	IdempotencyKey string         `json:"idempotency_key"`
	CausationID    *string        `json:"causation_id"`
	Attempt        int            `json:"attempt"`
	Delivery       string         `json:"delivery"`
}

func (e Envelope) JSON() string {
	b, err := json.MarshalIndent(e, "", "  ")
	if err != nil {
		panic(err)
	}
	return string(b)
}

// ---- 三种撤销场景的 payload ----

type RevokePayload struct {
	SourceSystem  string `json:"source_system"`
	SourceID      string `json:"source_id"`
	Kind          string `json:"kind"`
	Reason        string `json:"reason"`          // source_deleted / completed_early / time_changed
	PreviousDueAt string `json:"previous_due_at"` // 仅 time_changed 需要
}

func newRevoke(evType, bizID, fam string, p RevokePayload) Envelope {
	return Envelope{
		EventID:    "evt-" + p.SourceID + "-rev",
		Type:       evType,
		Source:     p.SourceSystem,
		BusinessID: bizID,
		FamilyID:   fam,
		MemberID:   "mem-001",
		Payload: map[string]any{
			"source_system":   p.SourceSystem,
			"source_id":       p.SourceID,
			"kind":            p.Kind,
			"reason":          p.Reason,
			"previous_due_at": p.PreviousDueAt,
		},
		Version:        "1.0",
		CreatedAt:      "2026-03-02T10:00:00+08:00",
		IdempotencyKey: evType + ":" + bizID,
		CausationID:    nil,
		Attempt:        0,
		Delivery:       "inproc", // 进程内直调；将来换总线改成 "stream"
	}
}

// =====================================================================
// calendar 侧的撤销处理器
// =====================================================================

type Row struct {
	From, SrcID, Kind, DueAt string
	Active                   bool
	RevokeReason             string
	MatchedBy                string // 靠什么维度匹配上的
}

type Calendar struct{ rows []Row }

func (c *Calendar) HandleRevoke(e Envelope) string {
	p, _ := e.Payload["source_system"].(string)
	id, _ := e.Payload["source_id"].(string)
	kind, _ := e.Payload["kind"].(string)
	reason, _ := e.Payload["reason"].(string)

	for i := range c.rows {
		r := &c.rows[i]
		if r.From == p && r.SrcID == id && r.Kind == kind {
			r.Active = false
			r.RevokeReason = reason
			r.MatchedBy = "(source_system, source_id, kind)"
			return "REVOKED"
		}
	}
	return "NOT_FOUND"
}

// 消费者侧幂等：同一 (type, business_id) 只处理一次
type Seen struct{ keys map[string]bool }

func (s *Seen) First(e Envelope) bool {
	if s.keys == nil {
		s.keys = map[string]bool{}
	}
	k := e.Type + "|" + e.BusinessID + "|" + fmt.Sprint(e.Payload["reason"])
	if s.keys[k] {
		return false
	}
	s.keys[k] = true
	return true
}

