// =====================================================================
// W35 d9：级联失效的实现 —— 业务对象的删除钩子怎么触发撤销。
//
// 判据第 2 条：业务对象删除 → 对应注册项级联失效。
//
// 「级联」这个词有歧义，今天要拆清楚：
//   数据库级联（ON DELETE CASCADE）：同一张表内的外键，数据库替你做
//   应用级级联：跨服务，数据库做不了，必须由业务代码显式发出撤销
//
// 本项目是后者。难点在于：**发出撤销的代码写在哪个函数里**。
// 今天真跑四种钩子位置，逐一验证漏了会怎样。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 平台层
// =====================================================================

type CalRow struct {
	From, SrcID, Kind, Title, DueAt string
	Active                          bool
}

type Calendar struct{ rows []CalRow }

func (c *Calendar) Upsert(from, id, kind, title, dueAt string) {
	for i := range c.rows {
		if c.rows[i].From == from && c.rows[i].SrcID == id && c.rows[i].Kind == kind {
			c.rows[i].Title, c.rows[i].DueAt, c.rows[i].Active = title, dueAt, true
			return
		}
	}
	c.rows = append(c.rows, CalRow{From: from, SrcID: id, Kind: kind, Title: title, DueAt: dueAt, Active: true})
}

func (c *Calendar) Revoke(from, id, kind, reason string) string {
	for i := range c.rows {
		if c.rows[i].From == from && c.rows[i].SrcID == id && c.rows[i].Kind == kind {
			c.rows[i].Active = false
			return "REVOKED"
		}
	}
	return "NOT_FOUND"
}

func (c *Calendar) Active() int {
	n := 0
	for _, r := range c.rows {
		if r.Active {
			n++
		}
	}
	return n
}

// =====================================================================
// 业务层：Bill 与它的软删
// =====================================================================

type Bill struct {
	ID, Family, Title, DueAt, Status string
	DeletedAt                        string
	DeletedBy                        string
	Version                          int
}

type Repo struct{ bills []*Bill }

func (r *Repo) ByID(id string) *Bill {
	for _, b := range r.bills {
		if b.ID == id {
			return b
		}
	}
	return nil
}
func (r *Repo) Live(id string) *Bill {
	b := r.ByID(id)
	if b == nil || b.DeletedAt != "" {
		return nil
	}
	return b
}

type Reg interface {
	RevokeDue(ctx string, sys, id, kind, reason string) error
}

type OutboxReg struct {
	cal    *Calendar
	rows   []string
	failTx bool // 演示：写 outbox 失败
}

func (o *OutboxReg) RevokeDue(ctx string, sys, id, kind, reason string) error {
	if o.failTx {
		return fmt.Errorf("outbox 写入失败：数据库连接中断")
	}
	o.rows = append(o.rows, sys+".due.revoked id="+id+" reason="+reason)
	if r := o.cal.Revoke(sys, id, kind, reason); r == "NOT_FOUND" {
		return fmt.Errorf("撤销失败：%s 在 calendar 侧不存在", id)
	}
	return nil // 进程内直调
}

// =====================================================================
// 四种钩子位置的写法
// =====================================================================

type Svc struct {
	repo *Repo
	reg  Reg
	// dbHook 模拟「数据库触发器 / 应用层统一拦截器」
	dbHookFires bool
}

// ① 只在 SoftDelete 里发撤销 —— 唯一正确的位置
func (s *Svc) SoftDelete(id, by string) error {
	b := s.repo.Live(id)
	if b == nil {
		return fmt.Errorf("对象不存在或已删除（返 404 等价，不返 403）")
	}
	// 先记撤销意图（同事务），再改业务行
	if err := s.reg.RevokeDue("tx", "finance", b.ID, "reminder", "source_deleted"); err != nil {
		return err
	}
	b.DeletedAt = "2026-03-02T10:00:00+08:00"
	b.DeletedBy = by
	b.Version++
	return nil
}

// ② 只在 Restore 里发注册 —— 恢复必须补注册
func (s *Svc) Restore(id string, cal *Calendar) error {
	b := s.repo.ByID(id)
	if b == nil || b.DeletedAt == "" {
		return fmt.Errorf("对象没有被删除，恢复非法")
	}
	b.DeletedAt = ""
	cal.Upsert("finance", b.ID, "reminder", b.Title, b.DueAt) // 重新注册
	return nil
}

// ③ 依赖数据库级联 —— 本项目里做不到，真跑一遍失败
func (s *Svc) TryDbCascade(id string, cal *Calendar) string {
	b := s.repo.ByID(id)
	if b == nil {
		return "NOT_FOUND"
	}
	// 假如真在 calendar_reminder 上建了
	//   FOREIGN KEY (source_id) REFERENCES finance.finance_bill(id) ON DELETE CASCADE
	// 会发生什么？
	if b.DeletedAt != "" {
		return "ON DELETE CASCADE 不会触发 —— 软删是 UPDATE deleted_at，不是 DELETE 行"
	}
	return "只有真 DELETE 行才会级联；铁律第 2 条要求软删，所以级联在这里永远不触发"
}

// ④ 忘了写撤销 —— 最常见的情况
func (s *Svc) SoftDeleteNoHook(id, by string) error {
	b := s.repo.Live(id)
	if b == nil {
		return fmt.Errorf("对象不存在")
	}
	b.DeletedAt = "2026-03-02T10:00:00+08:00"
	b.DeletedBy = by
	b.Version++
	return nil // ← 忘了调 reg.RevokeDue
}

func main() {
	seed := func() (*Repo, *Calendar) {
		return &Repo{bills: []*Bill{
			{ID: "bill-001", Family: "fam-001", Title: "房贷 3 月期", DueAt: "2026-03-05T09:00:00+08:00", Status: "unpaid", Version: 1},
			{ID: "bill-002", Family: "fam-001", Title: "物业费 Q1", DueAt: "2026-03-20T09:00:00+08:00", Status: "unpaid", Version: 1},
			{ID: "rp-014", Family: "fam-001", Title: "公积金还款 第 4 期", DueAt: "2026-03-12T09:00:00+08:00", Status: "unpaid", Version: 1},
		}}, &Calendar{}
	}

	hdr("场景：仓库里三张账单都注册到了到期中心")

	repo, cal := seed()
	reg := &OutboxReg{cal: cal}
	for _, b := range repo.bills {
		cal.Upsert("finance", b.ID, "reminder", b.Title, b.DueAt)
	}
	svc := &Svc{repo: repo, reg: reg}
	fmt.Printf("  calendar_reminder 生效 %d 条：bill-001 / bill-002 / rp-014\n", cal.Active())

	// ---- 正确的路径 ----
	hdr("路径 ①：SoftDelete 里发撤销（正确）")
	_ = svc.SoftDelete("bill-001", "mem-001")
	fmt.Printf("  用户删除 bill-001 →\n")
	fmt.Printf("    业务表 deleted_at = %q deleted_by = %q version = %d\n",
		repo.ByID("bill-001").DeletedAt, repo.ByID("bill-001").DeletedBy, repo.ByID("bill-001").Version)
	fmt.Printf("    outbox 登记：%v\n", reg.rows)
	fmt.Printf("    calendar 生效 %d 条（3 → 2）✅ 级联失效成立\n", cal.Active())

	// ---- 恢复 ----
	hdr("路径 ②：恢复（Restore）必须补注册")
	fmt.Println("  用户发现删错了，点「恢复」：")
	_ = svc.Restore("bill-001", cal)
	fmt.Printf("    calendar 生效 %d 条（2 → 3）✅\n", cal.Active())
	fmt.Println("  ⚠ 这一步极易漏。SoftDelete 有撤销，Restore 没注册 →")
	fmt.Println("    对象回来了但提醒没了，用户说「恢复之后怎么不提醒我了」。")
	fmt.Println("    这类不对称必须在 code review 里成对检查：搜 RevokeDue 就必须搜到 RegisterDue。")

	// ---- 数据库级联 ----
	hdr("路径 ③：想用数据库 ON DELETE CASCADE —— 本项目做不到")
	fmt.Printf("  %s\n", svc.TryDbCascade("bill-002", cal))
	fmt.Println()
	fmt.Println("  两个硬原因：")
	fmt.Println("    ① 铁律第 2 条要求软删（deleted_at），软删是 UPDATE 不是 DELETE → 触发器不响")
	fmt.Println("    ② 就算真 DELETE，跨 schema 外键也建不了：")
	fmt.Println("       finance_app 账号无权在 calendar schema 建外键指向 finance.finance_bill")
	fmt.Println("       （红线：禁止跨 schema SQL，tech-plan §10.3 第 1 条）")
	fmt.Println("  所以「级联」在这个架构里**必然是应用级的**，不是数据库替你做。")

	// ---- 漏写撤销 ----
	hdr("路径 ④：忘了写撤销（最常见的真实 bug）")
	repo2, cal2 := seed()
	reg2 := &OutboxReg{cal: cal2}
	for _, b := range repo2.bills {
		cal2.Upsert("finance", b.ID, "reminder", b.Title, b.DueAt)
	}
	svc2 := &Svc{repo: repo2, reg: reg2}
	_ = svc2.SoftDeleteNoHook("bill-002", "mem-001")
	fmt.Printf("  用户删除 bill-002（业务侧删了，撤销没发）\n")
	fmt.Printf("    业务表：deleted_at=%q ✅\n", repo2.ByID("bill-002").DeletedAt)
	fmt.Printf("    outbox：%v（空）\n", reg2.rows)
	fmt.Printf("    calendar 生效 %d 条 ← ❌ 幽灵提醒还在\n", cal2.Active())
	fmt.Println()
	fmt.Println("  3 月 20 日会发生什么：")
	fmt.Println("    calendar 扫到「物业费 Q1」，到点触发 calendar.reminder.fired")
	fmt.Println("    homeos 落 Notification → 推送「物业费 Q1 该缴了」")
	fmt.Println("    用户：「这条我已经删掉了，怎么还在提醒我？」")
	fmt.Println("    更糟的：用户点通知进到期中心 → 看到一条他删掉的事 → 点完成")
	fmt.Println("    → 回写 finance:bill-002 → 业务对象已软删 → 处理器拒绝（越权返 404 等价）")
	fmt.Println("    → 回写失败进对账报表 —— d10 的孤儿检测其实就是这条链的另一端")

	// ---- 事务失败 ----
	hdr("路径 ⑤：撤销意图登记失败 → 整个事务必须回滚")
	repo3, cal3 := seed()
	reg3 := &OutboxReg{cal: cal3, failTx: true}
	for _, b := range repo3.bills {
		cal3.Upsert("finance", b.ID, "reminder", b.Title, b.DueAt)
	}
	svc3 := &Svc{repo: repo3, reg: reg3}
	err := svc3.SoftDelete("bill-002", "mem-001")
	fmt.Printf("  RevokeDue 返回 error → %v\n", err)
	fmt.Printf("    业务表 deleted_at = %q（**必须还是空**，事务回滚了）\n", repo3.ByID("bill-002").DeletedAt)
	fmt.Printf("    calendar 生效 %d 条（未变）✅\n", cal3.Active())
	fmt.Println()
	fmt.Println("  ⚠ 这是「宁可删不掉，也不能删了还留着提醒」的取舍：")
	fmt.Println("    业务侧删除失败 → 用户看到「删除失败请重试」，这是一个**诚实**的失败。")
	fmt.Println("    反过来如果吞掉 error 继续删，得到的就是路径 ④ 那个幽灵。")

	// ---- 钩子该写在哪 ----
	hdr("撤销钩子应该写在哪：四个候选位置")

	type pos struct {
		where   string
		ok      bool
		problem string
	}
	poss := []pos{
		{"业务 service 的 SoftDelete / Delete 方法里", true,
			"唯一正确。删除是业务动作，撤销是它的必然后果，写在一起不会被漏"},
		{"HTTP handler 层（controller）", false,
			"handler 是协议层。将来加第二个入口（CLI、批量任务、定时清理）就会漏"},
		{"repository 的 Delete 里", false,
			"repo 抽象的是存储不是业务。它不知道「这个对象有注册项」，会变成跨模块依赖（违铁律 9）"},
		{"数据库触发器 / GORM hook（BeforeDelete）", false,
			"GORM 的 Delete hook 只在真 DELETE 触发，而本项目是软删（Update）。而且 hook 里发跨模块调用是隐式的，堆栈里看不出来"},
		{"回收站清理任务（真 DELETE 时）", false,
			"太晚了：用户删除后到进回收站之间（可能 30 天）提醒一直在响"},
	}
	fmt.Printf("  %-46s %-6s %s\n", "位置", "可行", "问题")
	fmt.Println("  " + strings.Repeat("-", 108))
	for _, p := range poss {
		fmt.Printf("  %-46s %-6s %s\n", p.where, map[bool]string{true: "✅", false: "❌"}[p.ok], p.problem)
	}

	fmt.Println()
	fmt.Println("  推荐写法：让「删除」这个动作本身必须经过一个发撤销的函数，")
	fmt.Println("  而不是「记得在删除后调一下撤销」。")
	fmt.Println("  做法：在 service 层定义")
	fmt.Println("      func (s *BillSvc) SoftDelete(ctx, id, by string) error {")
	fmt.Println("          // 1. 查（含权限，越权返 404）")
	fmt.Println("          // 2. 同一事务内登记撤销意图")
	fmt.Println("          // 3. 软删业务行")
	fmt.Println("          // 4. Commit")
	fmt.Println("      }")
	fmt.Println("  并把 repo 的 Delete 设为包内私有，让外部无法绕过这个函数。")
	fmt.Println("  「收在接口后面」这个原则在这里的体现：业务代码只能通过 service 改状态。")

	// ---- Go 的坑 ----
	hdr("Go 与 TS 的差别：钩子怎么写")
	fmt.Println("  TS：类可以用装饰器/框架钩子（NestJS 的 @OnEvent、TypeORM 的 subscribers），")
	fmt.Println("      编译后是隐式的，grep 不到调用点。")
	fmt.Println("  Go：**没有方法重写**，没有装饰器。你只有三种写法：")
	fmt.Println("    ① 显式调用（最常见，推荐）—— 可见、可 grep、可测")
	fmt.Println("    ② 函数包装：deleteBill := withRevoke(svc.Delete)  —— 隐式、易漏")
	fmt.Println("    ③ 接口 + 中间件：所有写操作走一个 wrap，服务级通用")
	fmt.Println("  ⚠ Go 里最容易踩的是 ① 的反面：")
	fmt.Println("    同一个 service 里 Delete 写了撤销，MarkPaid 忘了写（该发 completed_early）")
	fmt.Println("    → 编译器不会报错，code review 也可能漏")
	fmt.Println("    → 只能靠一条测试断言：「每个会改 due 语义的写方法都必须发出撤销」")
	fmt.Println("    这是 d12 的 s9-check.sh 里会真跑的一条。")

	fmt.Println("\n=== W35 d9 到此结束 ===")
	fmt.Println("明天讲孤儿注册项：怎么发现、怎么清理、为什么清理必须等对账而不是当场。")
}

// =====================================================================
// W35 d10：孤儿注册项 —— 业务对象没了但注册项还在，怎么发现与清理。
//
// 「孤儿」这个词在本项目里指两种东西，来源不同、危害不同、处置不同：
//   类型 A：calendar 侧的注册项指向一个业务面已经不存在的对象
//   类型 B：业务面对象引用了一个别的面里不存在的 id（技术方案 §7.1 方式③）
//
// 本阶段关注类型 A（它是级联失效的失败产物）。
// 处置手段是**每日对账**（PRD 18.6），不是当场删除 —— 原因今天要跑出来。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// ---- 两边的表（用 map 模拟，键是 id）----
// 现实里它们在不同 schema、两个不同的数据库账号，谁也查不到谁。
// 对账任务的做法是：各自导出「本面负责的 (source_system, source_id) 清单」，
// 在对账进程里做集合运算。

type Bill struct {
	ID, Family, Title, DueAt, Status string
	DeletedAt                        string
	Registered                       bool // 业务面认为「我登记过」
}

type FinanceView struct{ Bills map[string]*Bill }

type CalRow struct {
	From, SrcID, Kind, Title, DueAt string
	Active                          bool
	RegisteredAt                    string
}

type CalendarView struct{ Rows map[string]*CalRow } // key = from|srcid|kind

// ---- 对账进程：两边各给一份清单，然后在进程里比对 ----
// ★ 这就是「禁止跨 schema SQL」的落地方式：不连库，连清单。

type Snapshot struct {
	Face       string
	SourceIDs  []string          // 该面所有活着的对象 id
	Registered map[string]string // 该面登记过的 (id → registered_at)
	At         string
}

type Report struct {
	Kind     string // orphan_reminder / stale_outbox / failed_writeback
	Face     string
	ID       string
	Detail   string
	Action   string
	Severity string
}

func (c *CalendarView) ListFor(from string) []string {
	out := []string{}
	for k, r := range c.Rows {
		_ = k
		if r.From == from && r.Active {
			out = append(out, r.SrcID)
		}
	}
	sort.Strings(out)
	return out
}

// reconcile 跑一次对账。返回报告条目。
func reconcile(f *FinanceView, c *CalendarView, graceHours int, nowHour int) []Report {
	var rep []Report

	// ① 孤儿注册项：calendar 里有、business 侧没有（且不在宽限期内）
	live := map[string]bool{}
	for id, b := range f.Bills {
		if b.DeletedAt == "" {
			live[id] = true
		}
	}
	for _, r := range c.Rows {
		if r.From != "finance" || !r.Active {
			continue
		}
		if live[r.SrcID] {
			continue
		}
		// 宽限期：刚注册的可能 business 侧快照还没更新（最终一致窗口）
		age := nowHour // 简化：注册于 T0，对账在 T0+N 小时跑
		if age < graceHours {
			rep = append(rep, Report{
				Kind: "pending_grace", Face: "finance", ID: r.SrcID,
				Detail: fmt.Sprintf("刚注册 %d 小时，对账快照还没追上，暂不判定", age),
				Action: "跳过", Severity: "info",
			})
			continue
		}
		rep = append(rep, Report{
			Kind: "orphan_reminder", Face: "finance", ID: r.SrcID,
			Detail:   "calendar_reminder 生效中，但 finance 侧无对应活对象",
			Action:   "撤销（active=false, revoke_reason=reconcile_orphan）",
			Severity: "warn",
		})
	}

	// ② 漏注册：business 有 due_at、calendar 没有
	for id, b := range f.Bills {
		if b.DeletedAt != "" || b.DueAt == "" {
			continue
		}
		found := false
		for _, r := range c.Rows {
			if r.From == "finance" && r.SrcID == id && r.Active {
				found = true
			}
		}
		if !found {
			rep = append(rep, Report{
				Kind: "missing_reminder", Face: "finance", ID: id,
				Detail:   "finance 侧对象有 due_at，calendar 无生效注册项",
				Action:   "补注册（重发 due.registered，幂等键保证不重复）",
				Severity: "warn",
			})
		}
	}

	sort.Slice(rep, func(i, j int) bool {
		if rep[i].Kind != rep[j].Kind {
			return rep[i].Kind < rep[j].Kind
		}
		return rep[i].ID < rep[j].ID
	})
	return rep
}

func printReport(rep []Report, title string) {
	hdr(title)
	if len(rep) == 0 {
		fmt.Println("  （空账：对账通过）")
		return
	}
	for _, r := range rep {
		sev := map[string]string{"info": "INFO", "warn": "WARN", "fatal": "FATAL"}[r.Severity]
		fmt.Printf("  [%-5s] %-18s %-9s %s\n", sev, r.Kind, r.ID, r.Detail)
		fmt.Printf("             处置：%s\n", r.Action)
	}
	fmt.Printf("\n  合计 %d 条：", len(rep))
	cnt := map[string]int{}
	for _, r := range rep {
		cnt[r.Kind]++
	}
	keys := []string{}
	for k := range cnt {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for i, k := range keys {
		if i > 0 {
			fmt.Print("  ")
		}
		fmt.Printf("%s=%d", k, cnt[k])
	}
	fmt.Println()
}

func main() {
	hdr("背景：孤儿注册项是怎么产生的")

	type cause struct {
		how      string
		who      string
		howOften string
	}
	causes := []cause{
		{"删除钩子漏了撤销（d9 路径 ④）", "业务代码缺陷", "最常见"},
		{"撤销意图写进 outbox 后进程崩溃，投递器没扫到", "基础设施", "偶发"},
		{"撤销投递失败，超过 3 次进死信没人管", "运维流程缺失", "偶发但危害大"},
		{"业务对象被别的服务/脚本直接改了表，绕过 service", "架构违规", "罕见但最难查"},
		{"回滚不一致：业务回滚了但 outbox 没回滚（或反之）", "事务边界写错", "罕见"},
	}
	fmt.Printf("  %-44s %-14s %s\n", "产生原因", "归属", "频率")
	fmt.Println("  " + strings.Repeat("-", 90))
	for _, c := range causes {
		fmt.Printf("  %-44s %-14s %s\n", c.how, c.who, c.howOften)
	}
	fmt.Println()
	fmt.Println("  共同特征：**没有任何一个环节会报错**。")
	fmt.Println("  幽灵提醒会正常触发、正常通知、正常回写失败进对账。")
	fmt.Println("  所以它只能被「主动对账」发现，不能被「等报错」发现。")

	// =================================================================
	hdr("为什么必须走「每日对账」而不是跨 schema 直接查")

	fmt.Println("  有人会问：让对账任务直接 JOIN 两张表不就行了？")
	fmt.Println("  技术方案 §10.3 第 1 条：禁止跨 schema SQL、DBLink、只读视图、共用账号。")
	fmt.Println("  原因不是性能，是**边界**：")
	fmt.Println("    如果数据库账号能跨 schema 读，那它就能跨 schema 写。")
	fmt.Println("    边界一旦只在文档里，就是迟早会被某次「就查一下」突破。")
	fmt.Println()
	fmt.Println("  所以对账的做法是：")
	fmt.Println("    ① 各面各自导出本面清单（只查自己的库，合法）")
	fmt.Println("    ② 清单交给对账进程（一个独立的、可重跑的批任务）")
	fmt.Println("    ③ 在对账进程里做集合运算，发现差异 → 产出报表 + 告警")
	fmt.Println("  「跨面一致性」由**进程**保证，不由数据库的 JOIN 保证。")

	// =================================================================
	// 造一批真实场景的数据
	// =================================================================
	fin := &FinanceView{Bills: map[string]*Bill{}}
	addBill := func(id, title, due string, deleted bool) {
		d := ""
		if deleted {
			d = "2026-03-02T10:00:00+08:00"
		}
		fin.Bills[id] = &Bill{ID: id, Family: "fam-001", Title: title, DueAt: due, Status: "unpaid", DeletedAt: d}
	}
	addBill("bill-001", "房贷 3 月期", "2026-03-05T09:00:00+08:00", false)
	addBill("bill-002", "物业费 Q1", "2026-03-20T09:00:00+08:00", true) // 删了但没撤销 → 孤儿
	addBill("rp-014", "公积金还款 第 4 期", "2026-03-12T09:00:00+08:00", false)
	addBill("goal-007", "存款目标 5 万 截止", "2026-09-30T09:00:00+08:00", false) // 有 due_at 但没注册 → 漏注册
	addBill("bill-020", "车险", "2026-04-01T09:00:00+08:00", true)           // 刚删（宽限期内）

	cal := &CalendarView{Rows: map[string]*CalRow{}}
	addRem := func(id, title, due string) {
		k := "finance|" + id + "|reminder"
		cal.Rows[k] = &CalRow{From: "finance", SrcID: id, Kind: "reminder",
			Title: title, DueAt: due, Active: true, RegisteredAt: "2026-03-01T00:00:00+08:00"}
	}
	addRem("bill-001", "房贷 3 月期", "2026-03-05T09:00:00+08:00")
	addRem("bill-002", "物业费 Q1", "2026-03-20T09:00:00+08:00")
	addRem("bill-020", "车险", "2026-04-01T09:00:00+08:00")
	addRem("rp-014", "公积金还款 第 4 期", "2026-03-12T09:00:00+08:00")

	hdr("数据现状")
	fmt.Println("  finance.finance_bill（活对象）：")
	ids := []string{}
	for id, b := range fin.Bills {
		if b.DeletedAt == "" {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	fmt.Printf("    %v\n", ids)
	fmt.Println("  已软删：")
	ids = []string{}
	for id, b := range fin.Bills {
		if b.DeletedAt != "" {
			ids = append(ids, id)
		}
	}
	sort.Strings(ids)
	fmt.Printf("    %v\n", ids)
	fmt.Println("  calendar.calendar_reminder 生效中：")
	fmt.Printf("    %v\n", cal.ListFor("finance"))

	// =================================================================
	// 宽限期对比
	// =================================================================
	printReport(reconcile(fin, cal, 24, 2), "对账①  宽限期 24 小时，现在是对账后第 2 小时")
	fmt.Println()
	fmt.Println("  bill-020 刚删 2 小时，对账快照还没追上 → 判 pending_grace，不误伤。")
	fmt.Println("  这就是宽限期存在的唯一理由：**最终一致需要一个缓冲**。")
	fmt.Println("  没有宽限期的话，每个正常删除都会在对账里报一次孤儿，产生大量假告警，")
	fmt.Println("  真告警反而被淹没 —— 这比没有告警更糟。")

	printReport(reconcile(fin, cal, 24, 30), "对账②  宽限期 24 小时，现在是对账后第 30 小时")
	fmt.Println()
	fmt.Println("  bill-020 超过宽限期，判为真孤儿 → 撤销。")
	fmt.Println("  bill-002 是 d9 路径 ④ 那种漏写撤销的，30 小时后被抓出来。")
	fmt.Println("  goal-007 反过来：business 有 due_at 而 calendar 没有 → 补注册。")

	// =================================================================
	hdr("为什么处置是「撤销」而不是「删除」")

	type choice struct {
		how     string
		ok      bool
		problem string
	}
	choices := []choice{
		{"物理 DELETE calendar_reminder 行", false, "不可逆。查不出「为什么消失了」，对账报表失去证据；改期后的重新注册会产生新 id"},
		{"UPDATE active=false + revoke_reason=reconcile_orphan", true, "保留全部历史，且 revoke_reason 直接说明「是对账发现的」"},
		{"UPDATE active=false 但不记 reason", false, "分不清是用户删的还是对账清的，统计口径全乱"},
	}
	fmt.Printf("  %-56s %-6s %s\n", "处置方式", "可行", "问题")
	fmt.Println("  " + strings.Repeat("-", 106))
	for _, c := range choices {
		fmt.Printf("  %-56s %-6s %s\n", c.how, map[bool]string{true: "✅", false: "❌"}[c.ok], c.problem)
	}
	fmt.Println()
	fmt.Println("  对账发现的孤儿，reconcile_orphan 这个 reason 值本身就是资产：")
	fmt.Println("  它让「级联失效失效率」变成一个可观测指标 ——")
	fmt.Println("  如果这个值是 0，说明钩子都写对了；一旦上升，就是代码回退了。")

	// =================================================================
	hdr("对账任务的四条判据（对齐 PRD 18.6）")
	// =================================================================
	criteria := []struct {
		id   string
		text string
		pass bool
	}{
		{"18.6-1", "对账每天跑，跑完产出一份报表（不是只发告警）", true},
		{"18.6-2", "孤儿引用进报表并告警；**不自动修**，先看再修", true},
		{"18.6-3", "「0 条孤儿」才判通过 —— 不允许「不判定」", true},
		{"18.6-4", "对账本身要可重跑：跑第二遍结果必须与第一遍一致", true},
	}
	for _, c := range criteria {
		fmt.Printf("  [%s] %-8s %s  %s\n", map[bool]string{true: "✅", false: "❌"}[c.pass], c.id, c.text,
			map[bool]string{true: "", false: ""}[c.pass])
	}
	fmt.Println()
	fmt.Println("  第 2 条「不自动修」值得多说一句：自动修听起来更安全，但它是危险的。")
	fmt.Println("  原因是对账的判断基于**快照**：")
	fmt.Println("    对账进程在 T 时刻拉 finance 清单，在 T+2 秒拉 calendar 清单，")
	fmt.Println("    这 2 秒里发生的写操作，会让「活对象」看起来像孤儿。")
	fmt.Println("  宽限期能覆盖大部分，但覆盖不了「clock skew」与「长事务」。")
	fmt.Println("  自动修 = 用一个可能误判的判断去改生产数据。所以：")
	fmt.Println("    **对账只判定与告警，处置由人或由明确授权的补偿任务执行。**")

	// =================================================================
	hdr("对账任务本身的可重跑性：真跑两遍")
	// =================================================================
	r1 := reconcile(fin, cal, 24, 30)
	r2 := reconcile(fin, cal, 24, 30)
	same := len(r1) == len(r2)
	for i := range r1 {
		if r1[i] != r2[i] {
			same = false
		}
	}
	fmt.Printf("  第一次 %d 条，第二次 %d 条，逐条相同：%s\n", len(r1), len(r2),
		map[bool]string{true: "✅ 可重跑", false: "❌ 不可重跑"}[same])
	fmt.Println()
	fmt.Println("  做到可重跑的三条纪律：")
	fmt.Println("    ① 对账只读不写业务表（写的是自己的报表表）")
	fmt.Println("    ② 报表按 (kind, face, id) 唯一键 UPSERT，重跑覆盖而不是追加")
	fmt.Println("    ③ 不在报告里写时间戳之外的非确定值（比如「耗时 1.2s」）")
	fmt.Println()
	fmt.Println("  ⚠ Go 的坑：map 遍历顺序随机。上面代码里如果直接 range map 生成报表，")
	fmt.Println("    两次运行顺序会不同 → 对不上一致性。")
	fmt.Println("    修法是打印前排序（sort.Slice）。本程序所有输出都经过排序，所以双跑一致。")

	// =================================================================
	hdr("孤儿的两面：类型 B（反向的孤儿）")
	// =================================================================
	fmt.Println("  类型 B：finance 引用了一个 calendar 里不存在的 id。")
	fmt.Println("  例如 Transaction.receipt 存了 homeos.File 的 file_id，附件被删了。")
	fmt.Println("  这是技术方案 §7.1「逻辑 id 引用」的固有风险：")
	fmt.Println("    跨服务没有外键，引用完整性只能靠约定 + 对账。")
	fmt.Println("  本项目当前面目录里唯一的实例是 finance 引用 homeos.File，")
	fmt.Println("  它不在 S9 的注册链路上，但用的是**同一套对账机制**。")
	fmt.Println()
	fmt.Println("  一句话记住两类孤儿：")
	fmt.Println("    类型 A：calendar 有、business 没有 → 提醒会响没人管")
	fmt.Println("    类型 B：business 有、calendar 没有 → 要用时找不到（下次刷新就自愈）")
	fmt.Println("  A 危害更大，因为它**主动打扰用户**；B 只会自己恢复。")

	fmt.Println("\n=== W35 d10 到此结束 ===")
	fmt.Println("明天讲不注册清单：哪些对象压根不该注册，注册了反而是错的。")
}

