func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 判定规则：三问
// =====================================================================

type Candidate struct {
	Name        string
	Face        string
	HasDue      bool
	TableKind   string // business / projection / history_fact / runtime / config
	TriggerType string // timer / event_driven / none
	AlreadyDone bool
	Verdict     string
	Reason      string
}

// shouldRegister 实现三条判据。顺序很重要，先排除再肯定。
func shouldRegister(c Candidate) (bool, string) {
	// 判据一：投影表一律不注册（它已经是别人的副本）
	if c.TableKind == "projection" {
		return false, "投影表 {code}_proj_* —— 它本身就是别的面的数据的副本，再注册就是第二份真相"
	}
	// 判据二：历史事实类不注册（已发生的事不需要提醒）
	if c.TableKind == "history_fact" || c.AlreadyDone {
		return false, "历史事实类 —— 已发生的事没有「到期」语义，提醒一个已经过去的时间点毫无意义"
	}
	// 判据四：事件驱动的通知不注册（这是本项目最常被搞错的一条）
	// 注意它必须排在「没有 due_at」之前 —— Budget 超支恰恰是「既没有 due_at
	// 又是事件驱动」，只按 due_at 判会给出「无时间点不入」这个正确结论但错误的理由，
	// 理由错了，将来有人会给它硬造一个 due_at 来绕过判定。
	if c.TriggerType == "event_driven" {
		return false, "事件驱动 ≠ 定时来源。预算超支在 finance 内部判断后发 finance.budget.exceeded，homeos 消费它落通知；把它注册到到期中心会造出「一个月后提醒我上次超支了」这种幽灵"
	}
	// 判据五：运行表 / 配置表不注册
	if c.TableKind == "runtime" || c.TableKind == "config" {
		return false, "运行表族与配置表不是业务对象，注册它们会让到期中心变成一个杂货铺"
	}
	// 判据六：没有时间点的不注册
	if c.TriggerType == "none" || !c.HasDue {
		return false, "对象没有 due_at —— 到期中心是围绕「时间点」建的，无时间点不入"
	}
	// 通过
	return true, "有时间语义 + 定时触发 + 是业务对象 → 注册"
}

