// ---- 一个最小的 calendar，用于跑「错误注册」的后果 ----

type MiniRow struct {
	From, SrcID, Kind, Title, DueAt string
	Active                          bool
}

type MiniCal struct{ rows []MiniRow }

func (c *MiniCal) Upsert(from, id, kind, title, dueAt string) {
	for i := range c.rows {
		if c.rows[i].From == from && c.rows[i].SrcID == id {
			c.rows[i].Title, c.rows[i].DueAt, c.rows[i].Active = title, dueAt, true
			return
		}
	}
	c.rows = append(c.rows, MiniRow{From: from, SrcID: id, Kind: kind, Title: title, DueAt: dueAt, Active: true})
}

func (c *MiniCal) Active() int {
	n := 0
	for _, r := range c.rows {
		if r.Active {
			n++
		}
	}
	return n
}

func (c *MiniCal) Titles() string {
	out := []string{}
	for _, r := range c.rows {
		if r.Active {
			out = append(out, r.Title)
		}
	}
	return strings.Join(out, ", ")
}

// =====================================================================
// W35 d12：收口 —— 撤销链路端到端 + 判据自查。
//
// 今天把 d7~d11 串成一条完整链路：
//   业务对象的四种变化 → 是否撤销 → 撤销意图 → 进程内投递 → calendar 处置
//   → 漏掉的那些 → 每日对账抓出来
//
// 判据（W35 相关）：
//   2. 业务对象删除 → 对应注册项级联失效
// 以及 W35 的隐性要求：不注册清单 / 三种 reason 可区分 / 对账可重跑。
// =====================================================================

package main

import (
	"fmt"
	"sort"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 全链路模型
// =====================================================================

type Reg struct {
	From, ID, Kind, Family, Title, DueAt, Priority string
	Repeat, Visibility                             string
	DoneReturnsTo                                  string
}

type Intent struct {
	Type      string // finance.due.registered / finance.due.revoked
	Business  string // business_id
	Payload   Reg
	Reason    string
	PrevDueAt string
	State     string // pending / delivered / failed
}

type Platform struct{ intents []Intent }

func (p *Platform) Register(r Reg) {
	p.intents = append(p.intents, Intent{
		Type: "finance.due.registered", Business: r.ID, Payload: r, State: "pending",
	})
}
func (p *Platform) Revoke(id, kind, reason, prevDue string) {
	p.intents = append(p.intents, Intent{
		Type: "finance.due.revoked", Business: id,
		Payload: Reg{From: "finance", ID: id, Kind: kind}, Reason: reason,
		PrevDueAt: prevDue, State: "pending",
	})
}

type CalRow struct {
	From, ID, Kind, Title, DueAt, Priority string
	Active                                 bool
	RevokeReason                           string
}

type Cal struct{ rows []CalRow }

func (c *Cal) Upsert(r Reg) string {
	for i := range c.rows {
		if c.rows[i].From == r.From && c.rows[i].ID == r.ID && c.rows[i].Kind == r.Kind {
			c.rows[i].Title, c.rows[i].DueAt, c.rows[i].Priority, c.rows[i].Active = r.Title, r.DueAt, r.Priority, true
			return "updated"
		}
	}
	c.rows = append(c.rows, CalRow{From: r.From, ID: r.ID, Kind: r.Kind,
		Title: r.Title, DueAt: r.DueAt, Priority: r.Priority, Active: true})
	return "inserted"
}

func (c *Cal) Revoke(from, id, kind, reason string) string {
	for i := range c.rows {
		if c.rows[i].From == from && c.rows[i].ID == id && c.rows[i].Kind == kind {
			if !c.rows[i].Active {
				return "already_revoked(幂等)"
			}
			c.rows[i].Active, c.rows[i].RevokeReason = false, reason
			return "revoked"
		}
	}
	return "not_found"
}

func (c *Cal) Active() int {
	n := 0
	for _, r := range c.rows {
		if r.Active {
			n++
		}
	}
	return n
}

func (p *Platform) Dispatch(c *Cal) (int, int) {
	ok, bad := 0, 0
	for i := range p.intents {
		if p.intents[i].State != "pending" {
			continue
		}
		var res string
		if p.intents[i].Type == "finance.due.registered" {
			res = c.Upsert(p.intents[i].Payload)
		} else {
			res = c.Revoke("finance", p.intents[i].Payload.ID, p.intents[i].Payload.Kind, p.intents[i].Reason)
			if res == "not_found" {
				p.intents[i].State = "failed"
				bad++
				continue
			}
		}
		p.intents[i].State = "delivered"
		_ = res
		ok++
	}
	return ok, bad
}

// ---- business 侧 ----

type Bill struct {
	ID, Title, DueAt, Status string
	DeletedAt                string
}

type Biz struct {
	bills []*Bill
	p     *Platform
}

func mkReg(b *Bill) Reg {
	return Reg{From: "finance", ID: b.ID, Kind: "reminder", Family: "fam-001",
		Title: b.Title, DueAt: b.DueAt, Priority: "high", Repeat: "none",
		Visibility: "family", DoneReturnsTo: "finance:" + b.ID + ":mark_paid"}
}

func (z *Biz) Create(id, title, due string) {
	z.bills = append(z.bills, &Bill{ID: id, Title: title, DueAt: due, Status: "unpaid"})
	z.p.Register(mkReg(z.bills[len(z.bills)-1]))
}
func (z *Biz) Live(id string) *Bill {
	for _, b := range z.bills {
		if b.ID == id && b.DeletedAt == "" {
			return b
		}
	}
	return nil
}
func (z *Biz) Any(id string) *Bill {
	for _, b := range z.bills {
		if b.ID == id {
			return b
		}
	}
	return nil
}
func (z *Biz) Delete(id string, hook bool) {
	b := z.Live(id)
	if b == nil {
		return
	}
	if hook {
		z.p.Revoke(id, "reminder", "source_deleted", b.DueAt) // ★ 钩子
	}
	b.DeletedAt = "2026-03-02T10:00:00+08:00"
}
func (z *Biz) Reschedule(id, due string) {
	b := z.Live(id)
	if b == nil {
		return
	}
	b.DueAt = due
	z.p.Register(mkReg(b)) // 同键覆盖，不撤销
}
func (z *Biz) MarkPaidEarly(id string) {
	b := z.Live(id)
	if b == nil {
		return
	}
	b.Status = "paid"
	z.p.Revoke(id, "reminder", "completed_early", b.DueAt)
}
func (z *Biz) Rename(id, title string) {
	b := z.Live(id)
	if b == nil {
		return
	}
	b.Title = title
	z.p.Register(mkReg(b)) // 同键覆盖
}

