func countType(is []Intent, t string) int {
	n := 0
	for _, x := range is {
		if x.Type == t {
			n++
		}
	}
	return n
}

func countLive(bs []*Bill) int {
	n := 0
	for _, b := range bs {
		if b.DeletedAt == "" {
			n++
		}
	}
	return n
}

