// W36 d13：完成回写为什么是必需的 —— 不回写就是缺陷。
//
// PRD 16.4：「注册项被用户在到期中心完成 → 回写业务面对象状态，
//           （done_returns_to 指定的回调），不回写视为缺陷。」
//
// 今天不讲怎么回写（d15），只讲「为什么必须有」，并且真跑出后果。
// 关键：后果不是「报错」，是「数据静默分叉」。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// ---- 两边的状态 ----

type Bill struct {
	ID, Title, DueAt, Status string
	AmountCents              int64 // 铁律 1：金额一律整数分，禁浮点
	PaidAt                   string
	Version                  int
}

type Finance struct{ Bills []*Bill }

func (f *Finance) ByID(id string) *Bill {
	for _, b := range f.Bills {
		if b.ID == id {
			return b
		}
	}
	return nil
}

// ---- calendar 侧 ----

type Todo struct {
	ID, SrcSystem, SrcID, Title, DoneReturnsTo string
	Completed                                  bool
	LocalState                                 string // calendar 自己记的「已完成」
}

type Calendar struct {
	Todos  []*Todo
	Notifs []string
	// 回写结果对账流水
	WritebackLog []string
}

func (c *Calendar) ListToday() []string {
	out := []string{}
	for _, t := range c.Todos {
		if !t.Completed {
			out = append(out, t.Title)
		}
	}
	return out
}

// 完成一条待办。有回写 / 无回写两个版本。
func (c *Calendar) CompleteWithWriteback(t *Todo, f *Finance) string {
	t.Completed = true
	t.LocalState = "done"
	if t.DoneReturnsTo == "" {
		c.WritebackLog = append(c.WritebackLog, "MISSING: "+t.ID+" 无 done_returns_to，回写丢失")
		return "本地标记完成（回写丢失）"
	}
	// 解析 "finance:bill-001:mark_paid"
	p := strings.Split(t.DoneReturnsTo, ":")
	if len(p) != 3 {
		return "done_returns_to 格式错误"
	}
	b := f.ByID(p[1])
	if b == nil {
		c.WritebackLog = append(c.WritebackLog, "FAIL: "+t.ID+" → "+p[1]+" 不存在")
		return "回写失败：目标对象不存在"
	}
	if b.Status == "paid" {
		c.WritebackLog = append(c.WritebackLog, "IDEMPOTENT: "+t.ID+" 已是 paid")
		return "回写幂等：已是 paid"
	}
	b.Status = "paid"
	b.PaidAt = "2026-03-04T21:12:00+08:00"
	b.Version++
	c.WritebackLog = append(c.WritebackLog, "OK: "+t.ID+" → "+p[1]+" paid v"+itoa(b.Version))
	return "回写成功"
}

func (c *Calendar) CompleteNoWriteback(t *Todo) string {
	t.Completed = true
	t.LocalState = "done"
	c.WritebackLog = append(c.WritebackLog, "MISSING: "+t.ID+" 无 done_returns_to，回写丢失")
	return "本地标记完成（回写丢失）"
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	s := ""
	for n > 0 {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	return s
}

