// ---- 迷你模型 ----

type BizRow struct {
	Status  string
	PaidAt  string
	Version int
}

type MiniBiz struct{ rows map[string]*BizRow }

func (b *MiniBiz) apply(id, status string) { // 模拟反向指令
	r := b.rows[id]
	if r == nil {
		return
	}
	r.Status = status
	r.Version++
}

func applyCmd(b *MiniBiz, id, status string) { b.apply(id, status) }

type MiniRow struct {
	SrcID       string
	Completed   bool
	CompletedAt string
}

type MiniCal struct{ rows map[string]*MiniRow }

// =====================================================================
// W36 d15：回写的实现 —— done_returns_to 的解析与调用。
//
// 今天落地三件事，每件都有真实的安全/正确性后果：
//   ① 解析：三段式 + 严格校验（d4 讲过格式，这里实现）
//   ② 路由：action → handler 的注册表（**不是**反射、不是 map[string]any）
//   ③ 调用：把 member_id / completed_at 一起带过去（d13 的三个必带项）
//
// 本项目是进程内调用，所以「找到 handler」= 从一个 map 里取函数。
// 但这个 map 必须是**启动时显式注册**的，而不是运行时从字符串拼出来的。
// =====================================================================

package main

import (
	"errors"
	"fmt"
	"sort"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// platform 层：完成回写的接口与 handler 类型
// =====================================================================

// DoneCallback 是「业务面完成一次后要做什么」的抽象。
//
// 第一个参数是 payload（发生了什么），不是目标状态（应该变成什么）——
// d14 的核心结论：calendar 只传事实，不传指令。
type DoneCallback func(DoneEvent) error

type DoneEvent struct {
	SourceSystem string
	SourceID     string
	Action       string
	MemberID     string // 谁点的（PRD 有 on_behalf_of）
	CompletedAt  string // 什么时候点的（不是业务上的还款日）
	FamilyID     string
	TodoID       string // calendar 侧 id，幂等用
}

// DueWriteback 是 platform 暴露给 calendar 的唯一入口（铁律 9）
type DueWriteback interface {
	Resolve(doneReturnsTo string) (DoneCallback, string, string, error)
	Writeback(e DoneEvent) (WritebackResult, error)
}

type WritebackResult struct {
	OK      bool
	Idem    bool   // 幂等命中（已经写过）
	Changed string // 实际发生了什么
	Version int
}

// ErrNoHandler 是「找不到处理器」——它不是运行时错误，是**配置错误**
var ErrNoHandler = errors.New("action 未注册到 handler 表")

// =====================================================================
// 注册表
// =====================================================================

type Registry struct {
	// key = "finance:mark_paid"（system:action，不是 system:id:action）
	handlers map[string]DoneCallback
	// 幂等：已回写过的 (system, id, action)
	idem map[string]WritebackResult
	log  []string
}

func NewRegistry() *Registry {
	return &Registry{handlers: map[string]DoneCallback{}, idem: map[string]WritebackResult{}}
}

// Register 是**启动时**（wiring 阶段）调用的，业务代码从不调它。
func (r *Registry) Register(system, action string, fn DoneCallback) {
	r.handlers[system+":"+action] = fn
}

func (r *Registry) Resolve(doneReturnsTo string) (DoneCallback, string, string, error) {
	p := strings.Split(doneReturnsTo, ":")
	if len(p) != 3 {
		return nil, "", "", fmt.Errorf("格式错误：应为 {system}:{id}:{action}，实得 %d 段", len(p))
	}
	sys, id, action := p[0], p[1], p[2]
	if sys == "" || id == "" || action == "" {
		return nil, "", "", fmt.Errorf("三段都不能为空")
	}
	if !r.allowed(sys, action) {
		return nil, "", "", fmt.Errorf("%w：%s:%s", ErrNoHandler, sys, action)
	}
	return r.handlers[sys+":"+action], sys, id, nil
}

// allowed 就是 action 白名单。真实实现里它来自 registry（面登记表），
// 而不是这里 hardcode —— 但性质相同：**只有登记过的 action 才能跑**。
func (r *Registry) allowed(sys, action string) bool {
	_, ok := r.handlers[sys+":"+action]
	return ok
}

func (r *Registry) Writeback(e DoneEvent) (WritebackResult, error) {
	key := e.SourceSystem + "|" + e.SourceID + "|" + e.Action
	if prev, ok := r.idem[key]; ok {
		r.log = append(r.log, "IDEMPOTENT "+key)
		prev.Idem = true
		return prev, nil
	}
	fn, sys, id, err := r.Resolve(e.SourceSystem + ":" + e.SourceID + ":" + e.Action)
	if err != nil {
		r.log = append(r.log, "FAIL "+key+" err="+err.Error())
		return WritebackResult{}, err
	}
	// 用注册时的值覆盖，防止调用方伪造 sys/id（它们应该来自 done_returns_to）
	e2 := e
	e2.SourceSystem, e2.SourceID = sys, id
	if err := fn(e2); err != nil {
		r.log = append(r.log, "FAIL "+key+" err="+err.Error())
		return WritebackResult{}, err
	}
	r.idem[key] = WritebackResult{OK: true}
	r.log = append(r.log, "OK "+key)
	return WritebackResult{OK: true}, nil
}

// =====================================================================
// 业务侧：finance 的三个对象与它们的 handler
// =====================================================================

type Bill struct {
	ID, Title, Status, PaidAt, DeletedAt string
	Version                              int
}

type RepaymentPlan struct {
	ID, Title, Status, PaidAt string
	Version                   int
}

type Goal struct {
	ID, Title, Status, AchievedAt string
	Version                       int
}

type Finance struct {
	Bills map[string]*Bill
	Plans map[string]*RepaymentPlan
	Goals map[string]*Goal
}

func newFinance() *Finance {
	return &Finance{
		Bills: map[string]*Bill{
			"bill-001": {ID: "bill-001", Title: "房贷 3 月期", Status: "unpaid", Version: 1},
		},
		Plans: map[string]*RepaymentPlan{
			"rp-014": {ID: "rp-014", Title: "公积金还款 第 4 期", Status: "unpaid", Version: 1},
		},
		Goals: map[string]*Goal{
			"goal-007": {ID: "goal-007", Title: "存款目标 5 万", Status: "active", Version: 1},
		},
	}
}

// mark_paid：业务规则全在业务面这一侧
func (f *Finance) MarkPaid(e DoneEvent) error {
	b := f.Bills[e.SourceID]
	if b == nil {
		return fmt.Errorf("账单不存在")
	}
	if b.DeletedAt != "" {
		return fmt.Errorf("账单已软删，不接受完成回写（返 404 等价）")
	}
	if b.Status == "paid" {
		return nil // 幂等
	}
	if b.Status != "unpaid" {
		return fmt.Errorf("状态机不允许 unpaid → paid（当前 %s）", b.Status)
	}
	b.Status = "paid"
	// ★ 关键：paid_at 由业务面自己取「业务上的还款日」。
	//   本项目简化为「回写时刻」，真实实现可以是「用户填的还款日」或「银行流水日」。
	b.PaidAt = e.CompletedAt
	b.Version++
	return nil
}

func (f *Finance) MarkRepaid(e DoneEvent) error {
	p := f.Plans[e.SourceID]
	if p == nil {
		return fmt.Errorf("还款计划不存在")
	}
	if p.Status == "repaid" {
		return nil
	}
	p.Status = "repaid"
	p.PaidAt = e.CompletedAt
	p.Version++
	return nil
}

func (f *Finance) MarkReached(e DoneEvent) error {
	g := f.Goals[e.SourceID]
	if g == nil {
		return fmt.Errorf("目标不存在")
	}
	if g.Status == "reached" {
		return nil
	}
	g.Status = "reached"
	g.AchievedAt = e.CompletedAt
	g.Version++
	return nil
}

// =====================================================================
// calendar 侧：完成一个待办
// =====================================================================

type Todo struct {
	ID, SrcID, Title, DoneReturnsTo string
	Completed                       bool
	CompletedAt                     string
	CompletedBy                     string
}

type Calendar struct {
	Todos  []*Todo
	wb     DueWriteback
	Notify []string
}

func (c *Calendar) Complete(todoID, memberID, at string) string {
	var t *Todo
	for _, x := range c.Todos {
		if x.ID == todoID {
			t = x
		}
	}
	if t == nil {
		return "待办不存在"
	}
	if t.Completed {
		return "已完成（幂等短路，不重复回写）"
	}
	if t.DoneReturnsTo == "" {
		t.Completed = true
		return "本地完成，回写丢失（done_returns_to 为空）"
	}
	// ① 写自己的字段
	t.Completed, t.CompletedAt, t.CompletedBy = true, at, memberID
	// ② 构造 DoneEvent（只传事实）
	e := DoneEvent{
		Action:   "", // 由 Resolve 解析出来，这里不填
		MemberID: memberID, CompletedAt: at, FamilyID: "fam-001", TodoID: t.ID,
	}
	// ③ 调 platform
	_, sys, id, err := c.wb.Resolve(t.DoneReturnsTo)
	if err != nil {
		return "回写失败：" + err.Error()
	}
	e.SourceSystem, e.SourceID = sys, id
	e.Action = strings.Split(t.DoneReturnsTo, ":")[2]
	res, err := c.wb.Writeback(e)
	if err != nil {
		return "回写失败：" + err.Error()
	}
	if res.Idem {
		return "回写幂等命中"
	}
	return "回写成功"
}

func main() {
