// =====================================================================
// W36 d16：回写失败的兜底 —— 业务服务不可达时怎么办。
//
// 判据第 3 条的完整含义：「在到期中心点完成 → 业务对象状态真的被回写，
// 不回写视为缺陷」。「真的」两个字意味着要有兜底，不是试一次就完。
//
// tech-plan §7.5 的事件治理：at-least-once + 消费端幂等；
// 重试指数退避最多 3 次；超限进死信。
//
// 本项目砍掉了总线，但这套治理**一个字不能少** ——
// 少一个字就等于砍掉了保护。今天把它真跑出来。
// =====================================================================

package main

import (
	"errors"
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 错误分类：这是 d16 最核心的一步
// =====================================================================

type ErrKind int

const (
	// 可重试：目标可能恢复，重试有意义
	KindUnavailable ErrKind = iota // 服务不可达 / 超时 / 连接被拒
	KindConflict                   // 乐观锁冲突 / 状态机暂时不允许
	// 不可重试：重试 100 次也是同样结果
	KindNotFound   // 对象不存在 / 已软删
	KindForbidden  // 越权（返 404 等价）
	KindBadRequest // 契约不合法（action 未注册、格式错）
)

func (k ErrKind) String() string {
	switch k {
	case KindUnavailable:
		return "Unavailable"
	case KindConflict:
		return "Conflict"
	case KindNotFound:
		return "NotFound"
	case KindForbidden:
		return "Forbidden"
	case KindBadRequest:
		return "BadRequest"
	}
	return "Unknown"
}

func (k ErrKind) Retryable() bool { return k == KindUnavailable || k == KindConflict }

type WbError struct {
	Kind ErrKind
	Msg  string
}

func (e *WbError) Error() string { return e.Kind.String() + ": " + e.Msg }

func (e *WbError) Retryable() bool { return e.Kind.Retryable() }

func mkErr(k ErrKind, m string) error { return &WbError{Kind: k, Msg: m} }

// =====================================================================
// 回写任务
// =====================================================================

type Task struct {
	TodoID, System, ID, Action, MemberID, CompletedAt string
	Attempt                                           int
	State                                             string // pending / delivered / dead
	LastErr                                           string
}

type Business struct {
	// 可用性开关：模拟「业务服务不可达」
	reachable bool
	rows      map[string]string // id → status
	log       []string
}

func (b *Business) set(id, v string) { b.rows[id] = v }

// Apply 是业务面真正的 handler。它返回的错误必须带 Kind。
func (b *Business) Apply(t *Task) error {
	if !b.reachable {
		return mkErr(KindUnavailable, "连接被拒绝：finance 服务未启动")
	}
	cur, ok := b.rows[t.ID]
	if !ok {
		return mkErr(KindNotFound, "对象不存在或已软删")
	}
	if cur == "paid" {
		return nil // 幂等
	}
	if cur == "voided" {
		return mkErr(KindForbidden, "对象已作废，拒绝回写")
	}
	b.set(t.ID, "paid")
	b.log = append(b.log, fmt.Sprintf("OK %s → paid", t.ID))
	return nil
}

// =====================================================================
// 重试器：指数退避，最多 3 次
// =====================================================================

const maxAttempts = 3

// backoff 返回第 n 次重试的等待毫秒数（固定序列，不真 sleep，保证输出确定）
func backoff(n int) []int { return []int{100, 400, 1600} }

type Outbox struct{ tasks []*Task }

func (o *Outbox) Enqueue(t *Task) {
	c := *t
	c.State = "pending"
	o.tasks = append(o.tasks, &c)
}

// Run 一轮投递：对每个未完成任务尝试一次。
// 返回本轮结果摘要。
func (o *Outbox) Run(b *Business, nowMS int) (delivered, retried, deaded int) {
	wait := backoff(0)
	for _, t := range o.tasks {
		if t.State != "pending" {
			continue
		}
		// 退避未到，跳过（时间用固定步进模拟，不真 sleep）
		if t.Attempt > 0 {
			need := wait[t.Attempt-1]
			if nowMS < need {
				continue
			}
		}
		t.Attempt++
		err := b.Apply(t)
		if err == nil {
			t.State = "delivered"
			delivered++
			continue
		}
		var we *WbError
		if errors.As(err, &we) {
			t.LastErr = we.Error()
			if !we.Retryable() {
				t.State = "dead"
				deaded++
				continue
			}
		} else {
			t.LastErr = err.Error()
			t.State = "dead"
			deaded++
			continue
		}
		if t.Attempt >= maxAttempts {
			t.State = "dead"
			deaded++
			continue
		}
		retried++
	}
	return
}

func (o *Outbox) Dump() {
	fmt.Printf("  %-8s %-9s %-12s %-8s %-7s %s\n", "todo", "target", "action", "attempt", "state", "last_err")
	for _, t := range o.tasks {
		fmt.Printf("  %-8s %-9s %-12s %-8d %-7s %s\n", t.TodoID, t.ID, t.Action, t.Attempt, t.State, t.LastErr)
	}
}

// =====================================================================
// 对账兜底
// =====================================================================

type ReportRow struct {
	Kind   string
	TodoID string
	Detail string
	Action string
}

func reconcile(o *Outbox, b *Business) []ReportRow {
	var rep []ReportRow
	for _, t := range o.tasks {
		switch t.State {
		case "delivered":
			continue
		case "dead":
			action := "查数据/契约（不可重试，重放也没用）"
			if strings.Contains(t.LastErr, "Unavailable") || strings.Contains(t.LastErr, "Conflict") {
				action = "人工确认服务已恢复后手工重放"
			}
			rep = append(rep, ReportRow{
				Kind:   "dead_letter",
				TodoID: t.TodoID,
				Detail: fmt.Sprintf("重试 %d 次仍失败：%s", t.Attempt, t.LastErr),
				Action: action,
			})
		default:
			rep = append(rep, ReportRow{
				Kind: "pending", TodoID: t.TodoID,
				Detail: "仍在重试中，未超限",
				Action: "不处理（还在退避窗口内）",
			})
		}
	}
	return rep
}

