	fmt.Println("     TS：  class WbError extends Error { kind: 'NotFound' }")
	fmt.Println("           if (e.kind === 'NotFound') { ... }")
	fmt.Println("     Go：  func (e *WbError) Error() string { ... }")
	fmt.Println("           var we *WbError")
	fmt.Println("           if errors.As(err, &we) && we.Kind == KindNotFound { ... }")
	fmt.Println("     ⚠ 坑：用 `err.(*WbError)` 直接断言会在 err 是别的类型时 panic。")
	fmt.Println("       必须用 errors.As —— 它沿包装链找。")
	fmt.Println("     ⚠ 坑：errors.Is / errors.As 要求传**指针的指针**（&we），")
	fmt.Println("       因为 errors.As 要给 we 赋值。写成 (we) 编译不过。")
	fmt.Println()
