	fmt.Println("         ctx, cancel := context.WithTimeout(ctx, 300*time.Millisecond)")
	fmt.Println("         defer cancel()   // ← 必须 defer，否则泄漏计时器")
	fmt.Println("     每个可能阻塞的调用第一个参数都是 ctx：")
	fmt.Println("         b.Apply(ctx, task)   而不是  b.Apply(task)")
