// =====================================================================
// W36 d17：calendar.todo.completed 的语义 —— 待办完成 vs 提醒触发。
//
// tech-plan §7.5 事件目录里有两个容易混的：
//   calendar.reminder.fired     calendar → homeos     {reminder_id}:{fire_date}
//   calendar.todo.completed     calendar → 来源面     {todo_id}
//
// 一个发通知，一个回写业务对象。搞混的后果是真事故：
// 把 reminder.fired 当成「完成」，等于用户没做任何事就把账单标成已缴。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 四个对象：Reminder / Todo / CalendarEvent / Notification
// =====================================================================

type Reminder struct {
	ID, SrcSystem, SrcID, Title, DueAt string
	Repeat                             string
	FiredAt                            string // 到点触发的时间
	FiredCount                         int
	NextFireDate                       string
	TodoID                             string // 关联的待办（可能有）
}

type Todo struct {
	ID, SrcSystem, SrcID, Title string
	DueAt                       string
	ReminderID                  string
	Completed                   bool
	CompletedAt                 string
	CompletedBy                 string
	WritebackDone               bool
	DoneReturnsTo               string
}

type Notification struct {
	ID, Type, Title, Target string // type=reminder
	Read                    bool
}

type Finance struct {
	Bills map[string]string // id → status
	log   []string
}

type HomeOS struct{ Notifs []*Notification }

func (f *Finance) MarkPaid(id string) {
	f.Bills[id] = "paid"
	f.log = append(f.log, "finance: "+id+" → paid")
}

func (h *HomeOS) OnFired(r *Reminder) {
	h.Notifs = append(h.Notifs, &Notification{
		ID:     "ntf-" + r.ID,
		Type:   "reminder",
		Title:  r.Title,
		Target: "calendar",
	})
}

// fireReminder 模拟 calendar 的调度器到点
func fireReminder(r *Reminder, cal *Calendar) {
	if r.DueAt == "" {
		return
	}
	r.FiredAt = "2026-03-05T09:00:00+08:00"
	r.FiredCount++
	// calendar.reminder.fired → homeos
	cal.hos.OnFired(r)
	// 周期提醒要算下一次（PRD：周期规则归 calendar）
	if r.Repeat == "monthly" {
		r.NextFireDate = "2026-04-05T09:00:00+08:00"
		r.DueAt = "2026-04-05T09:00:00+08:00"
	}
}

type Calendar struct {
	Reminders []*Reminder
	Todos     []*Todo
	hos       *HomeOS
	fin       *Finance
	Events    []string
}

func (c *Calendar) Fire(remID string) {
	for _, r := range c.Reminders {
		if r.ID == remID {
			fireReminder(r, c)
			c.Events = append(c.Events, "calendar.reminder.fired → homeos（落 Notification，分型 reminder）")
			return
		}
	}
}

// completeTodo 模拟用户在到期中心点完成
func (c *Calendar) completeTodo(todoID, memberID, at string) string {
	var t *Todo
	for _, x := range c.Todos {
		if x.ID == todoID {
			t = x
		}
	}
	if t == nil {
		return "待办不存在"
	}
	if t.Completed {
		return "已完成（幂等）"
	}
	t.Completed, t.CompletedAt, t.CompletedBy = true, at, memberID
	c.Events = append(c.Events, "calendar.todo.completed → "+t.SrcSystem+":"+t.SrcID)
	if t.DoneReturnsTo == "" {
		return "完成（无回写目标）"
	}
	parts := strings.Split(t.DoneReturnsTo, ":")
	if parts[2] == "mark_paid" && parts[0] == "finance" {
		c.fin.MarkPaid(parts[1])
		t.WritebackDone = true
		return "完成 + 回写成功"
	}
	return "完成"
}

func main() {
	fin := &Finance{Bills: map[string]string{"bill-001": "unpaid"}}
	hos := &HomeOS{}
	cal := &Calendar{hos: hos, fin: fin}

	cal.Reminders = []*Reminder{
		{ID: "rem-1", SrcSystem: "finance", SrcID: "bill-001", Title: "房贷 3 月期",
			DueAt: "2026-03-05T09:00:00+08:00", Repeat: "monthly"},
	}
	cal.Todos = []*Todo{
		{ID: "todo-1", SrcSystem: "finance", SrcID: "bill-001", Title: "房贷 3 月期（到期中心）",
			DueAt: "2026-03-05T09:00:00+08:00", ReminderID: "rem-1",
			DoneReturnsTo: "finance:bill-001:mark_paid"},
	}

	hdr("一、两个事件的语义差别：不是「同一条消息的两个类型」")

	type ev struct {
		name      string
		trigger   string
		consumer  string
		effect    string
		bizEffect string
	}
	evs := []ev{
		{"calendar.reminder.fired", "到点（调度器触发）", "homeos",
			"落 Notification（分型 reminder）→ 站内信 + push", "**无**（业务对象完全不动）"},
		{"calendar.todo.completed", "用户在到期中心点完成", "来源面（finance）",
