package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 全链路：注册 → 触发 → 完成 → 回写 → 失败兜底
// =====================================================================

type Bill struct {
	ID, Title, DueAt, Status, PaidAt, DeletedAt string
	AmountCents                                 int64
	Version                                     int
}

type Finance struct {
	Bills map[string]*Bill
	alive bool
	log   []string
}

type Todo struct {
	ID, SrcID, Title, DoneReturnsTo string
	Completed                       bool
	CompletedAt, CompletedBy        string
	WritebackState                  string // ok / failed_dead / missing
	Attempt                         int
}

type Notif struct{ ID, Type, Title string }

type HomeOS struct{ Notifs []*Notif }

type Cal struct {
	Reminders map[string]string // id → due_at
	Todos     map[string]*Todo
	hos       *HomeOS
	fin       *Finance
	Events    []string
	Idem      map[string]bool
}

func newStack() *Cal {
	fin := &Finance{Bills: map[string]*Bill{}, alive: true}
	return &Cal{
		Reminders: map[string]string{},
		Todos:     map[string]*Todo{},
		hos:       &HomeOS{},
		fin:       fin,
		Events:    []string{},
		Idem:      map[string]bool{},
	}
}

// 注册
func (c *Cal) Register(id, title, dueAt, doneReturnsTo string) {
	key := "finance|" + id + "|reminder"
	if _, dup := c.Idem[key]; dup {
		c.Events = append(c.Events, "幂等命中，丢弃重复注册 "+id)
		return
	}
	c.Idem[key] = true
	c.Reminders["rem-"+id] = dueAt
	c.Todos["todo-"+id] = &Todo{ID: "todo-" + id, SrcID: id, Title: title, DoneReturnsTo: doneReturnsTo}
	c.Events = append(c.Events, "finance.due.registered → 落 todo-"+id)
}

// 触发
func (c *Cal) Fire(remID, title string) {
	_, ok := c.Reminders[remID]
	if !ok {
		return
	}
	biz := c.Events[len(c.Events)-1]
	if strings.HasPrefix(biz, "fire:") {
		c.Events = append(c.Events, "幂等命中，本周期已触发过")
		return
	}
	c.Events = append(c.Events, "fire:"+remID)
	c.Events = append(c.Events, "calendar.reminder.fired → homeos（分型 reminder）")
	c.hos.Notifs = append(c.hos.Notifs, &Notif{ID: "ntf-" + remID, Type: "reminder", Title: title})
}

// 完成 + 回写
func (c *Cal) Complete(todoID, memberID, at string) string {
	t := c.Todos[todoID]
	if t == nil {
		return "404 待办不存在"
	}
	if t.Completed {
		return "幂等短路"
	}
	t.Completed, t.CompletedAt, t.CompletedBy = true, at, memberID
	if t.DoneReturnsTo == "" {
		t.WritebackState = "missing"
		c.Events = append(c.Events, "MISSING 回写丢失（done_returns_to 为空）")
		return "本地完成，回写丢失"
	}
	p := strings.Split(t.DoneReturnsTo, ":")
	// 幂等
	ik := "wb|" + t.DoneReturnsTo
	if c.Idem[ik] {
		return "回写幂等命中"
	}
	// 业务不可达
	if !c.fin.alive {
		t.Attempt++
		if t.Attempt >= 3 {
			t.WritebackState = "failed_dead"
			c.Events = append(c.Events, "DEAD 回写重试 3 次仍不可达")
			return "完成，回写进死信"
		}
		t.WritebackState = "retrying"
		return "完成，回写重试中"
	}
	b := c.fin.Bills[p[1]]
	if b == nil || b.DeletedAt != "" {
		t.WritebackState = "failed_dead"
		c.Events = append(c.Events, "DEAD NotFound 对象不存在/已软删")
		return "完成，回写死信（NotFound）"
	}
	b.Status = "paid"
	b.PaidAt = at
	b.Version++
	c.Idem[ik] = true
	t.WritebackState = "ok"
	c.Events = append(c.Events, "calendar.todo.completed → 回写 "+p[1]+" paid v"+itoa(b.Version))
	return "回写成功"
}

// RetryOnce 是重试队列的一轮。它绕过了 Complete 的幂等短路，
// 因为重试的是**同一个任务**，不是用户的新动作。
func (c *Cal) RetryOnce() string {
	t := c.Todos["todo-bill-002"]
	if t == nil || t.WritebackState != "retrying" {
		return "队列为空（已终态）"
	}
	t.Attempt++
	if t.Attempt >= maxWritebackAttempts {
		t.WritebackState = "failed_dead"
		c.Events = append(c.Events, "DEAD 回写重试次数用尽")
		return "队列重试 → 第 3 次尝试失败 → 次数用尽，进死信"
	}
	return fmt.Sprintf("队列重试 → 第 %d 次尝试失败 → 继续退避",
		t.Attempt)
}

// maxWritebackAttempts 是「用户那一次点击」总共允许的尝试次数上限。
// 第一次（用户点的）+ 最多 2 次队列重试 = 3 次，与 d16 的退避表一致。
const maxWritebackAttempts = 3

func tick(ok bool) string {
	return map[bool]string{true: "✅", false: "❌"}[ok]
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	s := ""
	for n > 0 {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	return s
}

