// =====================================================================
// W37 d19：跨面读取的三种方式 —— 只读 HTTP / 事件+投影 / 逻辑 id 引用。
//
// tech-plan §7.1 明确这是一个**封闭集合，且仅此三种**。
// PRD 16.4 后面那句定版 ㉚：「不得因 calendar 独立成面而新增第四种跨面形态」。
//
// 「封闭」的意思是：遇到一个跨面读取需求时，你只有三个选项，
// 不是三个选项加「实在不行就……」。今天把三个都跑一遍，
// 并演示「第四种形态」会长什么样、为什么会烂掉。
// =====================================================================

package main

import (
	"fmt"
	"strings"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 一个「场景」：首页要显示「今日到期 3 项 / 待缴 2 笔共 17284.26 元」
// 需要读 finance 的 Bill 与 calendar 的 Event（两个面）
// =====================================================================

type Need struct {
	scene        string
	dataFrom     []string
	freq         string
	renderCnt    int // 一天渲染多少次
	needRealtime bool
}

var needs = []Need{
	{"首页「今日到期」列表", []string{"calendar"}, "每次打开首页", 50, true},
	{"首页 finance 格子「待缴 2 笔」", []string{"finance"}, "每次打开首页", 50, true},
	{"首页状态句「本月结余 ¥1234」", []string{"finance"}, "每次打开首页", 50, false},
	{"详情页「这些提醒来自哪些账单」", []string{"finance"}, "点开时", 3, true},
	{"导出报表里的「已完成事项数」", []string{"calendar", "finance"}, "导出时", 1, false},
	{"推送通知的角标「3 条未读」", []string{"homeos"}, "收到推送时", 20, true},
}

// =====================================================================
// 三种方式
// =====================================================================

type Method struct {
	name    string
	rule    string
	canReal bool
	spec    string
}

var methods = []Method{
	{"① 只读 HTTP", "实时查询别人的数据", true,
		"超时 ≤300ms、重试 ≤1 次、必须声明降级、禁止跨 schema SQL"},
	{"② 事件 + 本地投影", "高频渲染他面数据", true,
		"投影表 {code}_proj_{来源域}，只允许本服务订阅器写，可随时重建；不在请求链路上 fan-out"},
	{"③ 逻辑 id 引用", "存对方的 id，展示时批量调", true,
		"只存 id，无物理外键、无跨 schema 约束；禁止存金额副本；孤儿进每日对账"},
}

// 伪第四种：跨 schema 直查
type FakeMethod struct{ name, why string }

var fakes = []FakeMethod{
	{"跨 schema SQL JOIN", "「我就查一下，又不改」—— 直到某天 finance 需要重构表名"},
	{"共用数据库账号", "省事，但三个 schema 的权限边界同时消失"},
	{"DBLink / 只读视图", "Postgres 没有原生 DBLink，于是大家开始「建个视图」"},
	{"把对方的表结构复制一份到本地表", "看起来像投影，但它没有事件驱动，会静默过期"},
	{"前端并行请求多个服务再拼装", "PRD 明令禁止：首页聚合必须由 home/summary 单请求承担"},
}

func main() {
	hdr("一、场景清单：先问「要不要读」，再问「怎么读」")

	fmt.Println("  下列每个需求都是真实的。关键是**它们不是同一种需求**，不能用同一种方式。")
	fmt.Printf("  %-32s %-20s %-16s %s\n", "需求", "数据来自", "频次", "要实时吗")
	fmt.Println("  " + strings.Repeat("-", 100))
	for _, n := range needs {
		fmt.Printf("  %-32s %-20s %-16s %s\n", n.scene, strings.Join(n.dataFrom, "+"),
			n.freq, map[bool]string{true: "是", false: "否"}[n.needRealtime])
	}
	fmt.Println()
	fmt.Println("  先看频次那一列：**一天 50 次 vs 一天 1 次，差了 50 倍。**")
	fmt.Println("  这一列决定你能不能在请求链路上同步调他面。")

	// =================================================================
	hdr("二、三种方式的判定（tech-plan §7.1）")
	// =================================================================
	for _, m := range methods {
		fmt.Printf("\n  【%s】%s\n", m.name, m.rule)
		fmt.Printf("    约束：%s\n", m.spec)
	}
	fmt.Println()
	fmt.Println("  三句话记忆：")
	fmt.Println("    ① 要**当下准确**、频次不高 → 只读 HTTP")
	fmt.Println("    ② 要**渲染密集** → 事件 + 本地投影（不要在请求链路上 fan-out）")
	fmt.Println("    ③ 要**引用**（金额、附件）→ 只存 id，禁止存副本")

	// =================================================================
	hdr("三、逐个场景判定：今天只能选这三种")
	// =================================================================
	type verdict struct {
		scene  string
		method string
		why    string
	}
	vs := []verdict{
		{"首页「今日到期」列表", "① 只读 HTTP",
			"必须当下准确（今天到期的东西变了就是错），且一天 50 次还能接受"},
		{"首页 finance 格子「待缴 2 笔」", "① 只读 HTTP",
			"同上。但 PRD 定版 ㉚ 说它属于 home/summary 的单请求 fan-out，不许前端拼"},
		{"首页状态句「本月结余」", "② 事件 + 本地投影",
			"PRD 14.5 第 7 项明文：首页状态句与角标由投影喂，读取链路走投影表"},
		{"详情页「这些提醒来自哪些账单」", "③ 逻辑 id 引用",
			"calendar 侧存的是 source_id（finance.bill_id），展示时批量调 finance 只读接口"},
		{"导出报表里的「已完成事项数」", "② 事件 + 本地投影",
			"导出要求离线可跑，不能依赖在线调用（d14 的错误方向 ③ 就是这个坑）"},
		{"推送通知的角标「3 条未读」", "本地状态，不跨面",
			"未读口径是 homeos 自己的（d14 的 owner 表），根本不需要读 calendar"},
	}
	fmt.Printf("  %-32s %-22s %s\n", "需求", "选的方式", "为什么")
	fmt.Println("  " + strings.Repeat("-", 112))
	for _, v := range vs {
		fmt.Printf("  %-32s %-22s %s\n", v.scene, v.method, v.why)
	}
	fmt.Println()
	fmt.Println("  注意「推送角标」那一行：**它不是三种方式之一，因为它是本面的数据**。")
	fmt.Println("  遇到跨面需求时，第一个问题应该是「能不能变成不需要跨面」。")

	// =================================================================
	hdr("四、伪第四种形态：它们为什么会烂掉")
	// =================================================================
	for _, f := range fakes {
		fmt.Printf("  ❌ %-42s %s\n", f.name, f.why)
	}
	fmt.Println()
	fmt.Println("  它们的共同特征：**看起来更快，但把「一致性」的责任推给了人。**")
	fmt.Println("  三种正式方式里，一致性由机制保证：")
	fmt.Println("    ① 只读 —— 每次都问对方，没有副本")
	fmt.Println("    ② 投影 —— 有事件驱动，有重建命令，有对账")
	fmt.Println("    ③ 逻辑 id —— 不存副本就不会漂移，完整性有对账兜")
	fmt.Println("  伪方式里，一致性靠「大家记得别乱改表」—— 这是最不可靠的一种保证。")

	// =================================================================
	hdr("五、方式 ① 只读 HTTP 的形状（本项目的真实实例）")
	// =================================================================
	fmt.Println("  PRD 定版 ㉚：")
	fmt.Println("    svc-homeos 的 home/summary 的 due_today 字段")
	fmt.Println("    由 svc-homeos 调 GET /api/calendar/events 获得")
	fmt.Println("    超时 ≤300ms、重试 ≤1 次、失败即降级为「今日区暂不可用」且保留到期入口")
	fmt.Println("    绝不跨 schema 直连 calendar 库")
	fmt.Println()
	fmt.Println("  调用链：")
	fmt.Println("    客户端 → GET /api/homeos/home/summary")
	fmt.Println("                ↓")
	fmt.Println("             svc-homeos")
	fmt.Println("                ├─ 本地查 homeos_notification 未读数（自己的数据，不跨面）")
	fmt.Println("                ├─ 调 GET /api/calendar/events?date=today（跨面，方式①）")
	fmt.Println("                │     身份：走 15.2 共用 SDK 鉴权，不是伪造 token")
