// =====================================================================
// W37 d20：只读接口的三个硬约束 —— 超时 ≤300ms、重试 ≤1 次、必须声明降级。
//
// PRD 16.4 给的三条判据：
//   「调用方必须设超时 ≤300ms、至多重试 1 次、并有降级展示」
//
// 「必须」两个字是重点：这不是最佳实践，是**判据**。
// 违反任一条 = 门禁红 = 阶段不通过。
//
// 今天要真跑出一个超时（不是模拟，是真的 context deadline exceeded），
// 办法是起一个真的 httptest server，handler 里 sleep 800ms。
// =====================================================================

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

// bucket 把耗时归到断言区间，让输出**跨运行确定**（CARD-GUIDE 要求双跑一致）。
// 真实耗时每次跑会有几十毫秒浮动，直接打印就无法 diff。
func bucket(d, target time.Duration) string {
	if d < target/2 {
		return "远小于上限（< 一半）"
	}
	if d < target+100*time.Millisecond {
		return "贴着上限（超时点附近）"
	}
	if d < 2*target {
		return "略超上限（<2×）"
	}
	return "远超过上限（≥2×）"
}

func mustJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func tick(ok bool) string {
	return map[bool]string{true: "✅ 通过", false: "❌ 失败"}[ok]
}

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

// =====================================================================
// 约束一：超时
// =====================================================================

const Timeout = 300 * time.Millisecond

// fetch 在超时内拿到数据 → ok
// 拿不到 → 降级。**永不 panic、永不阻塞超过 Timeout**。
func fetch(ctx context.Context, url string, tries int) (data []Event, degraded string, attempts int, elapsed time.Duration) {
	start := time.Now()
	client := &http.Client{} // 不设 client 级 Timeout，只靠 ctx（d20 后面讲为什么）
	// 重试至多 tries-1 次（tries=1 表示不重试，tries=2 表示重试 1 次）
	for i := 0; i < tries; i++ {
		attempts++
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
		if err != nil {
			return nil, "请求构造失败", attempts, time.Since(start)
		}
		resp, err := client.Do(req)
		if err == nil {
			body, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			if resp.StatusCode == http.StatusOK {
				var out []Event
				if json.Unmarshal(body, &out) == nil {
					return out, "", attempts, time.Since(start)
				}
				return nil, "响应体不是合法 JSON", attempts, time.Since(start)
			}
			return nil, fmt.Sprintf("HTTP %d", resp.StatusCode), attempts, time.Since(start)
		}
		// 最后一次失败就不再重试
		if i == tries-1 {
			// 判定错误性质，决定降级词
			if errors.Is(err, context.DeadlineExceeded) {
				return nil, "暂不可用", attempts, time.Since(start)
			}
			return nil, "暂不可用", attempts, time.Since(start)
		}
	}
	return nil, "暂不可用", attempts, time.Since(start)
}

type Event struct {
	ID    string `json:"id"`
	Title string `json:"title"`
	DueAt string `json:"due_at"`
	Kind  string `json:"kind"`
}

// =====================================================================
// 约束二：重试至多 1 次
// =====================================================================

// 为什么「至多 1 次」不是「尽量多重试几次」：
//  ① 请求链路在**用户的等待中**。300ms×3 = 900ms，用户已经觉得卡了。
//  ② 重试只在「可能立刻成功」时有意义（瞬时抖动）。
//     对端持续不可达时，重试只是把 1 个失败变成 N 个失败。
//  ③ 一次请求内 fan-out ≤1 个他服务；重试不改变 fan-out 数，但放大总量。
// 判据是「至多」，不是「至少」也不是「尽量」。

// =====================================================================
// 约束三：必须声明降级
// =====================================================================

// 四态降级词（tech-plan §7.6，不可混用）
type DegradeWord string

const (
	NotMounted  DegradeWord = "未启用"   // 本家庭没挂载这个面
	NotBorn     DegradeWord = "即将上线"  // 这个面还没出生
	Unavailable DegradeWord = "暂不可用"  // 面已启用，但本次服务不可达
	DepNotReady DegradeWord = "依赖未就绪" // 本面可用，但依赖的另一面没出生
)

type DueTodayBlock struct {
	State    DegradeWord
	Events   []Event
	EntryURL string // ★ 无论降级与否都必须有：到期入口
}

func main() {
	hdr("一、先看三条约束分别防住什么")

	type c struct {
		rule string
		kill string
	}
	cs := []c{
		{"超时 ≤300ms", "一个卡住的面把整个首页拖死。300ms 是「用户能感知到的等待」的量级上限"},
		{"重试 ≤1 次", "对端持续不可达时重试放大流量；对端已恢复时重试才是收益"},
		{"必须声明降级", "「拿不到」和「没有」在 UI 上长得一样时，用户会以为今天真的没事"},
	}
	for _, x := range cs {
		fmt.Printf("  【%s】\n    防住：%s\n", x.rule, x.kill)
	}

	// =================================================================
	hdr("二、真跑一次超时（server 故意 sleep 800ms，client ctx 300ms）")
	// =================================================================

	// 快服务：20ms 返回
	fast := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(20 * time.Millisecond)
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, `[
		  {"id":"ev-1","title":"房贷 3 月期","due_at":"2026-03-05T09:00:00+08:00","kind":"event"},
		  {"id":"ev-2","title":"物业费 Q1","due_at":"2026-03-05T10:00:00+08:00","kind":"event"}
		]`)
	}))
	defer fast.Close()

	// 慢服务：800ms 才返回（超过 300ms 上限）
	slow := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(800 * time.Millisecond)
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, `[{"id":"ev-9","title":"来晚了","due_at":"2026-03-05T09:00:00+08:00","kind":"event"}]`)
	}))
	defer slow.Close()

	fmt.Println("  两个 httptest server：")
	fmt.Println("    快 server：handler sleep 20ms 后返回 2 条事件")
	fmt.Println("    慢 server：handler sleep 800ms 后返回 1 条事件")
	fmt.Println("    （两个 httptest server 的端口每次运行都不同，所以这里只描述行为，不打印 URL ——")
	fmt.Println("      打印端口会让输出无法双跑对比）")
	fmt.Println()
	fmt.Printf("  client 侧：ctx, cancel := context.WithTimeout(parent, %v)\n", Timeout)

	// ---- 快的情况 ----
	fmt.Println()
	fmt.Println("  ▸ 场景一：calendar 正常（20ms 返回）")
	ctx, cancel := context.WithTimeout(context.Background(), Timeout)
	evs, deg, tries, el := fetch(ctx, fast.URL+"/api/calendar/events?date=2026-03-05", 1)
	cancel()
	fmt.Printf("    结果：%d 条事件，降级词=%q，尝试 %d 次\n", len(evs), deg, tries)
	fmt.Printf("    断言 A：拿到数据            → %s\n", tick(len(evs) == 2))
	fmt.Printf("    断言 B：无降级词            → %s\n", tick(deg == ""))
	fmt.Printf("    断言 C：耗时 %s      → %s\n", bucket(el, Timeout), tick(el < Timeout))
	fmt.Printf("    断言 D：尝试次数 = 1        → %s\n", tick(tries == 1))

	// ---- 超时的情况 ----
	fmt.Println()
	fmt.Println("  ▸ 场景二：calendar 慢（800ms 返回），超时真跑")
	ctx2, cancel2 := context.WithTimeout(context.Background(), Timeout)
	evs2, deg2, tries2, el2 := fetch(ctx2, slow.URL+"/api/calendar/events?date=2026-03-05", 1)
	cancel2()
	fmt.Printf("    结果：%d 条事件，降级词=%q，尝试 %d 次\n", len(evs2), deg2, tries2)
	fmt.Printf("    断言 A：降级词 = 暂不可用    → %s\n", tick(deg2 == "暂不可用"))
	fmt.Printf("    断言 B：确实等到了超时点     → %s（耗时 %s）\n",
		tick(el2 >= Timeout-50*time.Millisecond), bucket(el2, Timeout))
	fmt.Printf("    断言 C：没有等满 800ms       → %s\n", tick(el2 < 500*time.Millisecond))
	fmt.Printf("    断言 D：尝试次数 = 1        → %s\n", tick(tries2 == 1))
	fmt.Println()
	fmt.Println("    ★ 关于「真跑出超时」这件事要说清：")
	fmt.Println("      ctx 到点会返回 context.DeadlineExceeded，client 立刻放弃，")
	fmt.Println("      所以耗时落在 300ms 上下几十毫秒 —— 每次跑不一样。")
	fmt.Println("      因此输出里断言的是**关系**（< 400ms 且 ≥ 250ms、确实走了降级分支），")
	fmt.Println("      而不是「耗时 = 300ms」。这也是为什么超时测试只能断言区间。")
	fmt.Println("      本程序用 bucket() 把耗时压成三种稳定表述，保证双跑 diff 一致。")

	// =================================================================
	hdr("三、约束二：重试至多 1 次（真跑）")
	// =================================================================
	fmt.Println("  ▸ 场景三：重试 0 次 vs 重试 1 次，对同一个慢服务")
	for _, tries := range []int{1, 2, 3} {
		ctx3, cancel3 := context.WithTimeout(context.Background(), Timeout)
		_, deg3, t3, el3 := fetch(ctx3, slow.URL+"/api/calendar/events", tries)
		cancel3()
		fmt.Printf("    maxTries=%d → 实际尝试 %d 次，降级词=%q，总耗时 %s\n",
			tries, t3, deg3, bucket(el3, Timeout))
	}
	fmt.Println()
	fmt.Println("  读这张表：maxTries=3 时尝试 3 次，但总耗时仍然 ≈ 300ms 而不是 900ms。")
	fmt.Println("  为什么？因为**每一次重试共享同一个 ctx**：第一次把 300ms 用完了，")
	fmt.Println("  第二次直接拿到 DeadlineExceeded，立刻返回。")
	fmt.Println()
	fmt.Println("  这正是为什么约束一必须先于约束二理解：")
	fmt.Println("    ctx 是**总预算**，不是每次调用的预算。")
	fmt.Println("    如果每次重试都新建 ctx（context.Background() + 新的 WithTimeout），")
	fmt.Println("    那 3 次重试就是 900ms —— 约束①被绕过了。")

	// 真跑「错误写法」作对照
	fmt.Println()
	fmt.Println("  真跑一次「错误写法」：每次重试都新建 ctx")
	start := time.Now()
	total := 0
	for i := 0; i < 3; i++ {
		c, cancel := context.WithTimeout(context.Background(), Timeout)
		req, _ := http.NewRequestWithContext(c, http.MethodGet, slow.URL, nil)
		_, err := (&http.Client{}).Do(req)
		cancel()
		if err != nil {
			total++
		}
	}
	fmt.Printf("    3 次重试各自新建 ctx → 每轮真的等满超时，总耗时 %s ❌\n",
		bucket(time.Since(start), Timeout))
	fmt.Println("    结论：重试次数 ≤1 只是第二道防线，第一道是「ctx 共享」。")

	// =================================================================
	hdr("四、约束三：必须声明降级（四态不可混用）")
	// =================================================================
	fmt.Println("  tech-plan §7.6 的四态：")
	ws := []struct {
		w    DegradeWord
		mean string
	}{
		{NotMounted, "本家庭没挂载这个面（homeos_family_module 无行）"},
		{NotBorn, "这个面还没出生（服务不存在）"},
		{Unavailable, "面已启用，但本次服务不可达或分包校验失败"},
		{DepNotReady, "本面可用，但它依赖的另一面没出生"},
	}
	for _, x := range ws {
		fmt.Printf("    %-10s %s\n", x.w, x.mean)
	}
	fmt.Println()
	fmt.Println("  homeos 与 calendar **恒启用恒出生**，所以今天这个场景只能是「暂不可用」。")
	fmt.Println("  用错降级词的危害：")
	fmt.Println("    把 calendar 不可达写成「即将上线」→ 用户以为 App 没更新，去应用商店看版本")
	fmt.Println("    把没挂载写成「暂不可用」→ 用户以为系统坏了，去联系客服")
	fmt.Println("    这两种误判的排查成本，比故障本身高得多。")

	// =================================================================
	hdr("五、判据第 4 条的完整形态：降级时保留到期入口")
	// =================================================================
	fmt.Println("  PRD 定版 ㉚ 原文：「失败即降级为「今日区暂不可用」且保留到期入口」")
	fmt.Println()
	fmt.Println("  两种情况的响应体：")

	// 正常
	okBlock := DueTodayBlock{State: "", Events: evs, EntryURL: "/pages/calendar/index"}
	fmt.Printf("  ── 正常 ──\n  {\n  \"State\": \"\",\n  \"Events\": %s,\n  \"EntryURL\": %q\n  }\n", mustJSON(evs), okBlock.EntryURL)

	// 降级
	badBlock := DueTodayBlock{State: Unavailable, Events: []Event{}, EntryURL: "/pages/calendar/index"}
	fmt.Printf("  ── 降级 ──\n  {\n  \"State\": %q,\n  \"Events\": [],\n  \"EntryURL\": %q\n  }\n", string(badBlock.State), badBlock.EntryURL)
	fmt.Println()
	fmt.Println("  ★ 两个关键点：")
	fmt.Println("    ① Events 返 **空数组** 不是 null（Go 的坑：nil slice 序列化成 null）")
	fmt.Println("    ② EntryURL **无论降级与否都在** —— 这就是「保留到期入口」")
	fmt.Println()
	fmt.Println("  为什么必须保留入口：")
	fmt.Println("    用户点进去会看到什么？到期中心自己的页面。")
	fmt.Println("    如果 calendar 真的挂了，那个页面也会降级 —— 但用户至少知道「到期相关功能有问题」")
	fmt.Println("    而不是看到一个空洞的首页，怀疑整个 App 坏了。")
	fmt.Println("    更重要的是：**降级是暂时状态，入口是长期存在的**。")
	fmt.Println("    把入口藏起来，用户就失去了「服务恢复了吗」的唯一自查手段。")

	// =================================================================
	hdr("六、Go 的实现要点")
	// =================================================================
	fmt.Println("  ① 为什么不用 http.Client{Timeout: 300ms}")
	fmt.Println("     client.Timeout 会给整个 client 的所有请求设上限，")
	fmt.Println("     而你需要的是「这一次调用」的上限 —— 同一个 client 可能被复用到别处。")
	fmt.Println("     ctx 是按请求粒度的，这才是正确的位置。")
	fmt.Println()
	fmt.Println("  ② defer cancel() 必须写")
	fmt.Println("     ctx, cancel := context.WithTimeout(parent, 300*time.Millisecond)")
	fmt.Println("     defer cancel()   // ← 漏了会泄漏计时器，直到父 ctx 结束")
	fmt.Println("     在 for 循环里写 defer cancel() 是经典泄漏：循环 N 次泄漏 N 个计时器。")
	fmt.Println("     正确做法是把循环体抽成一个函数。")
	fmt.Println()
	fmt.Println("  ③ errors.Is(err, context.DeadlineExceeded) 与 errors.Is(err, context.Canceled)")
	fmt.Println("     两者不同：前者是超时（重试有意义），后者是上游主动取消（不该重试）。")
	fmt.Println("     ⚠ 超时发生后，即使对端其实已经准备好了，我们也只能放弃 ——")
	fmt.Println("       context 一旦 Done，不能复活。所以「超时」永远是丢弃，不是「再等等」。")
	fmt.Println()
	fmt.Println("  ④ 用 errgroup 可以让多个并发调用共享一个 ctx")
	fmt.Println("     但本项目**禁止** fan-out 多个他服务（tech-plan §7.1），")
	fmt.Println("     所以单次只有一个跨面调用，errgroup 用不上。")
	fmt.Println("     如果哪天真的要并发两路，那要先过架构评审。")
	fmt.Println()
	fmt.Println("  ⑤ 判超时不能靠 time.Since")
	fmt.Println("     ❌ if time.Since(start) > 300*time.Millisecond { degrade() }")
	fmt.Println("        问题：这只是「事后发现」，连接已经挂着，资源没释放。")
	fmt.Println("     ✅ ctx 超时会**主动取消**请求，释放连接与 goroutine。")
	fmt.Println("     time.Since 只能用来**记录指标**，不能用来**做决策**。")

	// =================================================================
	hdr("七、三条约束的可验证形式（写进 CI 门禁）")
	// =================================================================
	type gate struct {
		rule string
		how  string
	}
	gates := []gate{
		{"超时 ≤300ms", "每个跨面调用点必须有 ctx, cancel := context.WithTimeout(..., 300*time.Millisecond)"},
		{"重试 ≤1 次", "代码里不存在对跨面调用的 for 循环重试；或者循环上界写死为 2"},
		{"必须声明降级", "调用点的返回值里必须有 DegradeWord 字段，且没有任何分支返回空串而不带 Events"},
	}
	for _, g := range gates {
		fmt.Printf("  ▸ %s\n    怎么验：%s\n", g.rule, g.how)
	}
	fmt.Println()
	fmt.Println("  这三条之所以能进门禁，是因为它们都是**结构性的**：")
	fmt.Println("    - 有没有 ctx → grep 得到")
	fmt.Println("    - 有没有循环重试 → grep 得到")
	fmt.Println("    - 有没有降级字段 → 类型检查得到")
	fmt.Println("  「必须」和「建议」的区别就在这里：")
	fmt.Println("    建议写不进门禁，三个月后就没人记得；必须能进门禁，违反就红。")

	fmt.Println("\n=== W37 d20 到此结束 ===")
	fmt.Println("明天把三条约束用起来：首页 due_today 聚合，真跑出超时与降级的完整响应体。")
}

// =====================================================================
// W37 d21：首页 due_today 的聚合 —— 真跑出超时与降级。
//
// PRD 定版 ㉚：
//   首页 home/summary 的 due_today 由 svc-homeos 调 GET /api/calendar/events
//   （超时 ≤300ms、重试 ≤1 次、失败即降级为「今日区暂不可用」且保留到期入口）
//   绝不跨 schema 直连 calendar 库
//
// 本程序起三个真的 httptest server：
//   1. svc-homeos   —— 它就是本程序的一部分（handler）
//   2. svc-calendar —— 正常时 20ms 返回；故障时 800ms 或直接不监听
// 然后真的打一个 HTTP 请求到 svc-homeos，看它返回的 JSON。
// =====================================================================

package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"sort"
	"strings"
	"time"
)

func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func tick(ok bool) string {
	return map[bool]string{true: "✅ 通过", false: "❌ 失败"}[ok]
}

// =====================================================================
// 契约
// =====================================================================

type Event struct {
	ID        string `json:"id"`
	Title     string `json:"title"`
	DueAt     string `json:"due_at"`
	Kind      string `json:"kind"`
	SrcSystem string `json:"src_system"`
	SrcID     string `json:"src_id"`
}

// DueTodayBlock 是 home/summary 里 due_today 的形状。
// ★ State 是必填的（不是 omitempty）：空串 = 正常，非空 = 降级。
// ★ Events 永远返回数组，不返回 null。
// ★ EntryURL 永远存在 —— 这就是「保留到期入口」。
type DueTodayBlock struct {
	State    DegradeWord `json:"state"`
	Events   []Event     `json:"events"`
	EntryURL string      `json:"entry_url"`
	// Measured 是本程序的观测用字段，真实接口不返回（延迟只在服务端日志里）
	Measured string `json:"-"`
}

type DegradeWord string

const (
	NotMounted  DegradeWord = "未启用"
	NotBorn     DegradeWord = "即将上线"
	Unavailable DegradeWord = "暂不可用"
	DepNotReady DegradeWord = "依赖未就绪"
)

type Summary struct {
	FamilyID string        `json:"family_id"`
	Unread   int           `json:"unread"`
	DueToday DueTodayBlock `json:"due_today"`
}

// =====================================================================
// svc-homeos 的实现（本程序扮演它）
// =====================================================================

const Timeout = 300 * time.Millisecond

type HomeOS struct {
	// calendarBaseURL 是配的地址（svc-homeos 不知道 calendar 是死是活）
	calendarBaseURL string
	notif           *NotificationStore
}

type NotificationStore struct{ Unread int }

func (h *HomeOS) summaryHandler(w http.ResponseWriter, r *http.Request) {
	blk := h.buildDueToday(r.Context())
	resp := Summary{FamilyID: "fam-001", Unread: h.notif.Unread, DueToday: blk}
	w.Header().Set("Content-Type", "application/json")
	b, _ := json.MarshalIndent(resp, "", "  ")
	_, _ = io.WriteString(w, string(b))
}

// buildDueToday 是今天的主角。
// 入参是上游请求的 ctx：子 ctx 从它派生，这样客户端断开时下游也立刻取消。
func (h *HomeOS) buildDueToday(parent context.Context) DueTodayBlock {
	blk := DueTodayBlock{
		// ★ 无论成败都保留入口
		EntryURL: "/pages/calendar/index",
		// ★ 无论成败 Events 都是空数组，绝不是 null
		Events: []Event{},
	}
	// 约束一：ctx 300ms
	ctx, cancel := context.WithTimeout(parent, Timeout)
	defer cancel() // ★ 必须 defer
	// 约束二：至多重试 1 次 → tries=2
	evs, err := h.callCalendar(ctx)
	if err == nil {
		blk.Events = evs // State 保持空串 = 正常
		return blk
	}
	// 约束三：必须声明降级
	blk.State = classify(err)
	return blk
}

func classify(err error) DegradeWord {
	// homeos 与 calendar 恒启用恒出生，所以这里只可能是「暂不可用」
	if errors.Is(err, context.DeadlineExceeded) {
		return Unavailable
	}
	if errors.Is(err, context.Canceled) {
		return Unavailable
	}
	// connection refused / no such host
	var ne net.Error
	if errors.As(err, &ne) {
		return Unavailable
	}
	return Unavailable
}

func (h *HomeOS) callCalendar(ctx context.Context) ([]Event, error) {
	var lastErr error
	for i := 0; i < 2; i++ { // 至多重试 1 次
		req, err := http.NewRequestWithContext(ctx, http.MethodGet,
			h.calendarBaseURL+"/api/calendar/events?date=2026-03-05&family_id=fam-001", nil)
		if err != nil {
			return nil, err
		}
		resp, err := (&http.Client{}).Do(req)
		if err != nil {
			lastErr = err
			continue // 共享同一个 ctx，第二次会立刻拿到 DeadlineExceeded
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			return nil, fmt.Errorf("calendar 返回 HTTP %d", resp.StatusCode)
		}
		var out []Event
		if err := json.NewDecoder(resp.Body).Decode(&out); err != nil {
			return nil, err
		}
		return out, nil
	}
	return nil, lastErr
}

