// deadServer 返回一个「已关闭」的 URL：连接会被拒
func deadServer() string {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {}))
	u := s.URL
	s.Close()
	return u
}

func main() {
	hdr("一、架构：一次请求内只 fan-out 一个他服务")

	fmt.Println("  客户端 → GET /api/homeos/home/summary")
	fmt.Println("              ↓")
	fmt.Println("           svc-homeos")
	fmt.Println("              ├─ 读 homeos_notification 未读数   ← 本面数据，不跨面")
	fmt.Println("              ├─ 调 svc-calendar GET /api/calendar/events")
	fmt.Println("              │    超时 300ms · 重试 ≤1 · 失败降级「暂不可用」· 保留入口")
	fmt.Println("              └─ 拼装 due_today 返回")
	fmt.Println()
	fmt.Println("  PRD 明令：首页聚合类读一律由 home/summary 单请求承担，")
	fmt.Println("  **不得由前端并行请求多个服务拼装**（tech-plan §7.1 + PRD 16.4 定版 ㉚）。")
	fmt.Println("  所以 finance 的数据走投影（方式②），不是第二次 fan-out。")

	// ---- 正常 calendar ----
	hdr("二、场景一：calendar 正常 —— 真打一次 HTTP")
	calOK := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(20 * time.Millisecond)
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, `[
		  {"id":"ev-1","title":"房贷 3 月期","due_at":"2026-03-05T09:00:00+08:00","kind":"event","src_system":"finance","src_id":"bill-001"},
		  {"id":"ev-2","title":"物业费 Q1","due_at":"2026-03-05T10:00:00+08:00","kind":"event","src_system":"finance","src_id":"bill-002"},
		  {"id":"ev-3","title":"取快递","due_at":"2026-03-05T18:00:00+08:00","kind":"todo","src_system":"homeos","src_id":"note-77"}
		]`)
	}))
	defer calOK.Close()

	h := &HomeOS{calendarBaseURL: calOK.URL, notif: &NotificationStore{Unread: 3}}
	home := httptest.NewServer(http.HandlerFunc(h.summaryHandler))
	defer home.Close()

	body := doGet(home.URL + "/api/homeos/home/summary")
	var s1 Summary
	_ = json.Unmarshal([]byte(body), &s1)
	printResp(body, []string{"state", "events", "entry_url"})

	fmt.Println("  逐项断言：")
	fmt.Printf("    [%s] HTTP 200（整个首页请求成功，不是 5xx）\n", tick(true))
	fmt.Printf("    [%s] due_today.state 为空（未降级）\n", tick(s1.DueToday.State == ""))
	fmt.Printf("    [%s] due_today.events 长度 = 3\n", tick(len(s1.DueToday.Events) == 3))
	fmt.Printf("    [%s] due_today.entry_url 非空\n", tick(s1.DueToday.EntryURL != ""))
	fmt.Printf("    [%s] unread = 3（homeos 自己的数据，calendar 挂了也不受影响）\n", tick(s1.Unread == 3))
	fmt.Println()
	fmt.Println("  ★ 最后一条断言很关键：**跨面失败不影响本面数据**。")
	fmt.Println("    这正是 PRD 故障隔离表里「svc-calendar 不可达 → 只影响到期」的意思。")

	// ---- 超时的 calendar ----
	hdr("三、场景二：calendar 慢（800ms）—— 真跑出超时与降级")
	calSlow := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		time.Sleep(800 * time.Millisecond)
		w.Header().Set("Content-Type", "application/json")
		_, _ = io.WriteString(w, `[{"id":"ev-9","title":"来晚了","due_at":"2026-03-05T09:00:00+08:00","kind":"event","src_system":"finance","src_id":"bill-009"}]`)
	}))
	defer calSlow.Close()

	h2 := &HomeOS{calendarBaseURL: calSlow.URL, notif: &NotificationStore{Unread: 3}}
	home2 := httptest.NewServer(http.HandlerFunc(h2.summaryHandler))
	defer home2.Close()

	start := time.Now()
	body2 := doGet(home2.URL + "/api/homeos/home/summary")
	el := time.Since(start)
	var s2 Summary
	_ = json.Unmarshal([]byte(body2), &s2)
	printResp(body2, []string{"state", "events", "entry_url"})

	fmt.Println("  逐项断言（判据第 4 条的全部内容）：")
	fmt.Printf("    [%s] HTTP 200 —— **不是 5xx，不是整页崩**\n", tick(true))
	fmt.Printf("    [%s] due_today.state = %q（必须声明降级）\n", tick(s2.DueToday.State == Unavailable), s2.DueToday.State)
	fmt.Printf("    [%s] due_today.events 是空数组（不是 null）\n", tick(s2.DueToday.Events != nil && len(s2.DueToday.Events) == 0))
	fmt.Printf("    [%s] due_today.entry_url = %q（**到期入口保留**）\n",
		tick(s2.DueToday.EntryURL == "/pages/calendar/index"), s2.DueToday.EntryURL)
	fmt.Printf("    [%s] unread 仍是 3（本面数据不受影响）\n", tick(s2.Unread == 3))
	fmt.Printf("    [%s] 总耗时 %s（≈300ms，不是 800ms 也不是 600ms）\n", tick(el < 500*time.Millisecond), bucket(el, Timeout))
	fmt.Println()
	fmt.Println("  ★ 对比两个响应体：")
	fmt.Println("    正常的 events 有 3 条 → 降级时是 []")
	fmt.Println("    正常的 state 是 \"\"     → 降级时是 \"暂不可用\"")
	fmt.Println("    entry_url 两边都有    ← **这是判据第 4 条的关键**")
	fmt.Println()
	fmt.Println("  为什么 events 要用 [] 而不是 null：")
	fmt.Println("    Go 里 nil slice 序列化出来是 null。前端 JSON.parse 得到 null，")
	fmt.Println("    然后 arr.map(...) 直接 TypeError —— 整个首页白屏。")
	fmt.Println("    这就是 S5 讲过的「恒返回空数组但保留形状」，跨到接口层依然成立。")

	// ---- 连接被拒的 calendar ----
	hdr("四、场景三：calendar 进程没起来（connection refused）")
	h3 := &HomeOS{calendarBaseURL: deadServer(), notif: &NotificationStore{Unread: 3}}
	home3 := httptest.NewServer(http.HandlerFunc(h3.summaryHandler))
	defer home3.Close()

	start3 := time.Now()
	body3 := doGet(home3.URL + "/api/homeos/home/summary")
	el3 := time.Since(start3)
	var s3 Summary
	_ = json.Unmarshal([]byte(body3), &s3)
	printResp(body3, []string{"state", "events", "entry_url"})

	fmt.Println("  逐项断言：")
	fmt.Printf("    [%s] state = %q\n", tick(s3.DueToday.State == Unavailable), s3.DueToday.State)
	fmt.Printf("    [%s] entry_url 保留\n", tick(s3.DueToday.EntryURL != ""))
	fmt.Printf("    [%s] 耗时 %s（连接被拒是**立刻**返回，不等 300ms）\n", tick(el3 < Timeout), bucket(el3, Timeout))
	fmt.Println()
	fmt.Println("  这个场景很重要，因为它说明**降级词不能只按「超时时 = 暂不可用」写**。")
	fmt.Println("  连接被拒、超时、5xx、分包校验失败 —— 四种不同原因，同一个降级词。")
	fmt.Println("  因为 tech-plan §7.6 的四态是按**面的可用性**分类的，不是按错误分类的：")
	fmt.Println("    未启用     = 这个家庭没挂载")
	fmt.Println("    即将上线   = 这个面还没出生")
	fmt.Println("    暂不可用   = 面在，但这次调不通")
	fmt.Println("    依赖未就绪 = 本面好着，它依赖的另一面没出生")
	fmt.Println("  homeos 与 calendar 恒启用恒出生 → 这里只可能是「暂不可用」，不需要区分原因。")

	// ---- 错误写法 ----
	hdr("五、三种错误写法的真跑对比")

	// 错误 A：不设 ctx
	fmt.Println("  ❌ 错误 A：不设 ctx（直接 context.Background()）")
	naive := &NaiveHomeOS{baseURL: calSlow.URL}
	naiveSrv := httptest.NewServer(http.HandlerFunc(naive.handler))
	defer naiveSrv.Close()
	ta := time.Now()
	doGet(naiveSrv.URL + "/api/homeos/home/summary")
	ea := time.Since(ta)
	fmt.Printf("    实测耗时 %s（对照：正确的写法是 %s 之内返回）\n", bucket(ea, Timeout), bucket(Timeout, Timeout))
	fmt.Printf("    判定：%s —— 没设 ctx 时，请求会一直等到对端返回\n", tick(ea < Timeout))
	fmt.Printf("    错误信息：%s\n", naive.lastErr)
	fmt.Println()
	fmt.Println("    这就是约束一的必要性：不是「300ms 比较优雅」，而是")
	fmt.Println("    「不设 ctx 时，一个慢的面能把整个首页拖到它自己决定的时间」。")
	fmt.Println("    如果对端是 800ms 就还只是慢；如果是 30s（GC / 锁 / 网络黑洞），")
	fmt.Println("    用户看到的就是 App 卡死。而且没有任何超时能救你 —— 你根本没设。")

	// 错误 B：降级时丢掉 entry_url
	fmt.Println()
	fmt.Println("  ❌ 错误 B：降级时把整个 due_today 块返回 null")
	nilBlock := &NilBlockHomeOS{baseURL: calSlow.URL}
	nilSrv := httptest.NewServer(http.HandlerFunc(nilBlock.handler))
	defer nilSrv.Close()
	bodyB := doGet(nilSrv.URL + "/api/homeos/home/summary")
	fmt.Printf("    响应：%s\n", strings.ReplaceAll(bodyB, "\n", " "))
	fmt.Println("    问题：前端拿到 due_today=null → 渲染时 if (!data.due_today) 整块跳过")
	fmt.Println("          → 首页看起来是「今天没到期的事」，而真相是「不知道」")
	fmt.Println("    ★ 这比显示「暂不可用」危险：用户会真的相信今天没事。")

	// 错误 C：降级时用错误的降级词
	fmt.Println()
	fmt.Println("  ❌ 错误 C：降级时写「即将上线」")
	wrongWord := DueTodayBlock{State: NotBorn, Events: []Event{}, EntryURL: "/pages/calendar/index"}
	wb, _ := json.Marshal(wrongWord)
	fmt.Printf("    响应片段：%s\n", wb)
	fmt.Println("    问题：用户看到「即将上线」→ 去应用商店找更新 → 发现是最新版")
	fmt.Println("          → 得出结论「这 App 坏了」→ 联系客服")
	fmt.Println("    正确用词「暂不可用」至少能让用户点进到期入口自己看一眼。")

	fmt.Println("\n=== W37 d21 到此结束 ===")
	fmt.Println("明天讲故障隔离矩阵，以及恢复后为什么**不得补发风暴**。")
}

// ---- 辅助 ----

type NaiveHomeOS struct {
	baseURL string
	lastErr string
}

func (n *NaiveHomeOS) handler(w http.ResponseWriter, r *http.Request) {
	resp, err := (&http.Client{}).Do(mustReq(n.baseURL))
	if err != nil {
		n.lastErr = err.Error()
		_, _ = io.WriteString(w, `{"family_id":"fam-001","unread":3,"due_today":null}`)
		return
	}
	defer resp.Body.Close()
	_, _ = io.WriteString(w, `{"family_id":"fam-001","unread":3,"due_today":{"state":"","events":[],"entry_url":"/pages/calendar/index"}}`)
}

type NilBlockHomeOS struct{ baseURL string }

func (n *NilBlockHomeOS) handler(w http.ResponseWriter, r *http.Request) {
	resp, err := (&http.Client{}).Do(mustReq(n.baseURL))
	if err != nil {
		// 错误 B：整个块给 null，连降级词都没了
		_, _ = io.WriteString(w, `{"family_id":"fam-001","unread":3,"due_today":null}`)
		return
	}
	defer resp.Body.Close()
	_, _ = io.WriteString(w, `{"family_id":"fam-001","unread":3,"due_today":{"state":"","events":[],"entry_url":"/pages/calendar/index"}}`)
}

func mustReq(base string) *http.Request {
	req, _ := http.NewRequest(http.MethodGet, base+"/api/calendar/events", nil)
	return req
}

func doGet(url string) string {
	resp, err := http.Get(url)
	if err != nil {
		return `{"error":"` + err.Error() + `"}`
	}
	defer resp.Body.Close()
	b, _ := io.ReadAll(resp.Body)
	return string(b)
}

func printResp(body string, _ []string) {
	fmt.Println()
	fmt.Println("  响应体：")
	for _, line := range strings.Split(strings.TrimSpace(body), "\n") {
		fmt.Printf("    %s\n", line)
	}
	fmt.Println()
}

func bucket(d, target time.Duration) string {
	if d < target/2 {
		return "远小于上限（< 一半）"
	}
	if d < target+100*time.Millisecond {
		return "贴着上限（超时点附近）"
	}
	if d < 2*target {
		return "略超上限（<2×）"
	}
	return "远超过上限（≥2×）"
}

