// 二、补发风暴
// =====================================================================

type Reminder struct {
	ID, Title, DueAt string
	Pending          bool
}

type Notification struct {
	ID, Type, Title string
	SentAt          string
}

type System struct {
	Reminders []*Reminder
	Notifs    []*Notification
	// 运行中吗
	up bool
	// 每个用户今天收到的推送条数
	pushPerUser map[string]int
}

// fireDue 是调度器：到点就发通知
func (s *System) fireDue(day string) int {
	fired := 0
	for _, r := range s.Reminders {
		if !s.up || !r.Pending || r.DueAt != day {
			continue
		}
		s.Notifs = append(s.Notifs, &Notification{
			ID: "ntf-" + r.ID, Type: "reminder", Title: r.Title, SentAt: day + "T09:00:00+08:00",
		})
		r.Pending = false
		s.pushPerUser["mem-001"]++
		fired++
	}
	return fired
}

// stormRecover 是「恢复后补发」的实现：扫所有 pending 的历史提醒，全发一遍
func (s *System) stormRecover() int {
	fired := 0
	for _, r := range s.Reminders {
		if !s.up || !r.Pending {
			continue
		}
		s.Notifs = append(s.Notifs, &Notification{
			ID: "ntf-" + r.ID, Type: "reminder", Title: r.Title, SentAt: "恢复时刻",
		})
		r.Pending = false
		s.pushPerUser["mem-001"]++
		fired++
	}
	return fired
}

// smartRecover 是「正确」的恢复：不补发，只处理还没过期的
func (s *System) smartRecover(today string) (sent, skipped int) {
	for _, r := range s.Reminders {
		if !s.up || !r.Pending {
			continue
		}
		if r.DueAt < today {
			r.Pending = false
			skipped++
			continue
		}
		s.Notifs = append(s.Notifs, &Notification{
			ID: "ntf-" + r.ID, Type: "reminder", Title: r.Title, SentAt: "恢复时刻",
		})
		r.Pending = false
		s.pushPerUser["mem-001"]++
		sent++
	}
	return
}

