func hdr(s string) {
	fmt.Printf("\n%s\n%s\n", s, strings.Repeat("=", len(s)))
}

func tick(ok bool) string { return map[bool]string{true: "✅ 通过", false: "❌ 失败"}[ok] }

// =====================================================================
// 被测系统的最小实现（复刻 d5/d7/d15/d21 的关键部分）
// =====================================================================

type Key struct{ Sys, ID, Kind string }

type CalRow struct {
	From, ID, Kind, Title, DueAt string
	Active                       bool
	Reason                       string
}

type System struct {
	Rows     []*CalRow
	finState map[string]string
	wh       map[string]DoneFn
	idem     map[string]bool
}

type DoneFn func(id, at string) error

func newSystem() *System {
	return &System{finState: map[string]string{}, wh: map[string]DoneFn{}, idem: map[string]bool{}}
}

func (s *System) Register(sys, id, kind, title, dueAt string) bool {
	k := Key{sys, id, kind}
	for _, r := range s.Rows {
		if (Key{r.From, r.ID, r.Kind}) == k {
			return false // 幂等命中
		}
	}
	s.Rows = append(s.Rows, &CalRow{From: sys, ID: id, Kind: kind, Title: title, DueAt: dueAt, Active: true})
	return true
}

func (s *System) Revoke(sys, id, kind, reason string) bool {
	for _, r := range s.Rows {
		if r.From == sys && r.ID == id && r.Kind == kind && r.Active {
			r.Active, r.Reason = false, reason
			return true
		}
	}
	return false
}

func (s *System) CountActive() int {
	n := 0
	for _, r := range s.Rows {
		if r.Active {
			n++
		}
	}
	return n
}

func (s *System) RegisterWriteback(action string, fn DoneFn) { s.wh[action] = fn }

func (s *System) CompleteTodo(id, doneReturnsTo, at string) (string, error) {
	parts := strings.Split(doneReturnsTo, ":")
	if len(parts) != 3 {
		return "", fmt.Errorf("done_returns_to 格式错误")
	}
	action := parts[2]
	ik := doneReturnsTo
	if s.idem[ik] {
		return "idempotent", nil
	}
	fn, ok := s.wh[action]
	if !ok {
		return "", fmt.Errorf("action 未注册: %s", action)
	}
	if err := fn(parts[1], at); err != nil {
		return "", err
	}
	s.idem[ik] = true
	return "ok", nil
}

