// ---- 判据 4 用的 summary builder ----

type summaryBuilder struct {
	calURL string
	unread int
}

func (s *summaryBuilder) handler(w http.ResponseWriter, r *http.Request) {
	state := ""
	events := []json.RawMessage{}
	ctx, cancel := context.WithTimeout(r.Context(), 300*time.Millisecond)
	defer cancel()
	req, _ := http.NewRequestWithContext(ctx, http.MethodGet, s.calURL, nil)
	resp, err := (&http.Client{}).Do(req)
	if err == nil {
		resp.Body.Close()
		events = []json.RawMessage{json.RawMessage(`{"id":"ev-1"}`)}
	}
	if err != nil {
		state = "暂不可用"
		events = []json.RawMessage{}
	}
	out := map[string]any{
		"family_id": "fam-001",
		"unread":    s.unread,
		"due_today": map[string]any{
			"state":     state,
			"events":    events,
			"entry_url": "/pages/calendar/index",
		},
	}
	w.Header().Set("Content-Type", "application/json")
	b, _ := json.Marshal(out)
	_, _ = io.WriteString(w, string(b))
}

func bucket(d, target time.Duration) string {
	if d < target/2 {
		return "远小于上限"
	}
	if d < target+100*time.Millisecond {
		return "贴着上限（超时点附近）"
	}
	if d < 2*target {
		return "略超上限"
	}
	return "远超过上限"
}
